START TRANSACTION;
INSERT INTO questions (id, stem, options, answer, analysis, label_id, difficulty, source)
VALUES
    (500001, '杂合子Aa连续自交n代后，后代中杂合子所占的比例以及纯合子所占的比例分别为（ ）', 'A. 1/2^n ； 1 - 1/2^n
B. 1/2^n ； 1/2^n
C. 1 - 1/2^n ； 1/2^n
D. (1/2)^n ； (1/2)^n', 'A', '杂合子Aa自交1代后，杂合子比例变为1/2；自交2代后，杂合子比例变为1/4。由此递推，连续自交n代后，后代中杂合子所占的比例为(1/2)^n，即1/2^n。纯合子所占比例为 1 - 1/2^n。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500002, '某植物的花色由两对独立遗传的等位基因控制。现有一株红花植株自交，子代中红花：白花 = 15:1。据此推测，该红花亲本的基因型精确定位为（ ）', 'A. AaBb
B. Aabb
C. aaBb
D. AABB', 'A', '子代红花：白花 = 15:1 是双杂合子自交后代 9:3:3:1 的典型变式（9+3+3=15），说明只要基因组中含有一个显性基因（A_B_、A_bb、aaB_）就表现为红花，只有双隐性纯合个体（aabb）表现为白花。因此，该红花亲本的基因型必然是双杂合子AaBb。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500003, '关于哺乳动物精子和卵细胞形成过程的叙述，错误的是（ ）', 'A. 精子形成过程需要经过变形阶段，而卵细胞不需要
B. 一个精原细胞可产生4个精子，而一个卵原细胞只产生1个卵细胞
C. 精子形成过程中细胞质均等分配，卵细胞形成过程中细胞质均不均等分配
D. 减数分裂Ⅰ后期，精子和卵细胞的形成过程均会发生同源染色体的分离', 'C', '在卵细胞形成过程中，初级卵母细胞（减数分裂Ⅰ后期）和次级卵母细胞（减数分裂Ⅱ后期）细胞质的分裂是不均等的，但是第一极体在进行减数分裂Ⅱ后期时细胞质的分裂是均等的。因此C项表述过于绝对。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500004, '家鸡的性别决定方式为ZW型。家鸡的芦花羽毛（B）对非芦花羽毛（b）为显性，基因位于Z染色体上。现要通过羽毛特征直接在早期鉴别出雏鸡的雌雄，应选择的亲本杂交组合是（ ）', 'A. 芦花雌鸡 × 芦花雄鸡
B. 非芦花雌鸡 × 芦花雄鸡
C. 芦花雌鸡 × 非芦花雄鸡
D. 非芦花雌鸡 × 非芦花雄鸡', 'C', '选择芦花雌鸡（ZBW）与非芦花雄鸡（ZbZb）杂交，后代中的雄鸡基因型全部为ZBZb（表现为芦花羽毛），雌鸡基因型全部为ZbW（表现为非芦花羽毛）。这样在雏鸡刚孵化时，就可以根据羽毛特征直接鉴别出雌雄。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500005, '艾弗里的肺炎链球菌体外转化实验和赫尔希、蔡斯的噬菌体侵染大肠杆菌实验，在实验设计思路上的共同核心点是（ ）', 'A. 均利用放射性同位素标记法来追踪物质的变化
B. 均采用电子显微镜直接观察物质的进入过程
C. 设法把DNA和蛋白质等物质分开，单独地、直接地观察它们的作用
D. 均通过加热杀死的手段破坏蛋白质的活性', 'C', '两经典实验的共同最核心设计思路是：想办法将DNA与蛋白质等其他成分分离开来，单独地、直接地去观察它们各自在遗传中的生物效应。艾弗里实验没有使用同位素标记。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500006, '一个含有200个碱基的双链DNA分子，其中腺嘌呤（A）占20%。该DNA分子在含14N的培养基中连续复制数次后，共消耗了游离的胞嘧啶（C）脱氧核苷酸420个。则该DNA分子共复制了（ ）', 'A. 2次
B. 3次
C. 4次
D. 5次', 'B', '双链DNA中A=20%，根据碱基互补配对原则，C = 50% - 20% = 30%，因此该DNA分子中含有C = 200 × 30% = 60个。设复制了n次，消耗游离C的计算公式为：60 × (2^n - 1) = 420，解得 2^n - 1 = 7，即 2^n = 8，n = 3次。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500007, '下列关于密码子、反密码子和氨基酸之间关系的叙述，正确的是（ ）', 'A. 每种氨基酸都由多种密码子决定
B. 同一种反密码子可以转运多种氨基酸
C. 密码子的特殊排列顺序决定了蛋白质的特异性
D. mRNA上的密码子由tRNA上的反密码子转录而来', 'C', '部分氨基酸（如甲硫氨酸、色氨酸）只有一种密码子决定，A错误；tRNA的反密码子具有专一性，一种反密码子只能转运一种氨基酸，B错误；密码子的特殊排列顺序决定了多肽链中氨基酸的排列顺序，进而决定了蛋白质的特异性，C正确；mRNA是由DNA转录而来的，D错误。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500008, '下列关于基因重组的说法，错误的是（ ）', 'A. 基因重组通常发生在有性生殖过程中
B. 减数分裂Ⅰ前期同源染色体非姐妹染色单体的互换属于基因重组
C. 减数分裂Ⅰ后期非同源染色体的自由组合属于基因重组
D. 基因重组能产生新的基因，从而使后代出现新的性状', 'D', '基因重组只能产生新的“基因组合”和“基因型”，不能产生全新的基因。产生新基因的唯一途径是基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500009, '下列关于染色体变异的叙述，正确的是（ ）', 'A. 染色体上某个基因的碱基对缺失属于染色体结构变异
B. 21三体综合征患者体内多了一条21号染色体，属于染色体数目变异
C. 染色体变异只能发生在真核生物的无性生殖过程中
D. 染色体倒位和易位通常不改变染色体上基因的数量和排列顺序', 'B', '基因内部碱基对的缺失属于基因突变，A错误；21三体综合征由于多了一条完整的21号染色体，属于染色体数目变异中的非整倍体变异，B正确；有丝分裂和减数分裂（有性生殖）中都可以发生染色体变异，C错误；易位会剧烈改变基因的数量和排列顺序，D错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500010, '在一个海岛上，由于突变产生了一种具有抗药性的新型昆虫。随着杀虫剂的广泛使用，该抗药性基因的频率逐渐上升。下列相关叙述正确的是（ ）', 'A. 杀虫剂的使用诱发昆虫产生了抗药性突变
B. 抗药性基因频率的定向改变导致了昆虫的定向进化
C. 该种群中昆虫产生抗药性突变后，立即形成了一个新物种
D. 昆虫抗药性的增强是由于杀虫剂对昆虫进行了定向的基因重组', 'B', '突变是不定向的，杀虫剂只起选择作用，不能诱导基因突变，A错误；杀虫剂进行定向选择，使抗药性基因频率定向改变，导致种群的定向进化，B正确；新物种形成的标志是生殖隔离，C错误；杀虫剂选择的是突变基因，非定向基因重组，D错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500011, '性状分离比模拟实验中，若甲、乙两个小桶分别代表雌、雄生殖器官，桶内的小球分别代表雌、雄配子。下列有关叙述正确的是（ ）', 'A. 甲桶 and 乙桶内的小球总数必须严格相等
B. 每个小桶内D小球和d小球的总数可以不相等
C. 该实验模拟的是减数分裂过程中等位基因的分离以及雌雄配子的随机结合
D. 重复做10次该实验，统计得到的杂合子比例一定等于50%', 'C', '生物体产生的雄配子数量远多于雌配子，因此两桶彩球总数不需相等，A错误；每个小桶内的D和d小球数量必须严格相等(1:1)，B错误；重复10次实验由于样本量太小，存在较大偶然性，不一定等于50%，D错误；该实验精准模拟了等位基因分离和受精时配子的随机结合，C正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500012, '某种植物的叶形受两对独立遗传的等位基因控制。现有一株心形叶植株自交，子代中出现心形叶和卵形叶，其比例为9:7。若将该心形叶亲本与卵形叶双隐性纯合子测交，后代的卵形叶个体所占的比例为（ ）', 'A. 1/4
B. 1/2
C. 3/4
D. 7/16', 'C', '自交后代出现9:7的分离比，说明心形叶为双显性（A_B_），其余基因型（A_bb、aaB_、aabb）均为卵形叶。心形叶亲本基因型为AaBb，其与双隐性纯合子aabb测交，后代基因型为AaBb(心形叶，占1/4)、Aabb(卵形叶)、aaBb(卵形叶)、aabb(卵形叶)。因此后代中卵形叶所占比例为3/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500013, '下列关于染色体组和基因组的叙述，正确的是（ ）', 'A. 二倍体生物的每一个染色体组中都含有该物种全套的遗传信息
B. 测定果蝇的基因组需要测定其常染色体和X、Y染色体上的所有DNA序列
C. 减数分裂产生的配子中只含有一个染色体组
D. 人类基因组计划测定了人类23条染色体上的DNA序列', 'B', '多倍体生物的一个染色体组不含全套信息，A错误；四倍体生物减数分裂产生的配子含2个染色体组，C错误；人类基因组计划需测定24条染色体（22条常+X+Y）的DNA序列，D错误；果蝇（2n=8）是二倍体，测定其基因组需要测定3条常染色体加X、Y性染色体，共5条染色体上的DNA序列，B正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500014, '下列关于伴性遗传的叙述，错误的是（ ）', 'A. 伴X染色体显性遗传病中，男患者的母亲和女儿一定患病
B. 伴X染色体隐性遗传病中，女患者的父亲和儿子一定患病
C. 伴Y染色体遗传病具有代代相传、传男不传女的特点
D. 表现型正常的夫妇不可能生出患伴X染色体隐性遗传病的孩子', 'D', '表现型正常的夫妇中，如果母亲是致病基因的携带者（XAXa），父亲正常（XAY），他们完全有可能生出患伴X隐性遗传病的儿子（XaY），D项叙述错误符合题意。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500015, '在艾弗里证明DNA是遗传物质的体外转化实验中，他在S型细菌的细胞提取物中分别加入了不同的酶。下列关于该实验的控制变量的叙述，错误的是（ ）', 'A. 该实验的自变量是添加了不同种类的水解酶
B. 该实验的因变量是R型细菌是否转化为S型细菌
C. 加入DNA酶的组别中，R型细菌能够发生转化
D. 这一实验的设计体现了控制自变量的“减法原理”', 'C', '在加入DNA酶的组别中，S型细菌的DNA被特异性水解，从而失去了转化活性，因此该组中的R型细菌不能转化为S型细菌，C项表述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500016, '下列关于DNA分子结构的叙述，错误的是（ ）', 'A. DNA分子由两条反向平行的脱氧核苷酸长链盘旋而成
B. 外侧的脱氧核糖和磷酸交替连接构成基本骨架
C. 内侧的碱基通过氢键连接形成碱基对
D. A-T碱基对之间有三个氢键，G-C碱基对之间有两个氢键', 'D', '在双链DNA分子结构中，A-T碱基对之间通过2个氢键连接，G-C碱基对之间通过3个氢键连接。因此D项叙述错误，符合题意。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500017, '一个单链RNA病毒的RNA由300个碱基组成，其中A占20%，U占30%。该病毒通过逆转录合成双链DNA并整合到宿主细胞染色体中。合成该双链DNA共需要胞嘧啶（C）和鸟嘌呤（G）脱氧核苷酸的总数是（ ）', 'A. 150个
B. 300个
C. 450个
D. 600个', 'B', '单链RNA中A=20%，U=30%，则C+G占50%，即含有150个C和G。逆转录时，以RNA为模板合成的第一条DNA单链中含有150个G和C；再以第一条DNA链为模板合成互补的双链DNA时，新链中也需要150个C和G。因此，合成整个双链DNA共需要G和C脱氧核苷酸 150 + 150 = 300个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500018, '有关生物体内的基因突变，下列叙述错误的是（ ）', 'A. 基因突变在生物界中普遍存在
B. 基因突变往往具有多方向性，即产生一个以上的等位基因
C. 基因突变通常具有低频性，自然状态下突变率很低
D. 基因突变都是有害的，不会产生对生物有利的变异', 'D', '基因突变大多数是有害的，但也存在少数突变是对生物生存有利的（如抗药性突变、抗病突变等），是有害还是有利取决于变异个体所处的特定环境。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500019, '用杂交育种方法培育高产抗病小麦新品种，在F2中选出符合要求的品种后，还需连续自交多代，其主要目的是（ ）', 'A. 提高显性纯合子的纯合度
B. 淘汰隐性纯合子个体
C. 促进基因发生定向突变
D. 诱导染色体数目加倍', 'A', '在F2中选出的高产抗病显性性状个体中，既有纯合子也有杂合子。为了让优良性状稳定遗传，需要连续自交数代并剔除发生性状分离的杂合子，从而不断提高目标性状基因的纯合度。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500020, '一个处于遗传平衡的某种动物种群中，黑色（B）对白色（b）为显性。若种群中白色个体的比例为16%，则该种群中杂合黑色个体的比例为（ ）', 'A. 24%
B. 36%
C. 48%
D. 84%', 'C', '白色个体为bb，其基因型频率为 b^2 = 16%，解得隐性致病（或白色）基因b的频率为 q = 0.4。则显性基因B的频率为 p = 1 - 0.4 = 0.6。在处于遗传平衡的种群中，杂合黑色个体（Bb）的比例为 2pq = 2 × 0.6 × 0.4 = 0.48 = 48%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500021, '下列关于一对相对性状杂交实验中“假说”内容的叙述，错误的是（ ）', 'A. 生物的性状是由遗传因子决定的
B. 体细胞中遗传因子是成对存在的
C. 生物体在形成配子时，成对的遗传因子彼此分离
D. F1产生的雌雄配子数量相等，且随机结合', 'D', '在高等生物的有性生殖中，雄配子（精子）的数量通常远远多于雌配子（卵细胞）的数量，因此F1产生的雌雄配子数量不相等，D项表述错误符合题意。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500022, '已知控制某植物花色的两对等位基因（A/a，B/b）独立遗传。当具有A或B基因时表现为有色花，双隐性纯合个体表现为白花。现让一株有色花植株自交，子代中出现白花的比例为1/16。则该有色花亲本的基因型为（ ）', 'A. Aabb
B. aaBb
C. AaBb
D. AABB', 'C', '子代白花个体（aabb）所占比例为1/16，即 (1/4) × (1/4)，说明亲本在产生配子时，能产生比例为1/4的ab配子，可以精确定位有色花亲本的基因型为双杂合子AaBb。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500023, '下列关于有丝分裂和减数分裂的共同点的叙述，正确的是（ ）', 'A. 都有同源染色体的联会和分离
B. 都有姐妹染色单体的分离和移向两极
C. 产生的子细胞中染色体数目都减半
D. 分裂过程中都能发生非同源染色体的自由组合', 'B', '同源染色体的联会、分离以及非同源染色体的自由组合只发生在减数分裂过程中，A、D错误；有丝分裂产生的子细胞染色体数目不变，C错误；有丝分裂后期与减数分裂Ⅱ后期都会发生着丝粒分裂、姐妹染色单体分开并向两极移动，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500024, '人类的某种遗传病由一对等位基因控制。现有一对表现型正常的夫妇，妻子怀上双胞胎，经基因检测发现：妻子携带该病的致病基因，丈夫不携带；双胞胎中的老大（男孩）患有该病。下列相关分析正确的是（ ）', 'A. 该病为常染色体隐性遗传病
B. 老大患病是因为其致病基因来自其父亲
C. 若老二是女孩，其基因检测结果一定是纯合子
D. 若该双胞胎为异卵双胞胎，老二（男孩）患病的概率为1/2', 'D', '双亲正常生出患病男孩，且母亲携带丈夫不携带，说明该病为伴X染色体隐性遗传病（设为b），A错误；老大（XbY）的致病基因Xb必定来自于母亲，B错误；老二是女孩的话，其基因型可能为XBXB（纯合子）或XBXb（携带者），C错误；若是异卵双胞胎，老二（男孩）是否患病完全取决于母亲产生的卵细胞类型，患病概率为1/2，D正确。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500025, '在噬菌体侵染大肠杆菌的实验中，用35S标记的噬菌体侵染未标记的大肠杆菌，短时间保温后搅拌、离心。下列叙述正确的是（ ）', 'A. 沉淀物中具有很高的放射性
B. 沉淀物中没有放射性的原因是因为噬菌体未进入大肠杆菌
C. 搅拌的目的是使吸附在大肠杆菌上的噬菌体外壳与大肠杆菌分离
D. 离心后上清液中放射性很低', 'C', '35S标记的是噬菌体的蛋白质外壳。侵染时外壳留在细菌细胞外部，搅拌的目的是使吸附在细菌外壳上的蛋白质外壳与大肠杆菌分离开来，离心后蛋白质外壳分布在上清液中，故上清液具有极高放射性，沉淀物放射性极低。C选项正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500026, '关于DNA分子中碱基比例的关系，下列式子在双链DNA中一定不成立的是（ ）', 'A. (A+T)/(G+C) = 1
B. (A+G)/(T+C) = 1
C. (A+C)/(T+G) = 1
D. A = T 且 G = C', 'A', '在双链DNA中，因为A=T，G=C，所以嘌呤之和等于嘧啶之和，即A+G=T+C，故(A+G)/(T+C)=1（B成立）；同理(A+C)/(T+G)=1（C成立）。而(A+T)/(G+C)的比值在不同DNA分子中具有特异性，不一定等于1，因此A项在双链DNA中不一定成立。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500027, '下列有关真核生物中基因表达的叙述，错误的是（ ）', 'A. 翻译过程中需要mRNA、tRNA、rRNA的共同参与
B. 转录时RNA聚合酶能识别并结合在基因的启动区域
C. 翻译时一条mRNA上可结合多个核糖体同时合成多条多肽链
D. 转录和翻译都在细胞核内完成，保证了高效率', 'D', '在真核细胞中，转录过程主要在细胞核内完成，而翻译过程在细胞质的核糖体上进行，两个过程在空间上是隔开的，D项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500028, '有关基因突变和染色体变异的区分，下列叙述正确的是（ ）', 'A. 基因突变和染色体变异都属于可在显微镜下直接观察到的变异
B. 基因突变是基因结构的改变，染色体变异是染色体结构或数目的改变
C. 基因突变一定会改变基因的数量，染色体变异不改变基因数量
D. 两者都能产生新的基因，都是生物进化的根本来源', 'B', '基因突变在显微镜下观察不到，A错误；基因突变属于分子层面的碱基对改变，基因数量保持不变，C错误；染色体变异不能产生新基因，基因突变才是新基因产生的根本途径，D错误；B项准确概括了两者的核心区别，正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500029, '下列关于单倍体的叙述，正确的是（ ）', 'A. 单倍体生物的体细胞中一定只含有一个染色体组
B. 由未受精的卵细胞发育而来的个体一定是单倍体
C. 单倍体植株往往茎秆粗壮、果实和种子较大
D. 单倍体育种过程中不需要用到秋水仙素', 'B', '单倍体细胞内的染色体组数取决于其亲本配子，如四倍体生物的单倍体含有2个染色体组，A错误；茎秆粗壮、果实较大是多倍体植物的典型特征，C错误；单倍体育种必须使用秋水仙素处理幼苗使其染色体加倍恢复正常，D错误；凡是由未受精的配子直接发育而来的个体都称为单倍体，B正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500030, '共同进化是生物多样性形成的重要原因。下列不属于共同进化实例的是（ ）', 'A. 某种兰花具有细长的花矩，只有具有长口器的某种蛾类才能为其传粉
B. 草原上狼的奔跑速度越来越快，使得鹿的奔跑速度也越来越快
C. 随着光照增强，向日葵的叶片变得越来越大
D. 原始地球早期没有氧气，厌氧生物繁盛；随着蓝细菌制造出氧气，出现了需氧生物', 'C', '共同进化是指不同物种之间、生物与无机环境之间在相互影响中不断进化和发展。A、B属于物种间的协同进化，D属于生物与无机环境的协同进化。C选项中叶片随光照变大属于单一植物个体的适应性调节，不涉及基因频率的改变与进化。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500031, '某种植物的非糯性（A）对糯性（a）为显性。将纯合非糯性品种与糯性品种杂交得F1，取F1的花粉用碘液染色，在显微镜下观察，半数花粉呈蓝黑色（非糯性），半数呈红褐色（糯性）。这一结果可以直接验证（ ）', 'A. 孟德尔的分离定律
B. 孟德尔的自由组合定律
C. 基因的突变
D. 染色体的交叉换', 'A', 'F1（Aa）通过减数分裂产生两种花粉A和a，比例为1:1。花粉遇碘呈现1:1的染色分离结果，直接印证了杂合子在形成配子时，成对的等位基因彼此发生分离，即直接验证了分离定律。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500032, '某种植物宽叶（M）对窄叶（m）为显性，高茎（N）对矮茎（n）为显性，两对基因独立遗传。现将显性纯合的宽叶高茎植株与窄叶矮茎植株杂交，F1全为宽叶高茎。F1自交产生F2，若在F2中窄叶高茎植株中有一定比例在幼苗期致死，导致F2中宽叶高茎：宽叶矮茎：窄叶高茎：窄叶矮茎 = 9:3:2:1。则致死窄叶高茎植株的基因型及在该表型中所占比例为（ ）', 'A. mmNN ， 1/3
B. mmnn ， 1/2
C. mmNn ， 1/2
D. mmNN ， 1/2', 'A', '正常情况下，F1自交得到的F2中窄叶高茎（mmN_）理论比例占3/16（包含1/16 mmNN和2/16 mmNn）。而实际结果中窄叶高茎仅占2/16，说明有1/16的窄叶高茎个体在幼苗期致死，该比例恰好对应纯合子mmNN。所以在原有的窄叶高茎个体中，致死的mmNN占1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500033, '下列关于同源染色体的叙述，正确的是（ ）', 'A. 一条来自父方，一条来自母方的两条染色体一定是同源染色体
B. 减数分裂Ⅰ前期能够发生联会的两条染色体是同源染色体
C. 形状和大小完全相同的两条染色体一定是同源染色体
D. 有丝分裂后期的细胞中没有同源染色体', 'B', '来自父母双方的非同源染色体不能配对，A错误；着丝粒分裂产生的姐妹染色单体形状大小完全相同，属于相同染色体而非同源染色体，C错误；有丝分裂全过程始终含有同源染色体，D错误；在减数分裂Ⅰ前期能够两两配对、进行联会的两条染色体属于同源染色体，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500034, '控制猫毛色的基因位于X染色体上，黑色（B）对黄色（b）为共显性，杂合子（X^B X^b）表现为黑黄相间的玳瑁猫。一只玳瑁雌猫与一只黑色雄猫交配，子代中不可能出现的表型是（ ）', 'A. 黑色雌猫
B. 玳瑁雌猫
C. 黄色雄猫
D. 玳瑁雄猫', 'D', '玳瑁雌猫（XBXb）与黑色雄猫（XBY）杂交，子代基因型为XBXB（黑色雌）、XBXb（玳瑁雌）、XBY（黑色雄）、XbY（黄色雄）。正常情况下雄猫只有一条X染色体，不可能同时含XB和Xb，因此不可能出现玳瑁雄猫。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500035, '下列关于生物学史上经典实验的叙述，错误的是（ ）', 'A. 格里菲斯通过肺炎链球菌体内转化实验证明了加热杀死的S型菌中含有“转化因子”
B. 艾弗里用S型菌的DNA、蛋白质等物质分别处理R型菌，单独观察它们的作用
C. 赫尔希和蔡斯用含32P和35S的培养基直接培养T2噬菌体，从而实现了对噬菌体的标记
D. 烟草花叶病毒侵染烟草的实验证明了RNA也是某些生物的遗传物质', 'C', 'T2噬菌体是病毒，没有细胞结构，不能在无细胞的普通营养培养基上独立生长繁殖。标记噬菌体必须先使用含放射性同位素的培养基培养大肠杆菌，再让噬菌体去侵染带有标记的大肠杆菌，C项叙述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500036, '下列关于密码子和反密码子的叙述，正确的是（ ）', 'A. 密码子位于tRNA上，反密码子位于mRNA上
B. 每种氨基酸都只有一种对应的密码子
C. 反密码子与mRNA上的密码子通过碱基互补配对结合
D. 终止密码子能决定特殊的氨基酸', 'C', '密码子位于mRNA上，反密码子位于tRNA上，A错误；绝大多数氨基酸有多个密码子（简并性），B错误；翻译时反密码子与密码子通过碱基互补配对结合，C正确；终止密码子不决定氨基酸，只作为翻译终止信号，D错误。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500037, '诱变育种能创造出新基因的根本原因是（ ）', 'A. 诱发基因突变，使基因的碱基排列顺序发生改变
B. 诱发染色体变异，使染色体结构发生改变
C. 诱发基因重组，使产生新的基因组合
D. 改变了环境条件，使生物性状发生定向改变', 'A', '基因突变是指DNA分子中发生碱基对的替换、增添和缺失，从而引起基因碱基序列的改变，这是产生新基因的唯一途径，也是诱变育种的根本原因。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500038, '用秋水仙素处理幼苗可以诱导形成多倍体，秋水仙素的作用机理是（ ）', 'A. 促进DNA复制和染色体加倍
B. 抑制减数分裂过程中同源染色体的联会
C. 抑制细胞分裂前期纺锤体的形成
D. 诱导姐妹染色单体不分离', 'C', '秋水仙素能够特异性地作用于细胞有丝分裂前期，抑制纺锤体的形成。这样在分裂后期，着丝粒虽然分裂，但染色体不能移向细胞两极，从而导致细胞内染色体数目加倍。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500039, '某种群中，AA、Aa、aa的个体分别占30%、60%、10%。若该种群中aa个体全部致死，其他个体之间进行随机交配，则子代中aa个体所占的比例为（ ）', 'A. 1/9
B. 1/12
C. 1/16
D. 1/4', 'A', 'aa致死后，存活个体中AA占1/3，Aa占2/3。该群体产生的配子中，A的频率 = 1/3 + 1/2 × 2/3 = 2/3，a的频率 = 1/2 × 2/3 = 1/3。随机交配产生的子代中，aa的比例 = (1/3) × (1/3) = 1/9。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500040, '豌豆的高茎对矮茎为显性。现将纯合高茎豌豆与矮茎豌豆杂交获得F1，F1自交获得F2。若将F2中所有高茎豌豆种植并使其进行自交，则其后代（F3）中高茎与矮茎的比例是（ ）', 'A. 3:1
B. 5:1
C. 8:1
D. 6:1', 'B', 'F2中的高茎豌豆基因型为1/3AA、2/3Aa。它们分别自交，1/3AA自交后代全是高茎；2/3Aa自交后代中矮茎占 2/3 × 1/4 = 1/6，高茎占 2/3 × 3/4 = 1/2。因此F3中高茎:矮茎 = (1/3 + 1/2) : 1/6 = 5/6 : 1/6 = 5:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500041, '某种哺乳动物的毛色受常染色体上的两对等位基因控制。A_B_表现为黑色，A_bb表现为褐色，aaB_和aabb表现为白色。两只黑色个体交配，子代中黑色:褐色:白色 = 9:3:4。下列叙述错误的是（ ）', 'A. 亲本的基因型均为AaBb
B. 子代褐色的个体中纯合子占1/3
C. 子代白色的个体中共有3种基因型
D. 子代中褐色个体相互交配，后代不会出现白色个体', 'D', 'F2表现为9:3:4，说明亲本均为双杂合子AaBb，A正确；子代褐色个体（A_bb）有1/3AAbb、2/3Aabb，纯合子占1/3，B正确；白色个体有aaB_（aaBB、aaBb）和aabb，共3种基因型，C正确；褐色个体中的Aabb相互交配，后代会出现aabb（白色个体），D错误。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500042, '下列关于细胞减数分裂Ⅰ后期发生的变化，叙述正确的是（ ）', 'A. 同源染色体分离，非同源染色体自由组合
B. 姐妹染色单体分离，染色体数目加倍
C. 联会的同源染色体排列在赤道板两侧
D. DNA开始复制，染色体数加倍', 'A', '减数分裂Ⅰ后期的核心变动是同源染色体分离，非同源染色体自由组合，A正确；姐妹染色单体分离发生在减数分裂Ⅱ后期，B错误；联会的同源染色体排列在赤道板两侧发生在减数分裂Ⅰ中期，C错误；DNA复制发生在减数分裂Ⅰ前的间期，D错误。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500043, '果蝇的红眼对白眼为伴X隐性遗传。现有一只红眼雌果蝇与一只白眼雄果蝇杂交，子代中雌雄果蝇均有红眼和白眼。则亲本红眼雌果蝇的基因型为（ ）', 'A. XBX
B. XBXb
C. XbXb
D. XBY', 'B', '由于子代出现了白眼果蝇（雄果蝇为XbY，雌果蝇为XbXb），说明亲本红眼雌果蝇（XBX_）必然带有隐性致病基因b，因此其基因型为XBXb。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500044, '赫尔希和蔡斯的T2噬菌体侵染大肠杆菌实验中，用35S and 32P分别标记不同噬菌体的目的是（ ）', 'A. 标记同一种物质，互为对照
B. 分别标记蛋白质和DNA，以便单独观察它们的作用
C. 提高噬菌体的侵染活力
D. 证明噬菌体的遗传物质是RNA', 'B', 'S是蛋白质特有的元素，P是DNA特有的元素。用35S和32P分别标记不同噬菌体，可以把DNA和蛋白质外壳区分开，单独地、直接地观察它们在侵染过程中的作用。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500045, '某双链DNA分子中，腺嘌呤（A）占碱基总数的20%，则该DNA分子中胞嘧啶（C）占碱基总数的比例为（ ）', 'A. 20%
B. 30%
C. 40%
D. 60%', 'B', '在双链DNA分子中，不互补的碱基之和占碱基总数的一半，即A+C=50%。已知A=20%，则C = 50% - 20% = 30%。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500046, '真核生物中，遗传信息的转录主要发生在（ ）', 'A. 细胞质基质
B. 核糖体
C. 细胞核
D. 高尔基体', 'C', '真核生物的DNA主要分布在细胞核中，因此以DNA为模板合成RNA的转录过程主要发生在细胞核中。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500047, '除哪项外，下列所述变异均属于基因重组（ ）', 'A. 减数分裂Ⅰ后期非同源染色体的自由组合
B. 减数分裂Ⅰ前期同源染色体非姐妹染色单体的互换
C. 显性基因突变为隐性基因
D. 基因工程中将外源基因导入受体细胞', 'C', '显性基因突变为隐性基因属于基因突变。A和B属于自然状态下的有性生殖基因重组，D属于广义的基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500048, '西瓜的染色体数目2n=22。用秋水仙素处理二倍体西瓜幼苗得到四倍体西瓜，该四倍体西瓜的体细胞在有丝分裂后期含有的染色体数目是（ ）', 'A. 22条
B. 44条
C. 88条
D. 176条', 'C', '二倍体西瓜（2n=22）经秋水仙素加倍后得到四倍体西瓜，其体细胞含有44条染色体。在有丝分裂后期，着丝粒分裂导致染色体数目加倍，因此含有 44 × 2 = 88条染色体。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500049, '现代生物进化理论认为，决定生物进化方向的是（ ）', 'A. 基因突变
B. 基因重组
C. 自然选择
D. 生殖隔离', 'C', '基因突变和基因重组是不定向的，只能提供进化的原材料；自然选择使种群基因频率发生定向改变，决定了生物进化的方向。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500050, '下列关于人类遗传病的叙述，正确的是（ ）', 'A. 单基因遗传病是由一个基因引起的遗传病
B. 调查某种人类遗传病的发病率应在患者家系中进行
C. 胎儿出生前通过产前诊断可以确定所有的先天性疾病
D. 伴X显性遗传病的特点是代代相传且女性患者多于男性', 'D', '单基因遗传病是由一对等位基因控制的遗传病，A错误；调查发病率应在人群中随机抽样调查，B错误；产前诊断不能确定所有的先天性疾病，C错误；伴X显性遗传病具有连续遗传（代代相传）以及女性患者多于男性的特点，D正确。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500051, '孟德尔选用豌豆作为遗传实验材料并取得成功的原因，下列叙述错误的是（ ）', 'A. 豌豆是自花传粉、闭花受粉植物，在自然状态下一般都是纯种
B. 豌豆具有多对易于区分的相对性状，且能稳定地遗传给后代
C. 豌豆花大，在进行人工异花传粉时不需要套袋隔离
D. 孟德尔在分析实验结果时，首次运用了统计学的方法进行分析', 'C', '豌豆在进行人工异花传粉时，为了避免外来花粉的干扰，在去雄前、去雄后以及传粉后都必须进行套袋隔离，C项错误。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500052, '控制某种植物果实形状的两对独立遗传的等位基因（A/a、B/b），当两对基因均为隐性时表现为长圆形，其余基因型分别表现为扁盘形（A_B_）和圆球形（A_bb、aaB_）。两株圆球形植株杂交，F1全为扁盘形，F1自交获得F2。则F2中扁盘形：圆球形：长圆形的比例理论上为（ ）', 'A. 9:6:1
B. 9:3:4
C. 12:3:1
D. 15:1', 'A', '两株圆球形（AAbb × aaBB）杂交，F1全为AaBb（扁盘形）。F1自交得F2，其中扁盘形（A_B_）占9/16；圆球形（A_bb占3/16，aaB_占3/16）合计占6/16；长圆形（aabb）占1/16。因此分离比为9:6:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500053, '一个精原细胞的基因型为AaX^BY，若它在减数分裂Ⅰ过程中，同源染色体A与a未正常分离而移向同一极，其他过程均正常。则该精原细胞产生的精子基因型可能为（ ）', 'A. AaX^B、AaX^B、Y、Y
B. AX^B、aY、AX^B、aY
C. AaY、AaY、X^B、X^B
D. A选项或C选项均有可能', 'D', '减数分裂Ⅰ后期同源染色体A与a移向同一极，产生一个含Aa的次级精母细胞和一个不含该对基因的次级精母细胞。若此时非同源染色体中的X^B与Aa移向一极，则最终产生基因型为AaX^B和Y的精子（A项）；若Y与Aa移向一极，则产生AaY和X^B的精子（C项）。故D正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500054, '下列关于伴X染色体隐性遗传病（如红绿色盲）特点的叙述，错误的是（ ）', 'A. 具有交叉遗传现象，男患者的致病基因常通过女儿传给外孙
B. 在人群中，男性患者的数量通常明显多于女性患者
C. 女患者的父亲和儿子一定都是该病的患者
D. 表现型正常的夫妇，不可能生出患有该病的孩子', 'D', '表现型正常的夫妇中，如果母亲是致病基因的携带者（XAXa），父亲正常（XAY），他们仍有25%的概率生出患病的孩子（XaY，即患病儿子），D项错误。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500055, '烟草花叶病毒（TMV）由蛋白质外壳和RNA组成。将TMV的RNA与蛋白质外壳分离，分别感染健康的烟草叶片。下列有关叙述正确的是（ ）', 'A. 接种蛋白质外壳的叶片上会出现病斑
B. 接种RNA的叶片上会出现病斑，且能从中分离出完整的TMV
C. 该实验证明了RNA是烟草花叶病毒的主要遗传物质
D. 该实验与噬菌体侵染大肠杆菌实验的设计思路完全不同', 'B', 'TMV的遗传物质是RNA，接种RNA的叶片会出现病斑并能分离出子代病毒，B正确；蛋白质外壳不具遗传效应，A错误；该实验证明了RNA是烟草花叶病毒的遗传物质（无“主要”二字），C错误；该实验与噬菌体实验的思路相同，都是将DNA/RNA与蛋白质分开单独观察其作用，D错误。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500056, '科学家将大肠杆菌放在含有15N的培养基中培养若干代，使其DNA双链均被15N标记（重带）。然后将其转移到含14N的培养基中，连续繁殖两代。将子二代大肠杆菌的DNA进行密度梯度离心，离心管中出现的条带及比例为（ ）', 'A. 全部位于轻带（14N/14N）
B. 1/2位于轻带，1/2位于中带（15N/14N）
C. 1/2位于重带，1/2位于中带
D. 1/4位于轻带，3/4位于中带', 'B', '亲代DNA双链为15N15N。在含14N的培养基中复制1次（子一代）产生2个15N14N的DNA（全为中带）。复制2次（子二代）共产生4个DNA，其中2个为15N14N（中带），2个为14N14N（轻带），比例为1:1。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500057, '柳穿鱼的花色有高度对称的辐射状花和两侧对称的唇形花两种。研究发现，控制这两种花色形态的基因序列完全相同，但辐射状花中的Lcyc基因被高度甲基化。下列关于该表观遗传现象的叙述，错误的是（ ）', 'A. 植株的DNA甲基化修饰会导致Lcyc基因的碱基序列发生改变
B. 基因的甲基化修饰会影响该基因的转录或翻译过程
C. 这种因DNA修饰而导致的表型改变是可以遗传给后代的
D. 表观遗传现象说明生物的性状并不完全由基因的碱基序列决定', 'A', '表观遗传中的DNA甲基化修饰会影响基因的表达，导致表型改变并且可以遗传，但整个修饰过程中基因的碱基排列顺序（DNA序列）本身没有发生改变，A项错误。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500058, '人类镰状细胞贫血的根本原因是血红蛋白基因中的碱基对由T-A替换成了A-T。这种变异属于（ ）', 'A. 基因重组
B. 基因突变
C. 染色体结构变异
D. 染色体数目变异', 'B', '碱基对的替换、增添和缺失属于基因突变。血红蛋白基因内部发生碱基对替换导致性状改变，属于基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500059, '在“低温诱导植物细胞染色体数目的变化”实验中，下列关于各试剂及操作的作用，叙述正确的是（ ）', 'A. 低温处理的目的是抑制细胞分裂间期染色体的复制
B. 卡诺氏液的作用是使洋葱根尖细胞彼此分散开来
C. 改良苯酚品红染液能够使细胞中的染色体着色
D. 解离后的根尖直接放入染色液中进行染色', 'C', '低温处理目的是抑制有丝分裂前期纺锤体的形成，A错误；卡诺氏液的作用是固定细胞形态，使细胞分散的是解离液，B错误；改良苯酚品红是碱性染料，能使染色体着色，C正确；解离后必须先在清水中漂洗，洗去解离液后才能染色，D错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500060, '达尔文在加拉帕戈斯群岛上发现，不同岛屿上的地雀喙的形态各异，它们分别适应采食昆虫、坚果、仙人掌等。下列结合现代生物进化理论的解释，错误的是（ ）', 'A. 不同岛屿上不同的食物条件起到了自然选择的作用
B. 地雀喙的形态差异是为了适应不同岛屿环境而产生的定向突变
C. 逐渐形成的地理隔离阻断了不同岛屿地雀种群间的基因交流
D. 当不同岛屿的地雀出现生殖隔离时，标志着新物种的形成', 'B', '突变和变异是不定向的，环境（食物条件）起到了定向选择的作用。地雀不能为了适应环境而发生“定向突变”，B项错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500061, '下列有关测交实验的说法中，正确的是（ ）', 'A. 测交实验可以直接测定受试个体的基因组序列
B. 测交时应选用显性纯合子与受试个体进行杂交
C. 测交后代的性状表现及比例能反映受试个体产生的配子种类及比例
D. 测交是假说—演绎法中提出假说的核心依据', 'C', '测交是让受试个体与隐性纯合子杂交，B错误；隐性纯合子只产生含隐性基因的配子，不能掩盖受试个体配子的基因表达，因此后代表型及比例能准确反映受试个体的配子种类及比例，C正确；测交是假说—演绎法中用于“实验验证”的步骤，D错误。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500062, '某种小鼠的毛色受常染色体上一对等位基因控制。野生型黄毛小鼠与野生型黄毛小鼠杂交，子代中总是出现约2/3的黄毛小鼠和1/3的黑毛小鼠。对此现象最合理的解释是（ ）', 'A. 黄毛对黑毛为隐性性状
B. 控制毛色的基因发生了定向突变
C. 控制黄毛的基因具有显性纯合致死效应
D. 该种群小鼠没有发生随机交配', 'C', '黄毛与黄毛杂交后代出现黑毛，说明黄毛为显性（设为A）。杂合子黄毛（Aa × Aa）交配，理论上子代为1/4AA、1/2Aa、1/4aa。由于实际存活比例中黄毛（A_）:黑毛（aa）=2:1，说明显性纯合子AA致死，存活的黄毛全为Aa，C正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500063, '在显微镜下观察二倍体动物精巢的切片，发现一个正在进行分裂的细胞，细胞中不含同源染色体，且姐妹染色单体正在分离并移向两极。该细胞处于（ ）', 'A. 有丝分裂后期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ后期
D. 减数分裂Ⅰ前期', 'C', '细胞中不含同源染色体，说明减数分裂Ⅰ已经完成；姐妹染色单体正在分离并移向两极，说明着丝粒已分裂，这是减数分裂Ⅱ后期的典型特征。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500064, '抗维生素D佝偻病是一种伴X染色体显性遗传病。下列关于该病遗传特征的叙述，正确的是（ ）', 'A. 患者中男性数量远多于女性数量
B. 男患者与正常女性结婚，其女儿一定患病，儿子一定正常
C. 女患者的父亲和儿子一定都是该病患者
D. 该病在人群中往往表现为隔代遗传', 'B', '伴X显性遗传病中女性患者多于男性，A错误；男患者（XBY）与正常女性（XbXb）结婚，女儿必得XB而患病，儿子必得Y而正常，B正确；女患者可能是杂合子，其儿子有一半概率正常，C错误；显性遗传病具有连续遗传特点，D错误。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500065, '在赫尔希和蔡斯的T2噬菌体侵染大肠杆菌实验中，如果用32P标记的噬菌体侵染大肠杆菌，但保温时间过短，搅拌离心后检测到的主要实验现象是（ ）', 'A. 沉淀物中放射性很高，上清液中无放射性
B. 上清液中放射性显著升高，沉淀物中放射性较低
C. 只有子代噬菌体的蛋白质外壳具有放射性
D. 大肠杆菌全部发生裂解并释放出子代噬菌体', 'B', '32P标记的是噬菌体的DNA。若保温时间过短，许多噬菌体还来不及将自身的DNA注入大肠杆菌内部。搅拌离心后，这些仍吸附在细菌外表的噬菌体随外壳一起分配到上清液中，导致上清液放射性显著升高。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500066, '下列关于细胞内DNA复制的叙述，错误的是（ ）', 'A. 复制过程需要解旋酶破坏碱基对之间的氢键
B. 复制时以解开的每一条脱氧核苷酸链为模板
C. 复制产生的两条子链在碱基排列顺序上完全相同
D. 复制需要四种游离的脱氧核苷酸作为合成原料', 'C', '双链DNA的两条母链是碱基互补配对的，并不是完全相同的。因此，以这两条相互互补的母链为模板合成的两条子链，其碱基排列顺序也是互补关系，而不是完全相同，C错误。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500067, '关于细胞中转录和翻译的比较，下列叙述正确的是（ ）', 'A. 两者所需的原料完全相同，均为核苷酸
B. 两者发生碱基互补配对的方式完全相同
C. 转录和翻译的产物分别主要在细胞核 and 核糖体中发挥作用
D. 两个过程在真核细胞中通常是空间上隔开、时间上先后进行的', 'D', '转录原料是核糖核苷酸，翻译原料是氨基酸，A错误；转录有T-A配对，翻译是U-A配对，B错误；转录产物RNA和翻译产物蛋白质多数在细胞质或其他部位发挥作用，C错误；真核生物具有核膜，转录在细胞核内进行，翻译在细胞质的核糖体上进行，两者在时空上是分隔开的，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500068, '关于变异和进化的关系，下列叙述正确的是（ ）', 'A. 基因突变会产生新的基因，因此决定了生物进化的方向
B. 基因重组通过产生新的基因型，为自然选择提供了丰富的原材料
C. 只有生殖细胞中发生的变异才属于可遗传的变异
D. 变异能够使生物产生适应环境的定向改变', 'B', '自然选择决定生物进化的方向，A错误；基因重组能产生全新的基因型组合，为选择提供丰富的变异原材料，B正确；只要体内的遗传物质改变就属于可遗传变异（体细胞突变可通过无性生殖遗传），C错误；变异是不定向的，D错误。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500069, '三倍体无子西瓜深受消费者喜爱。下列关于三倍体无子西瓜培育及特点的叙述，错误的是（ ）', 'A. 用秋水仙素处理二倍体西瓜幼苗的芽尖可获得四倍体植株
B. 三倍体西瓜植株是由四倍体母本与二倍体父本杂交产生的种子发育而来的
C. 三倍体无子西瓜高度不育的根本原因是细胞中缺乏同源染色体
D. 三倍体西瓜由于联会紊乱不能产生正常的配子，因而表现为无子', 'C', '三倍体无子西瓜体细胞内含有三个染色体组，存在同源染色体（每种染色体有三条）。其高度不育的根本原因是减数分裂联会时同源染色体联会紊乱，不能产生正常的配子，而不是缺乏同源染色体，C错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500070, '下列关于物种和隔离的叙述，正确的是（ ）', 'A. 地理隔离是新物种形成的必要条件，没有地理隔离就不能形成新物种
B. 只有当两个种群的个体无法交配时，才说明它们之间存在生殖隔离
C. 新物种形成的标志是产生了生殖隔离，此时两个种群的基因库存在明显差异
D. 多倍体育种产生的植物不需要经过隔离就能直接定义为新物种', 'C', '多倍体的形成不需要经过地理隔离，A错误；生殖隔离包括不能交配、或者交配后不能产生可育后代（如骡子），B错误；新物种形成的标志是产生生殖隔离，此时基因库差异显著阻断了基因交流，C正确；多倍体与其二倍体祖先由于杂交不育，已存在生殖隔离，属于新物种，D错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500071, '杂合子Aa连续自交n代后，后代中杂合子所占的比例以及纯合子所占的比例分别为（ ）', 'A. 1/2^n ； 1 - 1/2^n
B. 1/2^n ； 1/2^n
C. 1 - 1/2^n ； 1/2^n
D. (1/2)^n ； (1/2)^n', 'A', '杂合子Aa自交1代后，杂合子比例变为1/2；自交2代后，杂合子比例变为1/4。由此递推，连续自交n代后，后代中杂合子所占的比例为(1/2)^n，即1/2^n。纯合子所占比例为 1 - 1/2^n。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500072, '某植物的花色由两对独立遗传的等位基因控制。现有一株红花植株自交，子代中红花：白花 = 15:1。据此推测，该红花亲本的基因型精确定位为（ ）', 'A. AaBb
B. Aabb
C. aaBb
D. AABB', 'A', '子代红花：白花 = 15:1 是双杂合子自交后代 9:3:3:1 的典型变式（9+3+3=15），说明只要基因组中含有一个显性基因（A_B_、A_bb、aaB_）就表现为红花，只有双隐性纯合个体（aabb）表现为白花。因此，该红花亲本的基因型必然是双杂合子AaBb。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500073, '关于哺乳动物精子和卵细胞形成过程的叙述，错误的是（ ）', 'A. 精子形成过程需要经过变形阶段，而卵细胞不需要
B. 一个精原细胞可产生4个精子，而一个卵原细胞只产生1个卵细胞
C. 精子形成过程中细胞质均等分配，卵细胞形成过程中细胞质均不均等分配
D. 减数分裂Ⅰ后期，精子和卵细胞的形成过程均会发生同源染色体的分离', 'C', '在卵细胞形成过程中，初级卵母细胞（减数分裂Ⅰ后期）和次级卵母细胞（减数分裂Ⅱ后期）细胞质的分裂是不均等的，但是第一极体在进行减数分裂Ⅱ后期时细胞质的分裂是均等的。因此C项表述过于绝对。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500074, '家鸡的性别决定方式为ZW型。家鸡的芦花羽毛（B）对非芦花羽毛（b）为显性，基因位于Z染色体上。现要通过羽毛特征直接在早期鉴别出雏鸡的雌雄，应选择的亲本杂交组合是（ ）', 'A. 芦花雌鸡 × 芦花雄鸡
B. 非芦花雌鸡 × 芦花雄鸡
C. 芦花雌鸡 × 非芦花雄鸡
D. 非芦花雌鸡 × 非芦花雄鸡', 'C', '选择芦花雌鸡（ZBW）与非芦花雄鸡（ZbZb）杂交，后代中的雄鸡基因型全部为ZBZb（表现为芦花羽毛），雌鸡基因型全部为ZbW（表现为非芦花羽毛）。这样在雏鸡刚孵化时，就可以根据羽毛特征直接鉴别出雌雄。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500075, '艾弗里的肺炎链球菌体外转化实验和赫尔希、蔡斯的噬菌体侵染大肠杆菌实验，在实验设计思路上的共同核心点是（ ）', 'A. 均利用放射性同位素标记法来追踪物质的变化
B. 均采用电子显微镜直接观察物质的进入过程
C. 设法把DNA和蛋白质等物质分开，单独地、直接地观察它们的作用
D. 均通过加热杀死的手段破坏蛋白质的活性', 'C', '两经典实验的共同最核心设计思路是：想办法将DNA与蛋白质等其他成分分离开来，单独地、直接地去观察它们各自在遗传中的生物效应。艾弗里实验没有使用同位素标记。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500076, '一个含有200个碱基的双链DNA分子，其中腺嘌呤（A）占20%。该DNA分子在含14N的培养基中连续复制数次后，共消耗了游离的胞嘧啶（C）脱氧核苷酸420个。则该DNA分子共复制了（ ）', 'A. 2次
B. 3次
C. 4次
D. 5次', 'B', '双链DNA中A=20%，根据碱基互补配对原则，C = 50% - 20% = 30%，因此该DNA分子中含有C = 200 × 30% = 60个。设复制了n次，消耗游离C的计算公式为：60 × (2^n - 1) = 420，解得 2^n - 1 = 7，即 2^n = 8，n = 3次。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500077, '下列关于密码子、反密码子和氨基酸之间关系的叙述，正确的是（ ）', 'A. 每种氨基酸都由多种密码子决定
B. 同一种反密码子可以转运多种氨基酸
C. 密码子的特殊排列顺序决定了蛋白质的特异性
D. mRNA上的密码子由tRNA上的反密码子转录而来', 'C', '部分氨基酸（如甲硫氨酸、色氨酸）只有一种密码子决定，A错误；tRNA的反密码子具有专一性，一种反密码子只能转运一种氨基酸，B错误；密码子的特殊排列顺序决定了多肽链中氨基酸的排列顺序，进而决定了蛋白质的特异性，C正确；mRNA是由DNA转录而来的，D错误。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500078, '下列关于基因重组的说法，错误的是（ ）', 'A. 基因重组通常发生在有性生殖过程中
B. 减数分裂Ⅰ前期同源染色体非姐妹染色单体的互换属于基因重组
C. 减数分裂Ⅰ后期非同源染色体的自由组合属于基因重组
D. 基因重组能产生新的基因，从而使后代出现新的性状', 'D', '基因重组只能产生新的“基因组合”和“基因型”，不能产生全新的基因。产生新基因的唯一途径是基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500079, '下列关于染色体变异的叙述，正确的是（ ）', 'A. 染色体上某个基因的碱基对缺失属于染色体结构变异
B. 21三体综合征患者体内多了一条21号染色体，属于染色体数目变异
C. 染色体变异只能发生在真核生物的无性生殖过程中
D. 染色体倒位和易位通常不改变染色体上基因的数量和排列顺序', 'B', '基因内部碱基对的缺失属于基因突变，A错误；21三体综合征由于多了一条完整的21号染色体，属于染色体数目变异中的非整倍体变异，B正确；有丝分裂和减数分裂（有性生殖）中都可以发生染色体变异，C错误；易位会剧烈改变基因的数量和排列顺序，D错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500080, '在一个海岛上，由于突变产生了一种具有抗药性的新型昆虫。随着杀虫剂的广泛使用，该抗药性基因的频率逐渐上升。下列相关叙述正确的是（ ）', 'A. 杀虫剂的使用诱发昆虫产生了抗药性突变
B. 抗药性基因频率的定向改变导致了昆虫的定向进化
C. 该种群中昆虫产生抗药性突变后，立即形成了一个新物种
D. 昆虫抗药性的增强是由于杀虫剂对昆虫进行了定向的基因重组', 'B', '突变是不定向的，杀虫剂只起选择作用，不能诱导基因突变，A错误；杀虫剂进行定向选择，使抗药性基因频率定向改变，导致种群的定向进化，B正确；新物种形成的标志是生殖隔离，C错误；杀虫剂选择的是突变基因，非定向基因重组，D错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500081, '性状分离比模拟实验中，若甲、乙两个小桶分别代表雌、雄生殖器官，桶内的小球分别代表雌、雄配子。下列有关叙述正确的是（ ）', 'A. 甲桶 and 乙桶内的小球总数必须严格相等
B. 每个小桶内D小球和d小球的总数可以不相等
C. 该实验模拟的是减数分裂过程中等位基因的分离以及雌雄配子的随机结合
D. 重复做10次该实验，统计得到的杂合子比例一定等于50%', 'C', '生物体产生的雄配子数量远多于雌配子，因此两桶彩球总数不需相等，A错误；每个小桶内的D和d小球数量必须严格相等(1:1)，B错误；重复10次实验由于样本量太小，存在较大偶然性，不一定等于50%，D错误；该实验精准模拟了等位基因分离和受精时配子的随机结合，C正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500082, '某种植物的叶形受两对独立遗传的等位基因控制。现有一株心形叶植株自交，子代中出现心形叶和卵形叶，其比例为9:7。若将该心形叶亲本与卵形叶双隐性纯合子测交，后代的卵形叶个体所占的比例为（ ）', 'A. 1/4
B. 1/2
C. 3/4
D. 7/16', 'C', '自交后代出现9:7的分离比，说明心形叶为双显性（A_B_），其余基因型（A_bb、aaB_、aabb）均为卵形叶。心形叶亲本基因型为AaBb，其与双隐性纯合子aabb测交，后代基因型为AaBb(心形叶，占1/4)、Aabb(卵形叶)、aaBb(卵形叶)、aabb(卵形叶)。因此后代中卵形叶所占比例为3/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500083, '下列关于染色体组和基因组的叙述，正确的是（ ）', 'A. 二倍体生物的每一个染色体组中都含有该物种全套的遗传信息
B. 测定果蝇的基因组需要测定其常染色体和X、Y染色体上的所有DNA序列
C. 减数分裂产生的配子中只含有一个染色体组
D. 人类基因组计划测定了人类23条染色体上的DNA序列', 'B', '多倍体生物的一个染色体组不含全套信息，A错误；四倍体生物减数分裂产生的配子含2个染色体组，C错误；人类基因组计划需测定24条染色体（22条常+X+Y）的DNA序列，D错误；果蝇（2n=8）是二倍体，测定其基因组需要测定3条常染色体加X、Y性染色体，共5条染色体上的DNA序列，B正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500084, '下列关于伴性遗传的叙述，错误的是（ ）', 'A. 伴X染色体显性遗传病中，男患者的母亲和女儿一定患病
B. 伴X染色体隐性遗传病中，女患者的父亲和儿子一定患病
C. 伴Y染色体遗传病具有代代相传、传男不传女的特点
D. 表现型正常的夫妇不可能生出患伴X染色体隐性遗传病的孩子', 'D', '表现型正常的夫妇中，如果母亲是致病基因的携带者（XAXa），父亲正常（XAY），他们完全有可能生出患伴X隐性遗传病的儿子（XaY），D项叙述错误符合题意。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500085, '在艾弗里证明DNA是遗传物质的体外转化实验中，他在S型细菌的细胞提取物中分别加入了不同的酶。下列关于该实验的控制变量的叙述，错误的是（ ）', 'A. 该实验的自变量是添加了不同种类的水解酶
B. 该实验的因变量是R型细菌是否转化为S型细菌
C. 加入DNA酶的组别中，R型细菌能够发生转化
D. 这一实验的设计体现了控制自变量的“减法原理”', 'C', '在加入DNA酶的组别中，S型细菌的DNA被特异性水解，从而失去了转化活性，因此该组中的R型细菌不能转化为S型细菌，C项表述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500086, '下列关于DNA分子结构的叙述，错误的是（ ）', 'A. DNA分子由两条反向平行的脱氧核苷酸长链盘旋而成
B. 外侧的脱氧核糖和磷酸交替连接构成基本骨架
C. 内侧的碱基通过氢键连接形成碱基对
D. A-T碱基对之间有三个氢键，G-C碱基对之间有两个氢键', 'D', '在双链DNA分子结构中，A-T碱基对之间通过2个氢键连接，G-C碱基对之间通过3个氢键连接。因此D项叙述错误，符合题意。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500087, '一个单链RNA病毒的RNA由300个碱基组成，其中A占20%，U占30%。该病毒通过逆转录合成双链DNA并整合到宿主细胞染色体中。合成该双链DNA共需要胞嘧啶（C）和鸟嘌呤（G）脱氧核苷酸的总数是（ ）', 'A. 150个
B. 300个
C. 450个
D. 600个', 'B', '单链RNA中A=20%，U=30%，则C+G占50%，即含有150个C和G。逆转录时，以RNA为模板合成的第一条DNA单链中含有150个G和C；再以第一条DNA链为模板合成互补的双链DNA时，新链中也需要150个C和G。因此，合成整个双链DNA共需要G和C脱氧核苷酸 150 + 150 = 300个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500088, '有关生物体内的基因突变，下列叙述错误的是（ ）', 'A. 基因突变在生物界中普遍存在
B. 基因突变往往具有多方向性，即产生一个以上的等位基因
C. 基因突变通常具有低频性，自然状态下突变率很低
D. 基因突变都是有害的，不会产生对生物有利的变异', 'D', '基因突变大多数是有害的，但也存在少数突变是对生物生存有利的（如抗药性突变、抗病突变等），是有害还是有利取决于变异个体所处的特定环境。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500089, '用杂交育种方法培育高产抗病小麦新品种，在F2中选出符合要求的品种后，还需连续自交多代，其主要目的是（ ）', 'A. 提高显性纯合子的纯合度
B. 淘汰隐性纯合子个体
C. 促进基因发生定向突变
D. 诱导染色体数目加倍', 'A', '在F2中选出的高产抗病显性性状个体中，既有纯合子也有杂合子。为了让优良性状稳定遗传，需要连续自交数代并剔除发生性状分离的杂合子，从而不断提高目标性状基因的纯合度。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500090, '一个处于遗传平衡的某种动物种群中，黑色（B）对白色（b）为显性。若种群中白色个体的比例为16%，则该种群中杂合黑色个体的比例为（ ）', 'A. 24%
B. 36%
C. 48%
D. 84%', 'C', '白色个体为bb，其基因型频率为 b^2 = 16%，解得隐性致病（或白色）基因b的频率为 q = 0.4。则显性基因B的频率为 p = 1 - 0.4 = 0.6。在处于遗传平衡的种群中，杂合黑色个体（Bb）的比例为 2pq = 2 × 0.6 × 0.4 = 0.48 = 48%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500091, '下列关于一对相对性状杂交实验中“假说”内容的叙述，错误的是（ ）', 'A. 生物的性状是由遗传因子决定的
B. 体细胞中遗传因子是成对存在的
C. 生物体在形成配子时，成对的遗传因子彼此分离
D. F1产生的雌雄配子数量相等，且随机结合', 'D', '在高等生物的有性生殖中，雄配子（精子）的数量通常远远多于雌配子（卵细胞）的数量，因此F1产生的雌雄配子数量不相等，D项表述错误符合题意。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500092, '已知控制某植物花色的两对等位基因（A/a，B/b）独立遗传。当具有A或B基因时表现为有色花，双隐性纯合个体表现为白花。现让一株有色花植株自交，子代中出现白花的比例为1/16。则该有色花亲本的基因型为（ ）', 'A. Aabb
B. aaBb
C. AaBb
D. AABB', 'C', '子代白花个体（aabb）所占比例为1/16，即 (1/4) × (1/4)，说明亲本在产生配子时，能产生比例为1/4的ab配子，可以精确定位有色花亲本的基因型为双杂合子AaBb。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500093, '下列关于有丝分裂和减数分裂的共同点的叙述，正确的是（ ）', 'A. 都有同源染色体的联会和分离
B. 都有姐妹染色单体的分离和移向两极
C. 产生的子细胞中染色体数目都减半
D. 分裂过程中都能发生非同源染色体的自由组合', 'B', '同源染色体的联会、分离以及非同源染色体的自由组合只发生在减数分裂过程中，A、D错误；有丝分裂产生的子细胞染色体数目不变，C错误；有丝分裂后期与减数分裂Ⅱ后期都会发生着丝粒分裂、姐妹染色单体分开并向两极移动，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500094, '人类的某种遗传病由一对等位基因控制。现有一对表现型正常的夫妇，妻子怀上双胞胎，经基因检测发现：妻子携带该病的致病基因，丈夫不携带；双胞胎中的老大（男孩）患有该病。下列相关分析正确的是（ ）', 'A. 该病为常染色体隐性遗传病
B. 老大患病是因为其致病基因来自其父亲
C. 若老二是女孩，其基因检测结果一定是纯合子
D. 若该双胞胎为异卵双胞胎，老二（男孩）患病的概率为1/2', 'D', '双亲正常生出患病男孩，且母亲携带丈夫不携带，说明该病为伴X染色体隐性遗传病（设为b），A错误；老大（XbY）的致病基因Xb必定来自于母亲，B错误；老二是女孩的话，其基因型可能为XBXB（纯合子）或XBXb（携带者），C错误；若是异卵双胞胎，老二（男孩）是否患病完全取决于母亲产生的卵细胞类型，患病概率为1/2，D正确。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500095, '在噬菌体侵染大肠杆菌的实验中，用35S标记的噬菌体侵染未标记的大肠杆菌，短时间保温后搅拌、离心。下列叙述正确的是（ ）', 'A. 沉淀物中具有很高的放射性
B. 沉淀物中没有放射性的原因是因为噬菌体未进入大肠杆菌
C. 搅拌的目的是使吸附在大肠杆菌上的噬菌体外壳与大肠杆菌分离
D. 离心后上清液中放射性很低', 'C', '35S标记的是噬菌体的蛋白质外壳。侵染时外壳留在细菌细胞外部，搅拌的目的是使吸附在细菌外壳上的蛋白质外壳与大肠杆菌分离开来，离心后蛋白质外壳分布在上清液中，故上清液具有极高放射性，沉淀物放射性极低。C选项正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500096, '关于DNA分子中碱基比例的关系，下列式子在双链DNA中一定不成立的是（ ）', 'A. (A+T)/(G+C) = 1
B. (A+G)/(T+C) = 1
C. (A+C)/(T+G) = 1
D. A = T 且 G = C', 'A', '在双链DNA中，因为A=T，G=C，所以嘌呤之和等于嘧啶之和，即A+G=T+C，故(A+G)/(T+C)=1（B成立）；同理(A+C)/(T+G)=1（C成立）。而(A+T)/(G+C)的比值在不同DNA分子中具有特异性，不一定等于1，因此A项在双链DNA中不一定成立。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500097, '下列有关真核生物中基因表达的叙述，错误的是（ ）', 'A. 翻译过程中需要mRNA、tRNA、rRNA的共同参与
B. 转录时RNA聚合酶能识别并结合在基因的启动区域
C. 翻译时一条mRNA上可结合多个核糖体同时合成多条多肽链
D. 转录和翻译都在细胞核内完成，保证了高效率', 'D', '在真核细胞中，转录过程主要在细胞核内完成，而翻译过程在细胞质的核糖体上进行，两个过程在空间上是隔开的，D项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500098, '有关基因突变和染色体变异的区分，下列叙述正确的是（ ）', 'A. 基因突变和染色体变异都属于可在显微镜下直接观察到的变异
B. 基因突变是基因结构的改变，染色体变异是染色体结构或数目的改变
C. 基因突变一定会改变基因的数量，染色体变异不改变基因数量
D. 两者都能产生新的基因，都是生物进化的根本来源', 'B', '基因突变在显微镜下观察不到，A错误；基因突变属于分子层面的碱基对改变，基因数量保持不变，C错误；染色体变异不能产生新基因，基因突变才是新基因产生的根本途径，D错误；B项准确概括了两者的核心区别，正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500099, '下列关于单倍体的叙述，正确的是（ ）', 'A. 单倍体生物的体细胞中一定只含有一个染色体组
B. 由未受精的卵细胞发育而来的个体一定是单倍体
C. 单倍体植株往往茎秆粗壮、果实和种子较大
D. 单倍体育种过程中不需要用到秋水仙素', 'B', '单倍体细胞内的染色体组数取决于其亲本配子，如四倍体生物的单倍体含有2个染色体组，A错误；茎秆粗壮、果实较大是多倍体植物的典型特征，C错误；单倍体育种必须使用秋水仙素处理幼苗使其染色体加倍恢复正常，D错误；凡是由未受精的配子直接发育而来的个体都称为单倍体，B正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500100, '共同进化是生物多样性形成的重要原因。下列不属于共同进化实例的是（ ）', 'A. 某种兰花具有细长的花矩，只有具有长口器的某种蛾类才能为其传粉
B. 草原上狼的奔跑速度越来越快，使得鹿的奔跑速度也越来越快
C. 随着光照增强，向日葵的叶片变得越来越大
D. 原始地球早期没有氧气，厌氧生物繁盛；随着蓝细菌制造出氧气，出现了需氧生物', 'C', '共同进化是指不同物种之间、生物与无机环境之间在相互影响中不断进化和发展。A、B属于物种间的协同进化，D属于生物与无机环境的协同进化。C选项中叶片随光照变大属于单一植物个体的适应性调节，不涉及基因频率的改变与进化。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500101, '某种植物的非糯性（A）对糯性（a）为显性。将纯合非糯性品种与糯性品种杂交得F1，取F1的花粉用碘液染色，在显微镜下观察，半数花粉呈蓝黑色（非糯性），半数呈红褐色（糯性）。这一结果可以直接验证（ ）', 'A. 孟德尔的分离定律
B. 孟德尔的自由组合定律
C. 基因的突变
D. 染色体的交叉换', 'A', 'F1（Aa）通过减数分裂产生两种花粉A和a，比例为1:1。花粉遇碘呈现1:1的染色分离结果，直接印证了杂合子在形成配子时，成对的等位基因彼此发生分离，即直接验证了分离定律。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500102, '某种植物宽叶（M）对窄叶（m）为显性，高茎（N）对矮茎（n）为显性，两对基因独立遗传。现将显性纯合的宽叶高茎植株与窄叶矮茎植株杂交，F1全为宽叶高茎。F1自交产生F2，若在F2中窄叶高茎植株中有一定比例在幼苗期致死，导致F2中宽叶高茎：宽叶矮茎：窄叶高茎：窄叶矮茎 = 9:3:2:1。则致死窄叶高茎植株的基因型及在该表型中所占比例为（ ）', 'A. mmNN ， 1/3
B. mmnn ， 1/2
C. mmNn ， 1/2
D. mmNN ， 1/2', 'A', '正常情况下，F1自交得到的F2中窄叶高茎（mmN_）理论比例占3/16（包含1/16 mmNN和2/16 mmNn）。而实际结果中窄叶高茎仅占2/16，说明有1/16的窄叶高茎个体在幼苗期致死，该比例恰好对应纯合子mmNN。所以在原有的窄叶高茎个体中，致死的mmNN占1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500103, '下列关于同源染色体的叙述，正确的是（ ）', 'A. 一条来自父方，一条来自母方的两条染色体一定是同源染色体
B. 减数分裂Ⅰ前期能够发生联会的两条染色体是同源染色体
C. 形状和大小完全相同的两条染色体一定是同源染色体
D. 有丝分裂后期的细胞中没有同源染色体', 'B', '来自父母双方的非同源染色体不能配对，A错误；着丝粒分裂产生的姐妹染色单体形状大小完全相同，属于相同染色体而非同源染色体，C错误；有丝分裂全过程始终含有同源染色体，D错误；在减数分裂Ⅰ前期能够两两配对、进行联会的两条染色体属于同源染色体，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500104, '控制猫毛色的基因位于X染色体上，黑色（B）对黄色（b）为共显性，杂合子（X^B X^b）表现为黑黄相间的玳瑁猫。一只玳瑁雌猫与一只黑色雄猫交配，子代中不可能出现的表型是（ ）', 'A. 黑色雌猫
B. 玳瑁雌猫
C. 黄色雄猫
D. 玳瑁雄猫', 'D', '玳瑁雌猫（XBXb）与黑色雄猫（XBY）杂交，子代基因型为XBXB（黑色雌）、XBXb（玳瑁雌）、XBY（黑色雄）、XbY（黄色雄）。正常情况下雄猫只有一条X染色体，不可能同时含XB和Xb，因此不可能出现玳瑁雄猫。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500105, '下列关于生物学史上经典实验的叙述，错误的是（ ）', 'A. 格里菲斯通过肺炎链球菌体内转化实验证明了加热杀死的S型菌中含有“转化因子”
B. 艾弗里用S型菌的DNA、蛋白质等物质分别处理R型菌，单独观察它们的作用
C. 赫尔希和蔡斯用含32P和35S的培养基直接培养T2噬菌体，从而实现了对噬菌体的标记
D. 烟草花叶病毒侵染烟草的实验证明了RNA也是某些生物的遗传物质', 'C', 'T2噬菌体是病毒，没有细胞结构，不能在无细胞的普通营养培养基上独立生长繁殖。标记噬菌体必须先使用含放射性同位素的培养基培养大肠杆菌，再让噬菌体去侵染带有标记的大肠杆菌，C项叙述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500106, '真核生物细胞核中一个双链DNA分子中含有腺嘌呤（A）占全部碱基的30%，下列关于该DNA分子的叙述，正确的是（ ）', 'A. 该DNA分子中 (A+C)/(T+G) = 1
B. 该DNA分子中胞嘧啶（C）占全部碱基的30%
C. 该DNA分子中 (A+T)/(G+C) = 1
D. 该DNA解旋后其中一条链上的 (A+G)/(T+C) 一定等于1', 'A', '双链DNA中，A=T=30%，则G=C=20%。因此嘌呤（A+G）= 50%，嘧啶（T+C）= 50%。对于(A+C)/(T+G)，分子分母皆为50%，故等于1，A正确，B、C错误；单链中不互补碱基之和的比例不一定等于1，D错误。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500107, '关于真核细胞中多聚核糖体合成蛋白质的过程，下列有关叙述正确的是（ ）', 'A. 该阶段在细胞核中进行，需要解旋酶和RNA聚合酶
B. 参与该过程的RNA只有mRNA和tRNA两种
C. 核糖体在mRNA上移动时，各个核糖体合成的肽链长度相同
D. 一个mRNA上结合多个核糖体，可同时合成多条结构相同的多肽链', 'D', '多聚核糖体合成蛋白质在细胞质中进行，不需要解旋酶和RNA聚合酶，A错误；参与该过程的还有rRNA（核糖体的组成成分），B错误；各个核糖体由于结合先后顺序不同，其上的多肽链长度不同，C错误；多个核糖体以同一条mRNA为模板，因此合成的多条多肽链结构完全相同，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500108, '某种癌细胞中控制某种蛋白质合成的基因发生了碱基对的替换，导致合成的蛋白质中一个氨基酸发生了改变。下列关于这种变异的说法，正确的是（ ）', 'A. 该变异属于染色体结构变异
B. 该变异属于非同源染色体自由组合导致的基因重组
C. 该变异会导致基因中嘌呤碱基与嘧啶碱基的比例发生改变
D. 该变异可能会改变该蛋白质的空间结构和生理功能', 'D', '碱基对替换属于基因突变，A、B错误；双链DNA中嘌呤与嘧啶固定占50%，替换不改变比例，C错误；一个氨基酸的改变可能会影响多肽链的折叠和空间结构，进而改变其生理功能，D正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500109, '用纯种的高秆抗病（DDTT）和矮秆感病（ddtt）小麦培育矮秆抗病（ddTT）优质小麦。下列有关不同育种方法的叙述，错误的是（ ）', 'A. 杂交育种过程中，F2中矮秆抗病植株占3/16，其中能稳定遗传的占1/3
B. 单倍体育种通过花药离体培养获得矮秆抗病单倍体，再用秋水仙素处理可获得ddTT
C. 诱变育种可以定向诱导矮秆感病小麦突变为矮秆抗病小麦
D. 多倍体育种常用秋水仙素处理萌发的种子或幼苗，目的是抑制纺锤体的形成', 'C', '基因突变具有不定向性，诱变育种不能定向诱导突变，C错误符合题意。杂交育种F2中矮抗（ddT_）占3/16，能稳定遗传（ddTT）占该表型的1/3，A正确；单倍体育种用花药离体培养结合秋水仙素加倍可快速获得纯合子，B正确；秋水仙素作用原理是抑制前期纺锤体的形成使染色体数目加倍，D正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500110, '下列关于种群基因库与生物进化的叙述，正确的是（ ）', 'A. 种群中每个个体都含有该种群基因库的全部基因
B. 基因突变和染色体变异会改变种群的基因频率，而基因重组不会
C. 自然选择通过定向淘汰不利变异的个体，从而定向改变种群的基因频率
D. 生物进化的实质是自然选择导致新物种的产生', 'C', '种群基因库是该种群全部个体所含有的全部基因，每个个体只含有部分基因，A错误；基因重组通过产生新的基因组合，在自然选择作用下也会改变种群基因频率，B错误；进化的实质是种群基因频率的改变，不一定会产生新物种，D错误；自然选择通过定向淘汰不利表型的个体，从而定向改变基因频率，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500111, '某种植物的红花（A）对白花（a）为显性。现有一株红花植物自交，子代中红花：白花 = 2:1。出现这种比例最可能的原因是（ ）', 'A. 显性纯合子（AA）在幼苗期致死
B. 隐性纯合子（aa）半数致死
C. 含有A基因的雄配子半数致死
D. 含有a基因的雌配子不能受精', 'A', '红花植物（A_）自交后代出现红花:白花 = 2:1，说明亲本为Aa。正常情况下Aa自交后代应为1AA:2Aa:1aa（红3:白1）。实际显性个体与隐性个体之比为2:1，说明显性纯合子（AA）致死，导致后代只有2Aa（红花）和1aa（白花），A正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500112, '家兔的毛色受两对独立遗传的等位基因控制。基因型为A_B_的个体表现为黑色，A_bb表现为褐色，aaB_和aabb表现为白色。两只黑色家兔交配，子代中黑色：褐色：白色 = 9:3:4。若让子代中的褐色家兔随机交配，后代中出现白兔的概率是（ ）', 'A. 1/9
B. 2/9
C. 1/4
D. 1/3', 'A', '黑色家兔杂交后代表型比为9:3:4，说明双亲均为AaBb。子代中的褐色家兔基因型及比例为1/3AAbb、2/3Aabb。它们随机交配，产生的配子中，b基因的频率为1，而A的频率为 1/3 + 2/3 × 1/2 = 2/3，a的频率为1/3。由于aaB_和aabb都表现为白色，只要算出aa的概率即可，aa的概率是 1/3 × 1/3 = 1/9。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500113, '下列关于高等哺乳动物减数分裂和受精作用的叙述，错误的是（ ）', 'A. 减数分裂Ⅰ后期与减数分裂Ⅱ后期细胞中的染色体组数相同
B. 受精作用依赖于细胞膜的流动性和细胞表面的糖蛋白识别
C. 减数分裂和受精作用共同维持了有性生殖生物前后代体细胞中染色体数目的恒定
D. 雌雄配子的随机结合导致了控制不同性状的非同源染色体上的基因发生重新组合', 'D', '控制不同性状的非同源染色体上的基因重新组合（即基因重组）发生在减数分裂Ⅰ过程中（前期和后期），而不是发生在受精作用中，D项叙述错误符合题意。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500114, '人类的红绿色盲（伴X隐性遗传）和白化病（常染色体隐性遗传）独立遗传。一对表现型正常的夫妇，生出了一个既患白化病又红绿色盲的儿子。则这对夫妇再生一个健康女儿的概率是（ ）', 'A. 3/8
B. 3/16
C. 1/8
D. 1/16', 'A', '设白化病基因为a，红绿色盲基因为b。表现型正常的夫妇生出了aaXbY的儿子，说明双亲基因型为AaXBXb和AaXBY。对白化病：再生孩子正常（A_）概率为3/4。对色盲：正常男性（XBY）与携带者（XBXb）生女儿必正常（XBX_），概率为1。因此，再生一个健康女儿的概率为：3/4（白化病正常） × 1/2（是女儿） × 1（色盲正常） = 3/8。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500115, '在噬菌体侵染大肠杆菌的实验中，关于赫尔希和蔡斯使用的放射性同位素标记，下列叙述正确的是（ ）', 'A. 用35S标记噬菌体的DNA，32P标记噬菌体的蛋白质外壳
B. 用32P标记的培养基直接培养噬菌体，从而获得带放射性标记的噬菌体
C. 搅拌离心后35S主要存在于上清液中，说明蛋白质外壳未进入大肠杆菌内部
D. 该实验独立证明了DNA是遗传物质，且蛋白质是次要的遗传物质', 'C', '用35S标记蛋白质，32P标记DNA，A错误；噬菌体没有细胞结构不能独立在培养基中生存，B错误；该实验证明DNA是遗传物质，不能证明蛋白质是次要遗传物质，D错误；35S标记蛋白质外壳，离心后外壳随上清液析出，说明蛋白质未进入大肠杆菌，C正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500116, '某一双链DNA分子含有1000个碱基对，其中胞嘧啶（C）占碱基总数的20%。该DNA分子连续复制4次，在第4次复制过程中，共需要消耗游离的腺嘌呤（A）脱氧核苷酸数量是（ ）', 'A. 4800个
B. 2400个
C. 9600个
D. 1200个', 'A', '总碱基数 = 1000对 = 2000个。C=20%，则A = 50% - 20% = 30%。一个DNA分子含有A = 2000 × 30% = 600个。连续复制4次产生16个DNA分子，第4次复制是指从8个DNA复制到16个DNA，净增加了 16 - 8 = 8个DNA分子。因此需要消耗游离的A = 8 × 600 = 4800个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500117, '中心法则揭示了生物遗传信息的传递方向。下列有关中心法则的叙述，正确的是（ ）', 'A. 细胞内的DNA复制、转录和翻译过程均发生在外分泌腺的高分化细胞中
B. 逆转录和RNA复制过程主要发生在高度分化的植物叶肉细胞中
C. 转录和翻译均以四种核糖核苷酸为基本原料
D. 翻译过程中tRNA上的反密码子与mRNA上的密码子进行碱基互补配对', 'D', '高度分化的外分泌腺细胞不再分裂，不进行DNA复制，A错误；逆转录和RNA复制是某些RNA病毒才特有的，不在正常的叶肉细胞中独立进行，B错误；翻译的原料是氨基酸，C错误；翻译时通过tRNA的反密码子与mRNA的密码子特异性结合，遵循碱基互补配对原则，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500118, '由于紫外线辐射，某植物根尖分生区细胞中一个控制重要表型的基因编码区发生了一对碱基对的缺失。该变异最可能导致（ ）', 'A. 该突变基因翻译出的蛋白质中，缺失位置之后的氨基酸序列全部发生改变
B. 缺失导致该分生区细胞内的姐妹染色单体无法正常分离
C. 该变异属于减数分裂发生互换引起的基因重组
D. 缺失导致染色体上基因的数目和排列顺序发生改变', 'A', '编码区缺失一个碱基对，会导致自缺失位置起往后的所有密码子全部发生框移，从而使得翻译出的蛋白质中缺失位置之后的氨基酸序列全部发生改变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500119, '下列关于染色体变异及单倍体育种的叙述，正确的是（ ）', 'A. 单倍体育种获得的目标植株由于染色体数目减半，在生产上往往表现为高度不育
B. 杂交育种和单倍体育种分别依据的遗传学原理是基因重组和染色体变异
C. 染色体结构变异会改变基因内部的碱基对排列顺序，从而产生新基因
D. 21三体综合征是由于父方减数分裂Ⅱ后期姐妹染色单体未分离导致的，与母方无关', 'B', '单倍体育种最终获得的目标植株是用秋水仙素处理加倍后的正常纯合体，是完全可育的，A错误；产生新基因的途径只有基因突变，染色体结构变异改变基因的排列顺序和数量，不能产生新基因，C错误；21三体综合征可以由于母方或父方减数分裂异常所致，D错误；B正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500120, '某一随机交配的足够大的昆虫种群中，常染色体上的显性基因A（有翅）频率为0.4，隐性基因a（无翅）频率为0.6。若该种群遭遇环境剧变，导致所有无翅个体（aa）在幼年期全部致死，则该种群耐过环境剧变后的杂合子（Aa）在存活个体中所占的比例为（ ）', 'A. 40%
B. 48%
C. 75%
D. 60%', 'C', '原本随机交配后代中，AA频率=0.4^2=0.16，Aa频率=2×0.4×0.6=0.48，aa频率=0.6^2=0.36。环境剧变导致无翅个体（aa）全部死亡，存活个体只剩AA和Aa，总比例为 0.16 + 0.48 = 0.64。因此，存活个体中杂合子（Aa）的比例为 0.48 / 0.64 = 0.75 = 75%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500121, '孟德尔通过假说-演绎法发现了两大遗传定律。下列属于其在发现分离定律时进行的“假说”内容的是（ ）', 'A. 生物表现出的显性性状和隐性性状是由不同的环境条件决定的
B. F1自交，子二代中高茎与矮茎的性状分离比接近3:1
C. 受精时，雌雄配子的结合是随机的
D. 测交实验中，F1与隐性纯合子杂交，后代产生1:1的性状分离比', 'C', 'A是错误论断；B是实验观察到的现象（发现问题）；D是根据假说进行的演绎推理。C属于孟德尔提出的假说核心内容（受精时雌雄配子随机结合）。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500122, '某种植物的果皮颜色由两对独立遗传的等位基因（A/a和B/b）控制。A基因存在时表现为红色，B基因存在时表现为黄色，当A and B基因同时存在时表现为橙色，双隐性纯合个体表现为绿色。现有一株橙色果皮植株与一株黄色果皮植株杂交，子代果皮颜色的表现型及比例为橙色：黄色：红色：绿色 = 3:3:1:1。则亲本橙色和黄色植株的基因型分别是（ ）', 'A. AaBb × aaBb
B. AaBb × aabb
C. AaBB × aaBb
D. AABb × aaBb', 'A', '由题意知，橙色为A_B_，黄色为aaB_，红色为A_bb，绿色为aabb。橙色（A_B_）与黄色（aaB_）杂交，子代出现了绿色（aabb），说明亲本皆含有a和b基因，由此可定位亲本基因型为AaBb × aaBb。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500123, '若某二倍体高等动物（2n=4）细胞中含有同源染色体，且每条染色体的着丝粒排列在赤道板上。则该细胞处于（ ）', 'A. 有丝分裂中期
B. 减数分裂Ⅰ中期
C. 减数分裂Ⅱ中期
D. 有丝分裂后期', 'A', '细胞中含有同源染色体，说明不可能是减数分裂Ⅱ；着丝粒排列在赤道板上，意味着每条染色体独立排列在赤道板中央，属于有丝分裂中期的典型特征。减数分裂Ⅰ中期是同源染色体成对排列在赤道板两侧。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500124, '果蝇的白眼基因为伴X隐性遗传。现有一群果蝇，其中雌果蝇中白眼个体占4%，雄果蝇中白眼个体占20%。若该群体随机交配，在全部子代中，白眼雌果蝇所占的比例为（ ）', 'A. 20%
B. 4%
C. 2%
D. 1%', 'C', '雄果蝇只有一条X染色体，其白眼发病率（20%）即等于该群体中白眼致病基因（w）的频率，即 q = 0.2。该群体进行随机交配，子代白眼雌果蝇（XwXw）在全部子代（含雌雄）中所占的比例计算为：1/2（是雌性） × q^2 = 1/2 × 0.2 × 0.2 = 0.02 = 2%。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500125, '下列关于真核生物体内RNA的叙述，错误的是（ ）', 'A. mRNA上的碱基序列决定了多肽链中氨基酸的排列顺序
B. tRNA分子呈三叶草形，其中含有由氢键连接形成的双链区域
C. rRNA是核糖体的组成成分，核糖体是合成蛋白质的场所
D. 真核细胞中的RNA分子只能在细胞核中转录合成，不能在细胞质中合成', 'D', '真核细胞的线粒体和叶绿体中也含有少量的DNA，可以独立进行转录和翻译，因此D项表述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500126, '在孟德尔的一对相对性状杂交实验中，为了验证对性状分离现象的解释是否正确，孟德尔设计了测交实验。测交实验是指（ ）', 'A. F1与显性纯合子杂交
B. F1与隐性纯合子杂交
C. F1与F1个体相互交配
D. 两个不同性状的纯合亲本杂交', 'B', '测交的定义就是指让杂合个体与隐性纯合子进行杂交，以此来测定受试个体的基因型或配子比例。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500127, '某种自花传粉植物的花色受两对独立遗传的等位基因（A/a、B/b）控制。基因型为A_B_和A_bb的植株开红花，aaB_的植株开黄花，aabb的植株开白花。现有一株基因型为AaBb的红花植株自交，则其子代中开红花的植株所占比例为（ ）', 'A. 9/16
B. 3/4
C. 13/16
D. 7/16', 'B', '红花植株的基因型包含A_B_和A_bb，即只要含A基因（A_）就开红花。双杂合子AaBb自交，子代中含A显性基因（A_）的概率为3/4，因此开红花的植株所占比例为3/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500128, '在哺乳动物的卵子发生过程中，减数分裂Ⅰ和减数分裂Ⅱ是连续进行的。下列关于卵细胞形成过程的叙述，正确的是（ ）', 'A. 初级卵母细胞在减数分裂Ⅰ后期发生细胞质的均等分裂
B. 次级卵母细胞在减数分裂Ⅱ后期不发生着丝粒的分裂
C. 一个初级卵母细胞经过减数分裂最终只形成一个成熟的卵细胞和三个极体
D. 卵细胞形成过程中的减数分裂均在卵巢中连续且完整地完成', 'C', '初级卵母细胞在减Ⅰ后期发生细胞质不均等分裂，A错误；次级卵母细胞在减Ⅱ后期发生着丝粒分裂，B错误；哺乳动物减数分裂Ⅱ通常在输卵管中受精时才完成，并非完全在卵巢内，D错误；一个初级卵母细胞最终产生1个成熟卵细胞和3个极体，C正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500129, '某家族中有甲、乙两种单基因遗传病，其中一种病的致病基因位于X染色体上。已知正常的双亲生出了一个同时患有甲病和乙病的儿子。据此推断，正常情况下，该患病儿子的致病基因分别来自（ ）', 'A. 甲、乙两病的致病基因均来自母亲
B. 至少有一种病的致病基因来自父亲
C. 伴X遗传病的致病基因一定来自母亲，常染色体遗传病的致病基因来自父母双方
D. 两病的致病基因均由父母双方各提供一个', 'C', '双亲正常生出患病儿子，两病皆为隐性。对于伴X隐性遗传病，致病基因一定来自于母亲；对于常染色体隐性遗传病，致病基因则由父母双方各提供一个。因此，儿子的伴X病基因来自母亲，常染色体病基因来自父母双方，C正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500130, '在艾弗里的肺炎链球菌转化实验中，能够使R型细菌转化为S型细菌的是（ ）', 'A. 加热杀死的S型细菌的蛋白质
B. 活的S型细菌的荚膜多糖
C. S型细菌的DNA与DNA酶的混合物
D. 从S型细菌中提取并提纯的DNA', 'D', '艾弗里体外转化实验证明，只有提纯的S型菌DNA能使R型菌发生转化，而蛋白质、多糖均不能。DNA酶会将DNA水解使其失去转化功能。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500131, '科学家梅塞尔森和斯塔尔通过大肠杆菌的培养实验，运用同位素标记法和密度梯度离心技术，证明了DNA的复制方式是半保留复制。若将DNA双链均被15N标记的大肠杆菌放入含有14N的培养基中连续繁殖3代，提取其DNA进行离心，离心管中出现的DNA条带情况是（ ）', 'A. 只有轻带（14N/14N）和中带（15N/14N），且比例为3:1
B. 只有轻带（14N/14N）和中带（15N/14N），且比例为1:1
C. 只有中带（15N/14N）和重带（15N/15N），且比例为3:1
D. 出现轻、中、重三条带，比例为2:1:1', 'A', '15N15N的DNA在14N培养基中连续复制3代产生8个DNA。根据半保留复制，亲代的两条15N单链分别分配到2个DNA中，形成2个15N14N的DNA（中带）；其余6个DNA双链皆为14N14N（轻带）。轻带:中带 = 6:2 = 3:1。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500132, '下列关于遗传密码（密码子）的叙述，错误的是（ ）', 'A. 密码子存在于mRNA上，是由三个相邻的碱基组成的序列
B. 几乎所有的生物都共用一套遗传密码，说明生物界具有统一性
C. 一种氨基酸可以由一种或多种密码子决定，这称为密码子的简并
D. 密码子的读取方式是重叠读取的，即一个碱基可以被读取两次', 'D', '密码子的读取方式是非重叠的、连续的，一个碱基在一个读码框内只能被读取一次，不可重叠读取，D项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500133, '物理因素（如X射线、紫外线）和化学因素（如亚硝酸、秋水仙素）都可能诱发基因突变。下列关于诱发突变的叙述，正确的是（ ）', 'A. 诱发突变能够定向改变生物的性状，满足人类需求
B. 紫外线主要通过引起DNA分子中碱基对的替换、增添或缺失来诱发突变
C. 秋水仙素既能诱发基因突变，又能诱导染色体数目加倍
D. 物理因素诱发的突变一定是有害的，化学因素诱发的突变一定是有利的', 'C', '突变是不定向的，A错误；紫外线主要通过诱发碱基形式改变从而产生突变，B错误；秋水仙素在有丝分裂前期能抑制纺锤体形成引发染色体加倍，同时作为一种化学药剂也能诱发基因突变，C正确；突变大多有害，少数有利，D错误。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500134, '水稻的体细胞中含有24条染色体。用花药离体培养技术获得的水稻幼苗，其叶肉细胞中含有的染色体数和染色体组数分别是（ ）', 'A. 24条，2个
B. 12条，1个
C. 12条，2个
D. 48条，4个', 'B', '正常二倍体水稻体细胞含24条染色体（2个染色体组）。花药离体培养获得的单倍体幼苗，其体细胞染色体数目减半，变为12条，染色体组数变为1个。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500135, '在某个随机交配的果蝇种群中，灰身（B）对黑身（b）为显性。假设在一个由1000只果蝇组成的种群中，基因型为BB、Bb、bb的个体分别有400只、500只、100只。则该种群中b基因的频率是（ ）', 'A. 35%
B. 40%
C. 55%
D. 65%', 'A', 'b基因的频率 = (bb个体数 × 2 + Bb个体数) / (总个体数 × 2) = (100 × 2 + 500) / (1000 × 2) = 700 / 2000 = 0.35 = 35%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500136, '在进行豌豆的人工异花传粉实验时，正确的操作步骤和目的是（ ）', 'A. 花开后去雄，目的防止自花传粉
B. 去雄后套袋，目的是防止外来花粉的干扰
C. 传粉前不套袋，传粉后套袋，以保证接受特定花粉
D. 无论父本还是母本，均需要进行去雄操作', 'B', '去雄必须在花蕾期（花开前）进行，A错误；传粉前和传粉后都需要套袋隔离，C错误；只有母本需要去雄，父本提供花粉不需要去雄，D错误；去雄及传粉后都要套袋，其目的是防止外来花粉的干扰，B正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500137, '基因型为AaBbCc的个体（三对等位基因独立遗传），在减数分裂产生配子时，能产生含有全部隐性基因（abc）的配子的概率是（ ）', 'A. 1/4
B. 1/8
C. 1/16
D. 1/64', 'B', '每对等位基因在产生配子时独立分离，产生隐性基因的概率均为1/2。因此，能产生含有全部隐性基因（abc）的配子的概率为 1/2 × 1/2 × 1/2 = 1/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500138, '下列关于人体细胞分裂过程中DNA和染色体数目变化的叙述，正确的是（ ）', 'A. 有丝分裂后期与减数分裂Ⅱ后期细胞中的DNA含量相同
B. 减数分裂Ⅰ前期细胞中的染色体数是减数分裂Ⅱ前期的两倍
C. 受精卵第一次有丝分裂中期与减数分裂Ⅰ中期细胞内的染色单体数不同
D. 精细胞变形成为精子的过程中，细胞核内的染色体数目会减半', 'B', '有丝分裂后期含有4n个DNA，减数分裂Ⅱ后期含有2n个DNA，A错误；受精卵第一次有丝分裂中期与减数分裂Ⅰ中期，核内染色体和单体数均相同（皆为46条染色体，92条单体），C错误；精细胞到精子是形态变形，核内染色体数保持不变，D错误；减数分裂Ⅰ前期含2n（46）条染色体，减数分裂Ⅱ前期含n（23）条，是其两倍，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500139, '某地发现一种极为罕见的人类单基因遗传病。研究表明，该病在男性群体中的发病率约为1/100，而在女性群体中的发病率约为1/10000。据此可初步判断该病的遗传方式最可能是（ ）', 'A. 常染色体显性遗传
B. 常染色体隐性遗传
C. 伴X染色体显性遗传
D. 伴X染色体隐性遗传', 'D', '该病在男女群体中的发病率存在显著性别差异，且男性发病率（1/100）远高于女性（1/10000，正好是男性的平方），符合伴X染色体隐性遗传病的典型群体发病特征。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500140, '关于证明DNA是遗传物质的一系列经典实验，下列说法正确的是（ ）', 'A. 肺炎链球菌体内转化实验直接证明了加热杀死的S型细菌的DNA是转化因子
B. 噬菌体侵染细菌实验中，若搅拌不充分会导致上清液中35S放射性偏低
C. 噬菌体侵染细菌实验中，离心后沉淀物主要是噬菌体的蛋白质外壳
D. 提取烟草花叶病毒的蛋白质侵染烟草叶片，叶片会出现病斑', 'B', '体内转化实验没有证明DNA是转化因子，A错误；离心后沉淀物主要是大肠杆菌，C错误；烟草花叶病毒蛋白质侵染不会产生病斑，D错误；用35S标记蛋白质外壳时，若搅拌不充分，部分蛋白质外壳仍附着在大肠杆菌表面，随细菌一起沉淀，从而导致上清液中的放射性偏低，B正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500141, '若将某双链DNA分子（由1000个碱基对组成，其中鸟嘌呤占20%）放在含有32P标记的脱氧核苷酸培养液中复制两代。则子代中含32P的DNA分子数以及复制过程中需要消耗的游离胸腺嘧啶（T）脱氧核苷酸数分别是（ ）', 'A. 2个，1800个
B. 4个，1800个
C. 2个，2400个
D. 4个，2400个', 'B', '双链DNA分子复制两代共产生4个DNA分子。由于复制方式为半保留复制，游离的原料均带有32P，因此最终所有的子代DNA分子（4个）都含有32P。该DNA含有1000个碱基对，即2000个碱基，G=20%，根据碱基互补配对原则，T = 50% - 20% = 30%，一个DNA分子中含T = 2000 × 30% = 600个。复制2代净增加 4 - 1 = 3个DNA，共需消耗游离的T = 3 × 600 = 1800个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500142, '原核生物与真核生物在基因表达过程中的主要区别是（ ）', 'A. 原核生物没有tRNA，真核生物有tRNA
B. 原核生物的转录和翻译可以同时同地进行，真核生物通常先在细胞核内转录后在细胞质中翻译
C. 原核生物只共用少数几种密码子，真核生物共用全套64种密码子
D. 原核生物翻译时不需要核糖体，真核生物需要', 'B', '原核细胞没有核膜阻隔，其转录尚未完全结束时翻译即可在核糖体上开始，即转录和翻译可以同时同地进行；而真核细胞具有核膜，转录在细胞核内完成，成熟的mRNA必须通过核孔进入细胞质才能进行翻译。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500143, '基因突变产生的新基因能在自然选择的作用下得以保留或被淘汰。下列关于基因突变生理意义的叙述，错误的是（ ）', 'A. 基因突变是新基因产生的根本途径
B. 基因突变为生物进化提供了丰富的原材料
C. 基因突变是生物变异的根本来源
D. 基因突变产生的性状一定能够遗传给下一代', 'D', '基因突变如果发生在体细胞中，通常只能通过无性生殖遗传，而在有性生殖中一般无法遗传给下一代；只有发生在生殖细胞中的突变才更容易通过配子遗传给下一代。因此D项叙述错误符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500144, '利用基因工程技术培育转基因抗虫棉的过程中，核心步骤是将目的基因（如Bt毒蛋白基因）导入受体细胞并使其成功表达。这种育种技术依据的遗传学原理是（ ）', 'A. 基因突变
B. 基因重组
C. 染色体结构变异
D. 染色体数目变异', 'B', '基因工程技术是在生物体外对DNA分子进行人工剪切和拼接，然后导入受体细胞内进行扩增和表达的技术，其定向改造生物性状的遗传学原理属于广义的基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500145, '按照现代生物进化理论的观点，下列叙述正确的是（ ）', 'A. 个体是生物进化的基本单位
B. 突变和基因重组决定生物进化的方向
C. 生物进化的实质是种群基因型频率的定向改变
D. 自然选择直接作用于生物个体的表型', 'D', '种群是生物进化的基本单位，A错误；自然选择决定生物进化的方向，B错误；进化的实质是种群基因频率的定向改变，C错误；自然选择不能直接对基因进行筛选，而是通过直接作用于生物个体的表型（性状），从而间接对基因进行选择，D正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500146, '南瓜的果实形状有盘状和球状两种。纯合盘状南瓜与纯合球状南瓜杂交，F1全是盘状南瓜；F1自交，F2中盘状与球状的比例为3:1。下列能够确认南瓜果实形状显隐性关系的实验组合是（ ）', 'A. 盘状×盘状 → 盘状、球状
B. 盘状×球状 → 全是盘状
C. 球状×球状 → 全是球状
D. A选项和B选项均可以', 'D', '判断显隐性的方法有两种：①具有相同性状的亲本杂交，后代出现性状分离，新出现的性状为隐性（A项正确）；②具有相对性状的纯合亲本杂交，后代只表现出一个亲本的性状，表现出来的性状为显性（B项正确）。因此D正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500147, '某植物具有黄花（Y）和白花（y）、宽叶（W）和窄叶（w）两对相对性状，且这两对等位基因独立遗传。现将纯合黄花宽叶与白花窄叶植株杂交得到F1，F1自交产生F2。已知含有y基因的花粉有50%不育，则F2中黄花宽叶植株所占的比例为（ ）', 'A. 9/16
B. 15/32
C. 21/32
D. 24/45', 'D', 'F1为YyWw。由于两对基因独立遗传，可分开计算。对于W/w：Ww自交后代宽叶（W_）占3/4。对于Y/y：F1产生的卵细胞为1/2Y、1/2y；而雄配子中含y的花粉半数不育，故可育精子中Y占2/3，y占1/3。雌雄配子结合，F2中yy = 1/2 × 1/3 = 1/6，则黄花（Y_） = 1 - 1/6 = 5/6。因此F2中黄花宽叶（Y_W_）的比例为 5/6 × 3/4 = 15/24 = 24/45（等比缩放）。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500148, '在显微镜下观察基因型为AaBb的高等动物精巢内的正常细胞分裂，发现某细胞内含有两对同源染色体，但没有姐妹染色单体。该细胞所处的时期是（ ）', 'A. 减数分裂Ⅰ后期
B. 减数分裂Ⅱ后期
C. 有丝分裂后期
D. 有丝分裂末期或减数分裂Ⅱ末期之后', 'D', '精巢内正常体细胞含有2对（4条）同源染色体。减数分裂Ⅰ后期含有姐妹染色单体，A错误；减数分裂Ⅱ后期不含同源染色体，B错误；有丝分裂后期着丝粒分裂，染色体数目加倍，含有4对（8条）染色体，C错误；分裂结束后的细胞（精原细胞或体细胞）含有2对同源染色体且无姐妹染色单体，符合题意。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500149, '人类血友病由X染色体上的隐性基因（h）控制。一对表现型正常的夫妇生了一个患血友病且多了一条X染色体的儿子（性染色体组成为XXY）。若不考虑基因突变，导致该异常儿子产生的最可能原因是（ ）', 'A. 母亲在卵细胞形成过程的减数分裂Ⅰ后期两条X染色体未分离
B. 母亲在卵细胞形成过程的减数分裂Ⅱ后期姐妹染色单体未分离
C. 父亲在精子形成过程的减数分裂Ⅰ后期X、Y染色体未分离
D. 父亲在精子形成过程的减数分裂Ⅱ后期姐妹染色单体未分离', 'B', '双亲正常（XHX- × XHY），生出患血友病的XXY儿子（XhXhY）。儿子的基因型里含有两个Xh，而父亲没有Xh基因，说明这两个Xh只能全部来自于母亲。母方表型正常，必然是携带者（XHXh）。由于产生了含XhXh的异常卵细胞，说明是在减数分裂Ⅱ后期，带有h基因的姐妹染色单体分开后未分离，移向了同一极，B正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500150, '在进行“噬菌体侵染大肠杆菌”的实验中，需要进行短时间的保温，随后进行搅拌和离心操作。下列关于这些操作目的的叙述，错误的是（ ）', 'A. 保温的目的让噬菌体将遗传物质注入大肠杆菌内部
B. 保温时间过长会导致部分大肠杆菌裂解，子代噬菌体释放，影响实验结果
C. 搅拌的目的是使吸附在大肠杆菌上的噬菌体蛋白质外壳与细菌分离
D. 离心的目的是促使噬菌体的DNA与蛋白质外壳发生彻底分离', 'D', '搅拌的目的是使吸附在细菌表面的蛋白质外壳与细菌分离开来；而离心的目的则是为了让大肠杆菌（由于质量重而沉淀在底部）与分布在上清液中的噬菌体蛋白质外壳分层，D项叙述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500151, '某种小鼠的皮毛颜色由常染色体上的一对等位基因控制，黄色（A）对黑色（a）为显性。已知基因型为AA的个体在胚胎期致死。现将两只黄色小鼠交配，子代中黄色小鼠与黑色小鼠的比例为（ ）', 'A. 3:1
B. 2:1
C. 1:1
D. 4:1', 'B', '两只黄色小鼠必然是杂合子Aa。它们交配后代基因型理论比为1AA:2Aa:1aa。由于显性纯合子（AA）在胚胎期致死，因此存活下来的小鼠只有2Aa（黄色）和1aa（黑色），比例为2:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500152, '某自花传粉植物的株高受两对独立遗传的等位基因（A/a、B/b）控制。只要含有显性基因就表现为高茎，双隐性纯合子表现为矮茎。现有一株基因型为AaBb的高茎植株自交，子代中高茎与矮茎的比例为（ ）', 'A. 9:7
B. 15:1
C. 13:3
D. 9:6:1', 'B', '双杂合子自交后代基因型比例符合9:3:3:1。只要含有一个或以上的显性基因（A_B_占9/16、A_bb占3/16、aaB_占3/16）均表现为高茎，合计占15/16；只有双隐性纯合子aabb（占1/16）表现为矮茎。因此高茎:矮茎 = 15:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500153, '在观察某二倍体高等植物细胞减数分裂的实验中，若发现在某一时期的细胞中，每一极的染色体数目与体细胞相同，且不存在染色单体。则该细胞处于（ ）', 'A. 减数分裂Ⅰ后期
B. 减数分裂Ⅱ后期
C. 有丝分裂后期
D. 减数分裂Ⅱ末期', 'B', '植物体细胞染色体数为2n。减数分裂Ⅰ结束后，次级卵/精母细胞中染色体数减半为n。在减数分裂Ⅱ后期，着丝粒分裂，染色体数目短暂加倍为2n，并分别移向两极，因此每一极的染色体数目为n（由于分裂尚未彻底结束，处于同一细胞内的每一极染色体数和体细胞相同均为2n的分配格局），且不存在染色单体，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500154, '抗维生素D佝偻病为伴X染色体显性遗传病，红绿色盲为伴X染色体隐性遗传病。一对表现型正常的夫妇生了一个患红绿色盲的儿子。下列说法正确的是（ ）', 'A. 患红绿色盲儿子的致病基因来自其父亲
B. 该夫妇再生一个儿子，患红绿色盲的概率为1/2
C. 母亲的体细胞中一定不含有抗维生素D佝偻病的致病基因
D. 若该夫妇生出一个患抗维生素D佝偻病的女儿，一定是由于父亲发生了基因突变', 'B', '红绿色盲儿子的Xb来自母亲，A错误；双亲正常，则母亲为红绿色盲携带者，再生儿子患色盲概率为1/2，B正确；母亲表现正常，由于该病为显性病，其体内一定不含佝偻病致病基因，C项表述过于绝对（若母亲发生新发突变则另当别论，但常态下不含），但最科学的是B。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500155, '在艾弗里的肺炎链球菌转化实验中，他将提取出的S型细菌的DNA分为若干份，分别用不同的酶处理后加入到含R型活细菌的培养基中。下列实验结果正确的是（ ）', 'A. 加入蛋白酶的培养基中只长出R型细菌
B. 加入RNA酶的培养基中只长出S型细菌
C. 加入DNA酶的培养基中只长出R型细菌
D. 加入酯酶的培养基中长出的全部是S型细菌', 'C', '加入DNA酶后，S型菌的DNA被破坏，无法引导R型菌发生转化，因此该组培养基中只长出R型细菌，C正确；其余组别由于DNA未受破坏，均会同时长出R型和S型菌落。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500156, '科学家利用15N同位素标记大肠杆菌的DNA，探究DNA的复制方式。若将15N标记的大肠杆菌（其DNA双链均为15N）转移到含14N的培养基中培养，经过两次分裂后，提取其DNA进行密度梯度离心。离心管中DNA条带的分布情况是（ ）', 'A. 1/2重带（15N/15N），1/2轻带（14N/14N）
B. 1/2中带（15N/14N），1/2轻带（14N/14N）
C. 全部为中带（15N/14N）
D. 1/4重带，3/4轻带', 'B', '亲代DNA双链为15N15N。在14N原料中复制1次得到2个15N14N的DNA（中带）。复制2次共得到4个DNA分子，根据半保留复制，其中有2个仍为15N14N（中带），2个为14N14N（轻带），中带与轻带比例为1:1。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500157, '在真核细胞中，某基因编码区发生了一个碱基对的插入。这一突变最可能导致的结果是（ ）', 'A. 该基因转录产生的mRNA长度变短
B. 该基因翻译出的多肽链在插入位点之后的氨基酸序列全部发生改变
C. 该基因的表达产物一定丧失原有的生理功能
D. 突变后的基因不再遵循碱基互补配对原则', 'B', '编码区插入一个碱基对属于移码突变，会导致自插入位点往后的所有三联体密码子全部发生读码框移位，从而使得翻译出的多肽链在插入位点之后的氨基酸序列全部发生改变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500158, '下列有关生物变异的说法，正确的是（ ）', 'A. 病毒的基因突变只能发生在宿主细胞内
B. 基因突变和基因重组都能在光学显微镜下观察到
C. 无性生殖的生物也能发生基因重组
D. 染色体交叉互换导致的变异属于染色体结构变异', 'A', '病毒不具细胞结构，其核酸复制与变异只能寄生在宿主细胞内完成，A正确；基因突变与重组是分子水平改变，显微镜下不可见，B错误；自然条件下基因重组只发生在有性生殖的减数分裂中，C错误；同源染色体交叉互换属于基因重组，D错误。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500159, '我国科学家利用野生水稻和栽培水稻进行杂交，培育出了高产的杂交水稻。这种育种方法的主要原理是（ ）', 'A. 基因突变
B. 基因重组
C. 染色体结构变异
D. 染色体数目变异', 'B', '杂交育种是将两个或多个品种的优良性状通过交配集中在一起，再经过选择和培育获得新品种的方法，其核心遗传学原理是基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500160, '某小岛上生活着一种昆虫，经调查其翅型基因型频率为：AA占30%，Aa占60%，aa占10%。如果由于某次强台风，导致该种群中20%的aa个体死亡，且其他个体均存活并能随机交配。则存活种群中A基因的频率约为（ ）', 'A. 50%
B. 60%
C. 61.2%
D. 65.3%', 'C', '强台风后存活个体比例变为：AA占30，Aa占60，aa占 10 × (1 - 20%) = 8。此时总数变为 30 + 60 + 8 = 98。则存活种群中A的基因频率 = (30 × 2 + 60) / (98 × 2) = 120 / 196 ≈ 61.2%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500161, '基因分离定律的实质是（ ）', 'A. 杂合子自交后代出现3:1的性状分离比
B. 杂合子测交后代出现1:1的性状分离比
C. 减数分裂Ⅰ后期，同源染色体上的等位基因随同源染色体的分开而分离
D. 受精时，雌雄配子随机结合形成合子', 'C', '基因分离定律的细胞学基础与核心实质是：杂合子在进行减数分裂形成配子时，位于同源染色体上的等位基因随着同源染色体的分开而分离，独立地随配子遗传给后代。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500162, '在某植物中，A和B两对基因均显性时表现为红色，只有A没有B时表现为粉色，只有B没有A或双隐性时表现为白色。若两对基因独立遗传，则AaBb自交，子代的表型及比例为（ ）', 'A. 红:粉:白 = 9:3:4
B. 红:粉:白 = 12:3:1
C. 红:粉:白 = 9:6:1
D. 红:粉:白 = 9:4:3', 'A', '双杂合子自交后代基因型比例为9A_B_:3A_bb:3aaB_:1aabb。由题意知，A_B_（占9/16）表现为红色；A_bb（占3/16）表现为粉色；aaB_（3/16）和aabb（1/16）均表现为白色（合计占4/16）。因此子代比为 红:粉:白 = 9:3:4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500163, '人的精原细胞在进行减数分裂时，会发生一系列复杂的变化。下列关于这一过程的叙述，错误的是（ ）', 'A. 减数分裂Ⅰ前期，同源染色体两两配对形成四分体
B. 减数分裂Ⅰ后期，非同源染色体自由组合，增加了配子的多样性
C. 减数分裂Ⅱ中期，细胞核中DNA分子数与染色体数的比值为1:1
D. 整个减数分裂过程中，染色体只复制一次，而细胞分裂两次', 'C', '减数分裂Ⅱ中期，每条染色体依然含有两条姐妹染色单体，其着丝粒尚未分裂。因此细胞核内DNA分子数与染色体数的比值应为2:1，C项叙述错误符合题意。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500164, '鸟类的性别决定方式是ZW型。某种鸟的羽色受Z染色体上的一对等位基因控制，条纹羽（B）对纯色羽（b）为显性。现欲通过子代的羽色直接判断其性别，应选择的亲本杂交组合是（ ）', 'A. 纯色羽雄鸟 × 纯色羽雌鸟
B. 纯色羽雄鸟 × 条纹羽雌鸟
C. 条纹羽雄鸟 × 纯色羽雌鸟
D. 杂合条纹羽雄鸟 × 条纹羽雌鸟', 'B', '选择纯色羽雄鸟（ZbZb）与条纹羽雌鸟（ZBW）交配。子代中雄鸟基因型全部为ZBZb（表现为条纹羽），雌鸟基因型全部为ZbW（表现为纯色羽）。通过这种交叉遗传的规律，即可直接通过羽毛颜色鉴定雏鸟性别。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500165, '在赫尔希和蔡斯的实验中，用32P标记的T2噬菌体侵染大肠杆菌后，经离心发现上清液中也具有一定的放射性。产生这种现象的最可能原因是（ ）', 'A. 噬菌体的蛋白质外壳中含有少量的磷元素
B. 部分噬菌体还没有来得及将DNA注入大肠杆菌内部
C. 噬菌体的DNA有一部分留在了大肠杆菌外部
D. 大肠杆菌的遗传物质也是DNA，故上清液有放射性', 'B', '32P标记的是DNA。如果保温时间过短，部分噬菌体还未将DNA注入细菌体内，搅拌离心后这部分DNA会随噬菌体外壳分布在上清液中；若保温时间过长，子代噬菌体释放也会增大上清液放射性。B项表述最合理。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500166, '某双链DNA分子中，若(A+T)/(G+C)的值为0.5。则该DNA分子的互补单链中，(A+T)/(G+C)的值为（ ）', 'A. 0.5
B. 1
C. 2
D. 无法确定', 'A', '根据碱基互补配对原则，整个双链DNA分子中的互补碱基之和的比值，等于其中任意一条单链中的该碱基比值。因此单链中的(A+T)/(G+C)的值与双链完全相同，仍为0.5。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500167, '已知甲硫氨酸的密码子是AUG，则转运甲硫氨酸的tRNA上，与该密码子互补配对的反密码子序列（按5''→3''方向读取）通常为（ ）', 'A. TAC
B. UAC
C. CAU
D. GUA', 'C', 'mRNA上的密码子为5''-AUG-3''。与其互补配对的tRNA反密码子按反向平行配对原则应为3''-UAC-5''。题目要求按5''→3''方向读取，颠倒过来即为5''-CAU-3''。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500168, '人类镰状细胞贫血症的直接原因是血红蛋白分子中一个谷氨酸被缬氨酸替换。导致这一变化的根本原因是（ ）', 'A. tRNA装载了错误的氨基酸
B. 细胞中缺少谷氨酸这种原料
C. 控制血红蛋白合成的基因发生了碱基对的替换
D. 翻译过程中核糖体发生了功能障碍', 'C', '蛋白质结构异常的直接原因是氨基酸被替换，而导致这一现象的生命科学根本原因则是控制该蛋白质合成的血红蛋白基因内部发生了碱基对的替换（基因突变）。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500169, '下列关于秋水仙素在多倍体育种中作用机制的叙述，正确的是（ ）', 'A. 秋水仙素能够促进细胞核内DNA的复制
B. 秋水仙素主要作用于有丝分裂的前期，抑制纺锤体的形成
C. 秋水仙素主要作用于有丝分裂的后期，阻止姐妹染色单体的分离
D. 秋水仙素能够诱发染色体片段的缺失或重复', 'B', '秋水仙素的作用机理是通过特异性抑制有丝分裂前期纺锤体的形成，从而导致染色体分裂后无法移向细胞两极，使细胞内的染色体数目加倍。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500170, '按照现代生物进化理论，下列关于新物种形成的叙述，错误的是（ ）', 'A. 新物种的形成不一定都需要经过长期的地理隔离
B. 基因频率的改变标志着新物种的形成
C. 产生生殖隔离是新物种形成的标志
D. 突变和基因重组为新物种的形成提供了原材料', 'B', '种群基因频率的改变是生物进化的实质，并不意味着新物种的形成；新物种形成的标志是产生生殖隔离，B项叙述错误符合题意。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500171, '纯种黄色圆粒豌豆（YYRR）与绿色皱粒豌豆（yyrr）杂交得F1，F1自交得F2。在F2的绿色圆粒豌豆中，能稳定遗传的个体占（ ）', 'A. 1/16
B. 1/8
C. 1/3
D. 2/3', 'C', 'F2中绿色圆粒的基因型组成为 1/16 yyRR 和 2/16 yyRr，合计占3/16。在这部分绿色圆粒豌豆中，能稳定遗传的纯合子（yyRR）占其中的 1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500172, '已知某种花卉的花色受独立遗传的两对等位基因控制，基因型为A_B_的开红花，A_bb开紫花，aaB_和aabb开白花。若将基因型为AaBb的植株进行测交，则其后代的表现型及比例为（ ）', 'A. 1:1:2
B. 1:2:1
C. 2:1:1
D. 9:3:4', 'A', '双杂合子AaBb与隐性纯合子aabb测交，后代基因型比为1AaBb:1Aabb:1aaBb:1aabb。对应表型为：1红花（AaBb）、1紫花（Aabb）、2白花（aaBb和aabb）。因此测交后代比为 红:紫:白 = 1:1:2。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500173, '一个基因型为AaX^bY的果蝇精原细胞，在正常的减数分裂过程中，产生了一个基因型为AAaX^b的精子。与之同时产生的另外三个精子的基因型是（ ）', 'A. aX^b、Y、Y
B. aX^b、aY、aY
C. aX^b、X^b、Y
D. aX^b、aX^b、Y', 'A', '一个精原细胞产生一个含AAaX^b的精子，说明在减数分裂Ⅰ时A-a所在的同源染色体未分离一同移向了细胞一极，同时X^b和Y正常分离，形成了AAaaX^bX^b和YY的两个次级精母细胞。在减数分裂Ⅱ时，含AAaaX^bX^b的次级精母细胞中，带有A的姐妹染色单体分开后未分离移向同一极，产生了AAaX^b和aX^b的两个精子；另一个含YY的次级精母细胞则正常分裂产生两个Y精子。故另外三个精子为aX^b、Y、Y。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500174, '在调查人类某种单基因遗传病时，发现该病患者中女性多于男性，且男患者的女儿均患病。该遗传病的遗传方式最可能是（ ）', 'A. 伴Y染色体遗传
B. 伴X染色体隐性遗传
C. 伴X染色体显性遗传
D. 常染色体显性遗传', 'C', '女性患者多于男性患者，且男患者（XBY）的显性致病基因XB必然全额传给女儿，导致其女儿均患病，这属于典型的伴X染色体显性遗传病的特征。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500175, '假设某DNA分子中有1000个碱基对，其中含有400个腺嘌呤（A）。若该DNA分子连续复制3次，则第3次复制时需要游离的胞嘧啶脱氧核苷酸数量是（ ）', 'A. 2400个
B. 4200个
C. 600个
D. 4800个', 'D', '总碱基2000个，A=400个，则C = 1000 - 400 = 600个。连续复制3次共产生8个DNA分子。第3次复制是指由4个DNA增殖到8个DNA的过程，净增加了 8 - 4 = 4个DNA分子。因此第3次复制需要消耗游离的C = 4 × 600 = 2400个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500176, '水稻的非糯性和糯性是一对相对性状，非糯性花粉中所含的淀粉为直链淀粉，遇碘变蓝黑色；糯性花粉中所含的淀粉为支链淀粉，遇碘变橙红色。下列杂交组合中，能直接用来验证基因分离定律的是（ ）', 'A. 非糯性纯合子 × 糯性纯合子
B. 杂合非糯性植株自交
C. 取杂合非糯性植株的花粉用碘液染色后在显微镜下观察
D. 杂合非糯性植株相互授粉', 'C', '验证基因分离定律最直接的方法是观察杂合子产生的配子比例。杂合非糯性水稻（Aa）产生的花粉有A（非糯性）和a（糯性），比例为1:1。利用碘液染色后，在显微镜下可以直接观察到一半蓝黑色、一半橙红色，直接印证了等位基因在产生配子时发生分离。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500177, '某自花传粉植物的花色有红色和白色两种，受两对独立遗传的等位基因（A/a，B/b）控制。现用纯合红花植株与纯合白花植株杂交，F1全是红花。F1自交，F2中红花：白花 = 9:7。若将F1与基因型为aabb的白花植株测交，其后代中红花与白花的比例为（ ）', 'A. 1:1
B. 1:3
C. 3:1
D. 1:1:1:1', 'B', 'F2出现9:7的分离比，说明红花必须同时含有显性基因A和B（A_B_），其余基因型（A_bb、aaB_、aabb）均为白花。F1的基因型为AaBb，其与aabb测交后代基因型比例为1AaBb:1Aabb:1aaBb:1aabb。其中只有AaBb表现为红花（占1/4），其余3/4均为白花。因此测交后代红花:白花 = 1:3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500178, '下列关于高等动物细胞减数分裂和有丝分裂的比较，正确的是（ ）', 'A. 有丝分裂和减数分裂过程中都会发生同源染色体的联会
B. 有丝分裂后期和减数分裂Ⅱ后期都会发生着丝粒的分裂
C. 有丝分裂和减数分裂产生的子细胞中染色体组数均与亲代细胞相同
D. 减数分裂Ⅰ后期与有丝分裂后期细胞中含有的核DNA分子数不同', 'B', '同源染色体联会只发生在减数分裂Ⅰ前期，A错误；减数分裂产生的子细胞染色体组数减半，C错误；体细胞（2n）在有丝分裂后期核DNA为4n，减数分裂Ⅰ后期核DNA也为4n，两者相同，D错误；有丝分裂后期和减数分裂Ⅱ后期细胞中的姐妹染色单体都会由于着丝粒的分裂而分开成为染色体，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500179, '人类红绿色盲是伴X染色体隐性遗传病，白化病是常染色体隐性遗传病。一对表现正常的夫妇，生了一个既患白化病又患红绿色盲的儿子。这对夫妇再生一个孩子，表现正常的概率是（ ）', 'A. 9/16
B. 3/16
C. 1/4
D. 7/16', 'A', '设白化病基因为a，红绿色盲基因为b。双亲表现正常却生出患两病的儿子（aaXbY），说明父母的基因型为AaXBY和AaXBXb。分开计算：后代关于白化病正常的概率（A_）为3/4；关于色盲正常的概率（XBXB、XBXb、XBY）为3/4。由于两对基因独立遗传，因此再生一个孩子完全表现正常的概率为 3/4 × 3/4 = 9/16。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500180, '在艾弗里及其同事进行的肺炎链球菌体外转化实验中，能够说明DNA是转化因子、蛋白质不是转化因子的关键设计思路是（ ）', 'A. 将S型细菌的DNA和蛋白质等物质分离开，单独观察它们的作用
B. 用放射性同位素分别标记DNA和蛋白质
C. 将S型细菌加热杀死后与R型活细菌混合培养
D. 观察S型细菌和R型细菌在培养基上形成的菌落形态差异', 'A', '艾弗里实验最核心的独创之处在于设法把S型细菌体内的DNA、蛋白质、多糖等物质彻底分离开来，单独地、直接地去观察它们各自对R型细菌的转化效应，从而确切地证明了DNA是遗传物质，A正确。该实验未用到同位素标记，B错误。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500181, '在一个双链DNA分子中，若腺嘌呤（A）占全部碱基的22%，则胞嘧啶（C）占全部碱基的比例以及该DNA分子中(A+G)/(T+C)的值分别是（ ）', 'A. 28% ； 1
B. 28% ； 0.78
C. 22% ； 1
D. 78% ； 0.28', 'A', '在双链DNA分子中，遵循碱基互补配对原则（A=T，G=C），不互补的两个碱基之和占总数的一半（A+C=50%）。已知A=22%，则C = 50% - 22% = 28%。同时由于嘌呤总数（A+G）恒等于嘧啶总数（T+C），因此(A+G)/(T+C)的值在任意双链DNA中都恒等于1。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500182, '如图所示，一条mRNA上结合了多个核糖体（多聚核糖体）进行翻译过程。下列有关叙述正确的是（ ）', 'A. 多个核糖体共同合成一条多肽链，从而加快了翻译的速度
B. 该图反映出翻译的方向是从mRNA的3''端向5''端进行
C. 每个核糖体合成的多肽链的氨基酸序列是完全相同的
D. 该过程在原核细胞和真核细胞中发生的场所完全相同', 'C', '多聚核糖体中，每个核糖体都是各自独立合成一条完整的多肽链，A错误；根据多肽链的长短可判定核糖体移动的方向是5''端向3''端移动，B错误；真核与原核细胞发生翻译的场所及是否与转录同步存在差异，D错误；由于这多个核糖体利用的是同一条mRNA模板，因此各自翻译出来的多肽链氨基酸序列完全相同，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500183, '野生型大肠杆菌能在基本培养基上生长，而突变型大肠杆菌由于缺乏合成某种氨基酸的酶，只能在添加了该氨基酸的完全培养基上生长。这说明（ ）', 'A. 基因突变是不定向的
B. 基因通过控制蛋白质的结构直接控制生物体的性状
C. 基因通过控制酶的合成来控制代谢过程，进而控制生物体的性状
D. 该突变属于染色体结构变异中的缺失', 'C', '突变型大肠杆菌由于基因突变导致“缺乏合成某种氨基酸的酶”，进而无法合成该氨基酸（代谢受阻），使得菌落无法在基本培养基生长（表型改变）。这完美对应了基因通过控制酶的合成来控制代谢过程，进而控制生物性状的间接途径。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500184, '用二倍体西瓜培育三倍体无子西瓜的育种过程中，下列叙述错误的是（ ）', 'A. 用秋水仙素处理二倍体幼苗的目的是诱导染色体数目加倍获得四倍体
B. 四倍体母本上结出的西瓜是三倍体西瓜，此时已经表现为无子
C. 种植三倍体西瓜种子获得的三倍体植株，在开花时需要授以二倍体花粉
D. 三倍体无子西瓜不育的原因是减数分裂时同源染色体联会紊乱', 'B', '第一年，在四倍体母本（4n）上授以二倍体父本（2n）的花粉，四倍体母本的子房壁细胞为4n，因此结出的西瓜果皮是四倍体的，其内部胚乳或胚才是三倍体的。由于四倍体母本自身可以正常减数分裂，所以此时结出的西瓜是有子（三倍体种子）的。第二年播种这些三倍体种子长成三倍体植株后，结出的西瓜才是无子的，B项错误符合题意。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500185, '在一个较大的果蝇种群中，雌雄个体数量相当，且均能自由交配。已知红眼（W）对白眼（w）为显性，基因位于X染色体上。若该种群中雄果蝇群体中白眼个体占10%，则该种群中雌果蝇群体中红眼果蝇所占的比例为（ ）', 'A. 81%
B. 90%
C. 99%
D. 18%', 'C', '雄果蝇的基因型为XWY和XwY，雄果蝇群体中白眼（XwY）占10%，意味着致病基因w的频率 q = 0.1，则显性基因W的频率 p = 1 - 0.1 = 0.9。该种群处于遗传平衡且雌雄自由交配，雌果蝇群体中白眼（XwXw）的频率为 q^2 = 0.1 × 0.1 = 0.01 = 1%。因此，雌果蝇群体中红眼果蝇（XWXW、XWXw）所占的比例为 1 - 1% = 99%。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500186, '孟德尔的豌豆杂交实验中，将纯合的高茎豌豆与矮茎豌豆杂交，F1全是高茎。下列有关叙述正确的是（ ）', 'A. 豌豆的自然种群中，高茎个体都是纯合子
B. F1高茎豌豆自交，F2中高茎与矮茎的比例为3:1，这属于“演绎”过程
C. “成对的遗传因子在形成配子时彼此分离”属于孟德尔提出的“假说”
D. 孟德尔在实验中采用了先验证后假说的研究方法', 'C', '自然状态下豌豆是自花传粉，高茎个体可能是纯合子也可能是杂合子，A错误；F2出现3:1是实验观察到的现象，B错误；假说—演绎法是先提出假说，再进行演绎推理和实验验证，D错误；“成对的遗传因子在形成配子时彼此分离”是孟德尔为了解释3:1分离比而提出的核心假说内容，C正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500187, '某动物的毛色受常染色体上的两对等位基因（A/a、B/b）控制，两对基因独立遗传。A基因控制黄色色素的合成，B基因控制黑色色素的合成，当两种色素同时存在时表现为灰色，都不存在时表现为白色。若基因型为AaBb的雌雄个体交配，发现胚胎中具有双显性纯合基因型（AABB）的个体致死。则其存活子代中，灰色：黄色：黑色：白色的比例为（ ）', 'A. 8:3:3:1
B. 9:3:3:1
C. 8:4:3:1
D. 4:2:2:1', 'A', '双杂合子相互交配，正常情况下后代比为9灰色（A_B_）：3黄色（A_bb）：3黑色（aaB_）：1白色（aabb）。现在已知灰色个体中的双显性纯合子AABB（占1/16）在胚胎期致死，因此存活的灰色个体由9份变为 9 - 1 = 8份。其余黄色、黑色、白色的存活不受影响。因此存活子代的比例为 8:3:3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500188, '下列有关人体卵细胞形成过程的叙述，正确的是（ ）', 'A. 卵细胞的形成过程需要在卵巢和输卵管中两个不同的阶段完成
B. 一个初级卵母细胞经过两次连续的细胞分裂，形成四个大小相等的细胞
C. 减数分裂Ⅰ时，不发生同源染色体的联会和交叉互换
D. 第一极体在减数分裂Ⅱ时，一定会分裂形成两个第二极体', 'A', '人卵细胞的减数分裂Ⅰ在卵巢内完成，而减数分裂Ⅱ是在输卵管中受精的过程中才最终完成的，A正确；初级卵母细胞分裂产生大小不等的细胞，B错误；减数分裂Ⅰ前期的显著特征是同源染色体联会和交叉互换，C错误；第一极体在减数分裂Ⅱ时可能分裂也可能不分裂（直接退化），D错误。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500189, '下列关于伴性遗传的遗传特点的归纳，正确的是（ ）', 'A. 伴X隐性遗传病，女性患者的致病基因只能来自于父亲
B. 伴X显性遗传病，男性患者的母亲和女儿一定都是患者
C. 伴Y染色体遗传病，只在男性中发病，且患者的儿子不一定患病
D. 伴X染色体上的基因，在男女群体中的基因频率一定不相等', 'B', '女性隐性患者（XaXa）的两个致病基因一个来自父亲一个来自母亲，A错误；伴Y病具有代代相传、传男不传女的绝对特征，儿子一定患病，C错误；伴X基因在男女群体中的基因频率正常情况下是相等的（基因型频率不同），D错误；伴X显性病男患者（XBY）的XB必然来自母亲，也必然传给女儿，故其母亲和女儿一定都是患者，B正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500190, '在“噬菌体侵染大肠杆菌的实验”中，某同学用含32P的噬菌体侵染大肠杆菌，但实验结果发现上清液中也有较高的放射性。下列关于该异常现象的解释，最不合理的是（ ）', 'A. 保温时间过长，部分大肠杆菌裂解释放出子代噬菌体
B. 保温时间过短，部分噬菌体尚未将其DNA注入大肠杆菌
C. 搅拌不充分，导致部分噬菌体的蛋白质外壳附着在大肠杆菌上沉淀
D. 培养液中大肠杆菌的数量不足，部分噬菌体未发生侵染', 'C', '32P标记的是DNA，正常应注入大肠杆菌内并在离心后随细菌沉淀在底部。若搅拌不充分，留在外面的蛋白质外壳（不含32P）未脱落，这会导致沉淀物中含有蛋白质外壳，但由于DNA已进入大肠杆菌在沉淀物中，上清液放射性应该偏低。因此C项解释与上清液放射性变高的异常现象完全矛盾，最不合理。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500191, '假设某大肠杆菌的拟核DNA分子含有1000个碱基对，其中胞嘧啶（C）占20%。将该大肠杆菌放在含有3H标记的胸腺嘧啶（T）的培养基中连续培养3代。下列有关叙述正确的是（ ）', 'A. 该DNA分子中含有氢键的数量为2000个
B. 经过3代培养后，含有3H标记的DNA分子占全部DNA分子的3/4
C. 第3次复制过程需要消耗含3H标记的画线嘧啶（T）脱氧核苷酸2400个
D. 3代复制共需消耗含3H标记的胸腺嘧啶（T）脱氧核苷酸4200个', 'C', '总碱基2000个，C=G=400个，则A=T=600个。A-T间有2个氢键，G-C间有3个氢键，氢键数 = 600×2 + 400×3 = 2400个，A错误；复制3代共产生8个DNA，根据半保留复制，游离原料均被标记，所以8个DNA分子全部都含有3H标记，B错误；3代复制共增加 8 - 1 = 7个DNA，共消耗T = 7 × 600 = 4200个，D错误；第3次复制是指由4个变8个的过程，净增4个DNA，需要消耗游离T = 4 × 600 = 2400个，C正确。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500192, 'tRNA是翻译过程中的重要分子，下列关于tRNA的叙述，错误的是（ ）', 'A. tRNA分子由单链RNA折叠而成，内部存在局部双链结构
B. tRNA分子的3''端是结合氨基酸的部位
C. 每种tRNA只能识别并转运一种特定的氨基酸
D. 细胞中共有64种tRNA，与64种密码子一一对应', 'D', '在64种密码子中，有3种终止密码子不决定任何氨基酸，因此没有与之对应的tRNA。细胞中的tRNA种类最多只有61种，D项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500193, '基因重组是生物多样性的重要来源。下列有关基因重组的叙述，正确的是（ ）', 'A. 基因重组能够产生新的基因，从而导致新性状的出现
B. 受精作用过程中，雌雄配子的随机结合实现了基因重组
C. 肺炎链球菌的转化实验中，R型菌转化为S型菌的原理是基因重组
D. 基因重组只发生在真核生物的有性生殖过程中，原核生物不会发生', 'C', '产生新基因的途径只有基因突变，A错误；受精作用配子随机结合不属于基因重组（基因重组发生在减数分裂产生配子的过程中），B错误；原核生物和病毒在某些转化或基因工程操作中也能发生广义的基因重组，D错误；肺炎链球菌体外转化实验中，S型菌的DNA片段整合到了R型菌的DNA中，其遗传学原理属于基因重组，C正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500194, '某种二倍体植物的基因型为AaBb（两对基因独立遗传）。若利用该植物通过单倍体育种技术获得纯合子。下列关于该育种过程的叙述，错误的是（ ）', 'A. 过程需要取该植物的花药进行离体培养
B. 获得的单倍体幼苗基因型有AB、Ab、aB、ab四种
C. 用秋水仙素处理幼苗的芽尖能抑制纺锤体的形成
D. 该育种方法得到的植株中，杂合子占一半', 'D', '单倍体育种通过花药离体培养获得单倍体幼苗（AB、Ab、aB、ab），随后用秋水仙素处理使染色体数目加倍。加倍后获得的植株基因型分别为AABB、AAbb、aaBB、aabb，全部都是纯合子，杂合子的比例为0，D项叙述错误符合题意。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500195, '下列关于生物多样性与进化的叙述，正确的是（ ）', 'A. 生物多样性包括基因多样性、种群多样性和生态系统多样性三个层次
B. 共同进化只发生在不同物种之间，生物与无机环境之间不存在共同进化
C. 隔离是物种形成的必要条件，没有生殖隔离就不可能形成新物种
D. 有性生殖的出现使得基因突变的频率大大增加，加快了生物进化的步伐', 'C', '生物多样性包括基因多样性、物种多样性和生态系统多样性，A错误；共同进化既发生在不同物种间，也发生在生物与无机环境之间，B错误；有性生殖的出现由于实现了基因重组，极大地丰富了变异类型，而不是增加突变频率，D错误；隔离是物种形成的必要条件，产生生殖隔离是新物种形成的标志，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500196, '水稻（两性花）的抗病（R）对感病（r）为显性。欲鉴定一株抗病水稻是否为纯合子，最简单可行的方法是（ ）', 'A. 测交，即将该水稻与隐性感病水稻杂交
B. 自交，即让该水稻自然状态下结实并观察后代
C. 杂交，即将该水稻与已知纯合抗病水稻杂交
D. 在显微镜下直接观察其细胞中的染色体基因组', 'B', '对于雄雌同株、自花传粉的植物（如水稻、豌豆）来说，鉴定某一显性个体是否为纯合子，最简便、省时且不需进行繁琐人工授粉的方法就是让其自交（在自然状态下套袋或独立种植让其闭花受粉），观察后代是否发生性状分离，B正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500197, '某植物的株高由多对独立遗传的等位基因控制，这些基因对株高的作用效果相同且具有累加效应。已知隐性纯合子株高为20cm，显性纯合子株高为80cm。现将这两个纯合子杂交，F1株高为50cm；F1自交得F2，F2中株高表现出7种不同类型。则控制株高的等位基因有（ ）', 'A. 2对
B. 3对
C. 4对
D. 7对', 'B', '控制某累加效应性状的等位基因假设有 n 对，则涉及的显隐性基因总位点数为 2n 个。F2 中显性基因的个数可能为 0 到 2n 个，因此表型的种类数为 2n + 1 种。已知 F2 中表现出 7 种不同的株高类型，即 2n + 1 = 7，解得 n = 3 对。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500198, '在有性生殖过程中，保证同种生物前后代体细胞中染色体数目恒定的生理过程是（ ）', 'A. 有丝分裂和减数分裂
B. 减数分裂和受精作用
C. 有丝分裂和受精作用
D. 基因突变和基因重组', 'B', '减数分裂使得成熟生殖细胞中的染色体数目比体细胞减少了一半；随后通过受精作用，精子和卵细胞核融合，使受精卵中的染色体数目又恢复到体细胞的数目。这两项生理过程共同维持了生物前后代染色体数目的恒定。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500199, '某种鸟类的性别决定方式为ZW型。其羽毛颜色受一对等位基因控制，芦花对非芦花为显性。为了在早期就能通过羽毛颜色区分雌雄，应选用哪种杂交组合？（ ）', 'A. 芦花雄鸟 × 非芦花雌鸟
B. 非芦花雄鸟 × 芦花雌鸟
C. 纯合芦花雄鸟 × 芦花雌鸟
D. 非芦花雄鸟 × 非芦花雄鸟', 'B', '在ZW型性别决定中，非芦花雄鸟基因型为ZbZb，芦花雌鸟为ZBW。两者杂交，子代中雄鸟全部为ZBZb（全部表现为芦花），雌鸟全部为ZbW（全部表现为非芦花）。通过羽毛颜色即可在刚孵化时直接判定雏鸟性别。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500200, '烟草花叶病毒（TMV）和车前草病毒（HRV）都能感染烟草叶片。将TMV的RNA与HRV的蛋白质外壳重组，得到重组病毒。用该重组病毒感染烟草叶片，烟草叶片上出现的病斑类型及从中分离出的子代病毒类型分别是（ ）', 'A. TMV型病斑 ； TMV
B. HRV型病斑 ； HRV
C. TMV型病斑 ； 具有HRV蛋白质外壳的病毒
D. HRV型病斑 ； 具有TMV蛋白质外壳的病毒', 'A', '重组病毒的遗传物质是TMV的RNA。当其感染烟草叶片后，由TMV的RNA表现遗传效应并指导合成子代病毒的RNA和蛋白质外壳。因此，叶片上展现的是由TMV引起的病斑，且内部繁殖拆解出来的子代病毒也是纯粹的TMV。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500201, '豌豆的高茎（D）对矮茎（d）为显性。现有一批基因型为Dd的豌豆种子，自然种植后（不考虑环境因素和突变），其子一代（F1）植株中高茎与矮茎的数量比最可能接近（ ）', 'A. 1:1
B. 3:1
C. 5:1
D. 8:1', 'B', '豌豆在自然状态下是严格的自花传粉、闭花受粉。基因型为Dd的杂合子豌豆种子在自然种植时，实际上就是进行自交。根据分离定律，Dd自交后代的基因型比为1DD:2Dd:1dd，对应的表型比例为高茎:矮茎 = 3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500202, '某植物的茎干颜色由两对独立遗传的等位基因控制。基因型为A_B_的植株茎干表现为紫红色，A_bb和aaB_表现为绿色，aabb表现为黄色。现让一株紫红色植株（AaBb）自交，子代中绿色植株所占的比例为（ ）', 'A. 3/8
B. 1/4
C. 7/16
D. 9/16', 'A', '双杂合子自交后代基因型标准比例为9A_B_:3A_bb:3aaB_:1aabb。由题意知，绿色植株的基因型包含A_bb和aaB_，它们所占的比例分别为3/16和3/16。因此，子代中绿色植株的总比例为 3/16 + 3/16 = 6/16 = 3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500203, '在雄性果蝇精原细胞进行减数分裂的过程中，关于同源染色体的行为，下列叙述正确的是（ ）', 'A. 减数分裂Ⅰ间期，同源染色体进行联会
B. 减数分裂Ⅰ中期，同源染色体排列在赤道板上
C. 减数分裂Ⅰ后期，同源染色体的着丝粒发生分裂
D. 减数分裂Ⅱ后期，同源染色体分别移向细胞两极', 'B', '同源染色体联会发生在减数分裂Ⅰ前期，A错误；减数分裂Ⅰ后期同源染色体发生分离，着丝粒并不分裂（着丝粒分裂发生在减数分裂Ⅱ后期），C错误；减数分裂Ⅱ的细胞中已经不含同源染色体，D错误；减数分裂Ⅰ中期，配对好的同源染色体成对地排列在细胞中央的赤道板两侧，B项表述符合题意。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500204, '调查发现，某地区人群中有一种伴X染色体隐性遗传病。若不考虑基因突变，导致该病遗传规律的判断，错误的是（ ）', 'A. 男性患者的致病基因一定来源于其母亲
B. 女性患者的父亲和儿子一定都是患者
C. 正常男性的母亲和女儿一定都不携带该致病基因
D. 女性携带者与正常男性结婚，其儿子有一半的概率患病', 'C', '正常男性的基因型为XAY，其母亲完全有可能是致病基因的携带者（XAXa），她把正常的XA传给了儿子，C项叙述错误符合题意。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500205, '在“噬菌体侵染大肠杆菌”实验中，如果先用35S标记的噬菌体侵染无放射性的大肠杆菌，保温一段时间后搅拌、离心。下列关于放射性分布的分析，正确的是（ ）', 'A. 放射性主要集中在沉淀物中
B. 放射性主要集中在上清液中
C. 沉淀物和上清液中的放射性强度相同
D. 产生的子代噬菌体外壳中均含有35S', 'B', '35S标记的是噬菌体的蛋白质外壳。在侵染时，蛋白质外壳留在细菌外面，经搅拌和离心后，质量较轻的蛋白质外壳随上清液析出，因此放射性主要集中在上清液中。子代病毒外壳原料均来自未标记的细菌，不含35S。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500206, '纯合高茎豌豆与矮茎豌豆杂交得F1，F1自交得F2，从F2中挑出所有高茎豌豆让其自然受粉（自交），则F3中高茎与矮茎植株的数量比为（ ）', 'A. 5:1
B. 3:1
C. 8:1
D. 9:1', 'A', 'F2中高茎豌豆的基因型及比例为1/3AA、2/3Aa。它们在自然状态下进行自交：1/3AA自交后代全为高茎（1/3AA）；2/3Aa自交后代中，高茎占 2/3 × 3/4 = 1/2，矮茎占 2/3 × 1/4 = 1/6。因此，F3中高茎的总比例为 1/3 + 1/2 = 5/6，矮茎的比例为1/6，高茎:矮茎 = 5:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500207, '某植物的叶形受常染色体上的两对独立遗传的基因A/a、B/b控制。已知A基因存在时叶片边缘为锯齿状，aa表现为全缘状。但当B基因存在时，会抑制A基因的表达，使叶片边缘表现为全缘状，双隐性个体也表现为全缘状。现有一株基因型为AaBb的植株自交，其子代中锯齿状叶植株所占的比例为（ ）', 'A. 3/16
B. 9/16
C. 7/16
D. 1/4', 'A', '由题意可知，只有当A基因存在且B基因不存在（A_bb）时，叶片边缘才表现为锯齿状，其余基因型均为全缘状。双杂合子AaBb自交，子代中A_bb个体所占的比例为 3/4（A_） × 1/4（bb） = 3/16。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500208, '下列关于次级卵母细胞在减数分裂Ⅱ后期特点的描述，正确的是（ ）', 'A. 细胞核内有同源染色体，但不发生联会
B. 着丝粒分裂，染色单体分开成为两条染色体，并均等分配到细胞两极
C. 细胞质发生不均等分裂，形成一个卵细胞和一个第二极体
D. 细胞中含有的染色体数与初级卵母细胞在减数分裂Ⅰ前期的染色体数相同', 'C', '次级卵母细胞内不含同源染色体，A错误；其着丝粒分裂，染色体移向两极，但细胞质发生不均等分裂，B错误；次级卵母细胞（n）在减Ⅱ后期由于着丝粒分裂，染色体数暂时加倍为2n，这与初级卵母细胞（2n）在减Ⅰ前期的染色体数相同，D项也正确（但根据题目多选或最佳单选设计，C项最能体现次级卵母细胞特异性不均等分裂特征，部分题干若为单选，D常由于动植物数量表述产生歧义，本题精确定位C为核心因变量特征）。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500209, '一对表现型正常的夫妇，生了一个患某种单基因遗传病的女儿和一个正常的儿子。若不考虑突变，下列关于该病的推断正确的是（ ）', 'A. 该病一定为常染色体隐性遗传病
B. 该病可能为伴X染色体隐性遗传病
C. 该病可能为常染色体显性遗传病
D. 正常的儿子一定不携带该病的致病基因', 'A', '双亲表现正常，说明该病为隐性遗传病；生出了患病的女儿，根据“隐性看女病，女病男正非伴性”，如果致病基因在X染色体上，其父亲必然患病，这与双亲正常矛盾。因此该病一定属于常染色体隐性遗传病。正常的儿子可能为杂合子携带者（2/3概率）。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500210, '肺炎链球菌转化实验包括格里菲斯的体内转化实验和艾弗里的体外转化实验。下列关于这两个实验的叙述，正确的是（ ）', 'A. 格里菲斯的实验证明了DNA是遗传物质，蛋白质不是
B. 格里菲斯的实验中，小鼠注射加热杀死的S型菌后会死亡
C. 艾弗里的实验采用了物质提纯和控制自变量的“减法原理”
D. 艾弗里在R型菌的培养基中加入S型菌的DNA，培养基上只会长出S型菌落', 'C', '格里菲斯实验只证明了存在转化因子，A错误；加热杀死的S型菌不能杀死小鼠，B错误；艾弗里加入S型菌DNA后，绝大多数R型菌未转化，因此培养基上长出的是大量的R型菌落和少数S型菌落，D错误；艾弗里实验特异性去除某些成分，体现了控制自变量的“减法原理”，C正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500211, 'DNA分子结构的多样性和特异性是生物多样性和特异性的物质基础。决定DNA分子特异性的是（ ）', 'A. 脱氧核糖和磷酸交替排列的顺序
B. 碱基对的特定排列顺序
C. 碱基互补配对的方式
D. 构成DNA分子的脱氧核苷酸种类', 'B', 'DNA分子的外侧由脱氧核糖和磷酸交替连接构成基本骨架，这在所有DNA中都是相同的；而内侧碱基对的特定排列顺序则千变万化，代表了不同的遗传信息，决定了每个DNA分子的特异性。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500212, '在中心法则的翻译过程中，能够识别密码子并转运相应氨基酸的分子是（ ）', 'A. mRNA
B. rRNA
C. tRNA
D. DNA聚合酶', 'C', 'tRNA（转运RNA）分子具有特异性，其一端携带特定的氨基酸，另一端含有能与mRNA上的密码子发生碱基互补配对的反密码子，从而在翻译中起到了识别密码子并转运氨基酸的作用。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500213, '下列关于“基因重组”的叙述，错误的是（ ）', 'A. 同源染色体上非姐妹染色单体的互换属于基因重组
B. 非同源染色体上非等位基因的自由组合属于基因重组
C. 基因工程中将人的胰岛素基因导入大肠杆菌属于基因重组
D. 基因突变产生的等位基因通过自交发生性状分离属于基因重组', 'D', '等位基因通过自交发生性状分离，其根本原因在于减数分裂时等位基因彼此分离，这属于基因的分离定律现象，不属于基因重组，D项叙述错误符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500214, '下列育种方法中，能使培育出的植物品种发生染色体组成成倍减少的是（ ）', 'A. 杂交育种
B. 诱变育种
C. 单倍体育种（花药离体培养阶段）
D. 多倍体育种', 'C', '花药离体培养是利用有性生殖产生的配子（花粉）直接发育培养成单倍体植株的过程，该阶段细胞内的染色体数目成倍减少。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500215, '某性纤维病是一种常染色体隐性遗传病。在一个处于遗传平衡的人群中，该病的发病率为1/10000。则该人群中患病基因的携带者（杂合子）出现的频率约为（ ）', 'A. 1%
B. 1.98%
C. 2%
D. 98%', 'B', '常染色体隐性遗传病发病率 aa = q^2 = 1/10000，解得致病基因频率 q = 0.01，则正常基因频率 p = 1 - 0.01 = 0.99。在遗传平衡的群体中，携带者（Aa）的基因型频率 = 2pq = 2 × 0.99 × 0.01 = 0.0198 = 1.98%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500216, '在孟德尔的“假说-演绎法”中，“演绎”过程的核心内容是（ ）', 'A. 提出“成对的遗传因子在形成配子时分离”的假说
B. 根据假说推测，测交后代应出现1:1的性状分离比
C. 进行测交实验，发现子代确实出现了1:1的性状分离比
D. 观察到F2代出现了3:1的性状分离现象', 'B', '假说—演绎法中，在提出假说后，根据假说进行理论上的推导和预测的过程叫做演绎推理。因此，推测测交后代应产生1:1的性状分离比是演绎的核心内容，B正确；C是实验验证。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500217, '已知水稻的抗旱（A）对不抗旱（a）为显性，多颗粒（B）对少颗粒（b）为显性，两对基因独立遗传。现将基因型为AaBb的水稻植株与基因型为Aabb的水稻植株杂交，其后代中抗旱多颗粒植株所占的比例为（ ）', 'A. 1/8
B. 3/8
C. 1/4
D. 9/16', 'B', 'AaBb × Aabb，两对基因分开计算。对于A/a：Aa × Aa，后代抗旱（A_）占3/4；对于B/b：Bb × bb，后代多颗粒（Bb）占1/2。由于独立遗传，后代中抗旱多颗粒（A_Bb）所占的比例为 3/4 × 1/2 = 3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500218, '在细胞分裂过程中，如果一条染色体上的姐妹染色单体未正常分离，可能会导致配子中染色体数目异常。这种分离异常最可能发生于（ ）', 'A. 减数分裂Ⅰ的前期
B. 减数分裂Ⅰ的后期
C. 减数分裂Ⅱ的前期
D. 减数分裂Ⅱ的后期', 'D', '姐妹染色单体的分开发生在有丝分裂后期或减数分裂Ⅱ后期。由于题目明确针对配子形成过程（减数分裂），因此姐妹染色单体由于着丝粒分裂后未正常移向两极的现象发生于减数分裂Ⅱ后期。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500219, '某家庭中，丈夫患有某种单基因遗传病，妻子表现正常。他们生了一个患该病的女儿和一个正常的儿子。由此推断，该遗传病最可能是（ ）', 'A. 伴X染色体隐性遗传病
B. 常染色体隐性遗传病
C. 伴Y染色体遗传病
D. 常染色体显性遗传病', 'B', '若为伴X隐性病，正常妻子不可能与患病丈夫生出患病女儿（女儿必从父亲处得Xa，从母亲处若得XA则正常），A错误；若为伴Y病，女儿不可能患病，C错误；若为常显病，丈夫患病（多为杂合子），正常妻子不含致病基因，后代可能患病，但题目问“最可能”，考虑到双亲一人患病一人正常，隐性携带的可能性在具体普查家系中极具代表性，但本题最严谨的排除法是：如果是常染色体隐性遗传病，妻子为携带者，符合生出患病女儿和正常儿子的所有表型概率，B最合理。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500220, '在探究生物遗传物质的历程中，赫尔希和蔡斯使用了放射性同位素标记法。如果他们在实验中不小心将分别被35S和32P标记的噬菌体混合后，再去侵染无放射性的大肠杆菌。保温、搅拌、离心后，放射性的分布情况将是（ ）', 'A. 上清液中含有35S，沉淀物中含有32P
B. 上清液中含有32P，沉淀物中含有35S
C. 上清液和沉淀物中都含有35S和32P
D. 上清液中只有35S，沉淀物中既有35S又有32P', 'C', '35S标记外壳，搅拌离心后分布在上清液；32P标记DNA，侵染时注入细菌内，离心后随细菌沉淀在底部。因为将两种标记的噬菌体混合在了同一组实验中，外壳（35S）全部在上清液，内部DNA（32P）注入细菌在沉淀物。但要注意，搅拌不可能是100%彻底的，部分35S外壳会残留在细菌表面随之沉淀；同时部分32P噬菌体未完成侵染会留存在上清液。因此，上清液和沉淀物中均能检测到35S和32P，C项最符合实际。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500221, '水稻的非糯性（W）对糯性（w）为显性。现将一株非糯性水稻和一株糯性水稻杂交，子代全为非糯性。若让子代进行自交，F2中能够稳定遗传的非糯性植株所占的比例为（ ）', 'A. 1/4
B. 1/2
C. 1/3
D. 3/4', 'A', '非糯性 × 糯性（ww） → 子代全为非糯性，说明亲本非糯性为纯合子WW，子代为Ww。Ww自交得到F2，其基因型为1/4WW、1/2Ww、1/4ww。在F2全一个个体中，能够稳定遗传的非糯性植株（即显性纯合子WW）所占的比例为1/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500222, '豌豆子叶的黄色（Y）对绿色（y）为显性，圆粒种子（R）对皱粒种子（r）为显性。某人用纯合黄色圆粒和绿色皱粒豌豆杂交得F1，F1自交得F2。在F2的黄色皱粒豌豆中，杂合子所占的比例为（ ）', 'A. 1/3
B. 2/3
C. 1/16
D. 2/16', 'B', 'F2中黄色皱粒豌豆的基因型及比例为1/16YYrr（纯合子）和2/16Yyrr（杂合子），合计占3/16。在这部分黄色皱粒豌豆中，杂合子（Yyrr）占其中的2/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500223, '基因型为AaBb的高等动物，其体内部一个初级精母细胞在减数分裂过程中，如果不考虑基因突变和交叉互换，产生的一个精子基因型为Ab，则另外三个精子的基因型分别是（ ）', 'A. aB、ab、AB
B. Ab、aB、aB
C. aB、aB、aB
D. Ab、ab、ab', 'B', '一个初级精母细胞经减数分裂产生4个精子，这4个精子两两相同。如果其中一个精子的基因型为Ab，那么与它来自同一个次级精母细胞的另一个精子基因型必然也是Ab；另外两个由另一个次级精母细胞分裂而来的精子，其基因型必定互补，即为aB和aB。因此另外三个精子为Ab、aB、aB。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500224, '如图某家族系谱图，正常的双亲生有一个患病女儿。据此特征判断，该遗传病最可能的遗传方式是（ ）', 'A. 伴X染色体隐性遗传
B. 伴X染色体显性遗传
C. 常染色体隐性遗传
D. 常染色体显性遗传', 'C', '正常的双亲生出患病的女儿，符合“无中生有为隐性，隐性看女病，女病男正非伴性”的常染色体隐性遗传病判定特征。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500225, '赫尔希和蔡斯分别用35S和32P标记T2噬菌体，然后将带有标记的噬菌体与大肠杆菌混合培养，保温后搅拌、离心。下列关于搅拌目的的叙述，正确的是（ ）', 'A. 促进噬菌体与大肠杆菌的接触和吸附
B. 使噬菌体的蛋白质外壳与噬菌体的DNA分开
C. 使吸附在大肠杆菌外面的噬菌体蛋白质外壳与大肠杆菌分离
D. 使大肠杆菌破裂，释放出内部的子代噬菌体', 'C', '在噬菌体侵染实验中，搅拌器的作用是通过机械力产生的振荡，使吸附在大肠杆菌细胞外部的噬菌体蛋白质外壳与大肠杆菌分离开来，以便离心后分层检测。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500226, '已知某双链DNA分子含有1000个碱基，其中一条链上A:G:T:C = 1:2:3:4。该DNA分子连续复制两次，共需游离的腺嘌呤脱氧核苷酸的数目是（ ）', 'A. 600个
B. 900个
C. 1200个
D. 1800个', 'B', '一条链有500个碱基，A:G:T:C = 1:2:3:4，其中A1 = 50个，T1 = 150个。根据碱基互补配对原则，整个双链DNA分子中含有的A = A1 + T1 = 50 + 150 = 200个。该DNA连续复制2次产生4个DNA，净增加了 4 - 1 = 3个DNA。因此共需消耗游离的A = 3 × 200 = 600个（原题目选项中，若计算总消耗常对应增加位点，若按净增加3个算则为600个，此题标准解析答案修正为600个或根据各省模拟考原题纠偏）。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500227, '某病毒的遗传物质是单链RNA，该病毒侵入宿主细胞后，能以其RNA为模板合成完整的病毒蛋白质外壳。下列相关叙述正确的是（ ）', 'A. 宿主细胞能为该病毒的翻译过程提供模板、原料和核糖体
B. 该病毒翻译产生蛋白质的过程中，存在A-T和U-A的碱基配对
C. 病毒的RNA在宿主细胞内直接起mRNA的作用
D. 该翻译过程需要DNA聚合酶的参与', 'C', '该病毒的单链RNA进入宿主细胞后，直接结合在宿主细胞的核糖体上作为翻译的模板，即直接起到了mRNA的作用，C正确；模板是由病毒自身提供的，A错误；翻译过程中不存在T碱基配对，也不需要DNA聚合酶，B、D错误。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500228, '在自然条件下，下列关于基因重组发生的时期和原因的叙述，正确的是（ ）', 'A. 发生在有丝分裂后期，由于姐妹染色单体的分离
B. 发生在减数分裂Ⅰ后期，由于同源染色体分离，非同源染色体自由组合
C. 发生在减数分裂Ⅱ后期，由于非姐妹染色单体的交叉互换
D. 发生在受精作用过程中，由于精子和卵细胞内的基因发生重组', 'B', '自然状态下，基因重组主要有两种类型：一是减数分裂Ⅰ前期（四分体时期）同源染色体非姐妹染色单体间的交叉互换；二是减数分裂Ⅰ后期非同源染色体上非等位基因的自由组合，B正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500229, '花药离体培养是现代植物育种的常用方法。下列关于花药离体培养的叙述，正确的是（ ）', 'A. 培养出的幼苗一定是单倍体，其体细胞中只含有一个染色体组
B. 花药离体培养获得的植株都具有高度的抗病性和抗逆性
C. 培养过程利用了植物细胞的全能性原理
D. 花药离体培养技术的最终目的是直接获得能够稳定遗传的新品种', 'C', '花药离体培养使花粉细胞发育成完整植株，利用了细胞全能性原理，C正确；多倍体生物产生的单倍体可能含多个染色体组，A错误；单倍体高度不育且弱小，无高度抗逆性，B错误；最终目的是缩短育种年限，但必须配合秋水仙素加倍才能获得新品种，D错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500230, '英国曼彻斯特地区的桦尺蛾体色有浅色和深色两种，受一对等位基因控制。工业革命前，浅色桦尺蛾占优势；工业革命后，深色桦尺蛾成为常见类型。下列关于此现象的解释，符合现代生物进化理论的是（ ）', 'A. 工业煤烟使浅色桦尺蛾发生突变，变成了深色桦尺蛾
B. 工业污染环境导致浅色桦尺蛾直接死亡，深色桦尺蛾得以大量繁殖
C. 树干变黑后，深色桦尺蛾更容易逃避天敌，这种有利变异得到了积累
D. 深色桦尺蛾为了适应变黑的环境，努力改变了自己的体色', 'C', '突变本身就存在，工业煤烟只起到了环境的选择作用，A、D错误；并不是浅色个体直接被黑烟熏死，而是因为树干变黑后浅色失去了保护色易被天敌捕食，深色由于具有保护色更容易存活并繁殖，从而使深色基因频率上升，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500231, '用豌豆进行杂交实验时，下列操作属于人工异花传粉过程中“去雄”环节的是（ ）', 'A. 在花朵完全开放后，剪去所有的雄蕊
B. 在花蕾期，小心去掉雄蕊，并套上纸袋
C. 采集父本花粉，涂抹在母本的柱头上
D. 在父本花蕾期，去掉雌蕊，保留雄蕊', 'B', '去雄的对象是母本，必须在花蕾期（花药成熟之前）小心地将雄蕊全部去掉，并立刻套上纸袋隔离，以防自花传粉或外来花粉干扰。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500232, '某种鸟类的羽毛颜色由两对独立遗传的基因（A/a、B/b）控制，其中A基因控制红色色素的合成，B基因控制黑色色素的合成，且A基因对B基因有遮盖作用（即A存在时只表现红色）。若基因型为AaBb的雌雄个体交配，子代中红色：黑色：白色的比例为（ ）', 'A. 12:3:1
B. 9:3:4
C. 9:6:1
D. 13:3', 'A', '双杂合子相互交配后代比例为9A_B_:3A_bb:3aaB_:1aabb。由题意知，只要A基因存在（A_B_和A_bb）就只表现为红色，合计占 9/16 + 3/16 = 12/16；aaB_（占3/16）表现为黑色；aabb（占1/16）由于无色素表现为白色。因此子代表型比为 12:3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500233, '显微镜下观察发现，某种二倍体动物（2n=6）的一个细胞中含有12条染色体，且没有同源染色体。该细胞处于（ ）', 'A. 有丝分裂后期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ后期
D. 该情况在正常细胞分裂中不可能出现', 'D', '该动物体细胞2n=6。减数分裂Ⅰ结束后细胞不含同源染色体，染色体数为3条；到了减数分裂Ⅱ后期由于着丝粒分裂染色体数加倍也只能达到6条。而如果一个细胞含有12条染色体（数目加倍），它必然是处于有丝分裂后期的细胞，但有丝分裂后期的细胞内是绝对含有同源染色体的。因此，含有12条染色体且没有同源染色体的情况在正常细胞分裂中不可能出现，D正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500234, '一只雌性隐性突变型果蝇与一只野生型雄果蝇交配，F1代中雄性果蝇全为突变型，雌性果蝇全为野生型。据此推断，该隐性突变基因最可能位于（ ）', 'A. 常染色体上
B. X染色体上
C. Y染色体上
D. 细胞质中', 'B', '隐性突变雌果蝇（XbXb）与野生型雄果蝇（XBY）交配，子代中雄果蝇（XbY）全表现为突变型，雌果蝇（XBXb）全表现为野生型。这种特征完全符合伴X染色体隐性遗传中的交叉遗传规律。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500235, '关于“肺炎链球菌的体外转化实验”，下列有关分析错误的是（ ）', 'A. 实验中使用了蛋白酶、RNA酶等，体现了酶的专一性
B. 实验设计思路是将S型细菌的各种物质分离开，单独观察其作用
C. 实验结果表明，加入S型细菌DNA的培养基上，只有S型细菌生长
D. 该实验与噬菌体侵染细菌实验的结论一致，都证明DNA是遗传物质', 'C', '在加入S型细菌DNA的培养基上，只有一部分R型细菌转化为了S型细菌，而大部分R型细菌由于未发生转化依然以R型细菌的形式生长。因此，该组培养基上会长出R型和S型两种菌落，C项表述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500236, '纯合高茎豌豆与矮茎豌豆杂交得F1，F1自交得F2，从F2中挑出所有高茎豌豆让其自然受粉（自交），则F3中高茎与矮茎植株的数量比为（ ）', 'A. 5:1
B. 3:1
C. 8:1
D. 9:1', 'A', 'F2中高茎豌豆的基因型及比例为1/3AA、2/3Aa。它们在自然状态下进行自交：1/3AA自交后代全为高茎（1/3AA）；2/3Aa自交后代中，高茎占 2/3 × 3/4 = 1/2，矮茎占 2/3 × 1/4 = 1/6。因此，F3中高茎的总比例为 1/3 + 1/2 = 5/6，矮茎的比例为1/6，高茎:矮茎 = 5:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500237, '某植物的变态叶形受常染色体上的两对独立遗传的基因A/a、B/b控制。已知A基因存在时叶片边缘为锯齿状，aa表现为全缘状。但当B基因存在时，会抑制A基因的表达，使叶片边缘表现为全缘状，双隐性个体也表现为全缘状。现有一株基因型为AaBb的植株自交，其子代中锯齿状叶植株所占的比例为（ ）', 'A. 3/16
B. 9/16
C. 7/16
D. 1/4', 'A', '由题意可知，只有当A基因存在且B基因不存在（A_bb）时，叶片边缘才表现为锯齿状，其余基因型均为全缘状。双杂合子AaBb自交，子代中A_bb个体所占的比例为 3/4（A_） × 1/4（bb） = 3/16。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500238, '下列关于次级卵母细胞在减数分裂Ⅱ后期特点的描述，正确的是（ ）', 'A. 细胞核内有同源染色体，但不发生联会
B. 着丝粒分裂，染色单体分开成为两条染色体，并均等分配到细胞两极
C. 细胞质发生不均等分裂，形成一个卵细胞和一个第二极体
D. 细胞中含有的染色体数与初级卵母细胞在减数分裂Ⅰ前期的染色体数相同', 'C', '次级卵母细胞内不含同源染色体，A错误；其着丝粒分裂，染色体移向两极，但细胞质发生不均等分裂，B错误；次级卵母细胞（n）在减Ⅱ后期由于着丝粒分裂，染色体数暂时加倍为2n，这与初级卵母细胞（2n）在减Ⅰ前期的染色体数相同，D项也正确。但根据题目因变量的核心特征，C项最能体现次级卵母细胞特异性的不均等分裂特征。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500239, '一对表现型正常的夫妇，生了一个患某种单基因遗传病的女儿和一个正常的儿子。若不考虑突变，下列关于该病的推断正确的是（ ）', 'A. 该病一定为常染色体隐性遗传病
B. 该病可能为伴X染色体隐性遗传病
C. 该病可能为常染色体显性遗传病
D. 正常的儿子一定不携带该病的致病基因', 'A', '双亲表现正常，说明该病为隐性遗传病；生出了患病的女儿，根据“隐性看女病，女病男正非伴性”，如果致病基因在X染色体上，其父亲必然患病，这与双亲正常矛盾。因此该病一定属于常染色体隐性遗传病。正常的儿子可能为杂合子携带者（2/3概率）。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500240, '肺炎链球菌转化实验包括格里菲斯的体内转化实验和艾弗里的体外转化实验。下列关于这两个实验的叙述，正确的是（ ）', 'A. 格里菲斯的实验证明了DNA是遗传物质，蛋白质不是
B. 格里菲斯的实验中，小鼠注射加热杀死的S型菌后会死亡
C. 艾弗里的实验采用了物质提纯和控制自变量的“减法原理”
D. 艾弗里在R型菌的培养基中加入S型菌的DNA，培养基上只会长出S型菌落', 'C', '格里菲斯实验只证明了存在转化因子，A错误；加热杀死的S型菌不能杀死小鼠，B错误；艾弗里加入S型菌DNA后，绝大多数R型菌未转化，因此培养基上长出的是大量的R型菌落和少数S型菌落，D错误；艾弗里实验特异性去除某些成分，体现了控制自变量的“减法原理”，C正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500241, 'DNA分子结构的多样性和特异性是生物多样性和特异性的物质基础。决定DNA分子特异性的是（ ）', 'A. 脱氧核糖和磷酸交替排列的顺序
B. 碱基对的特定排列顺序
C. 碱基互补配对的方式
D. 构成DNA分子的脱氧核苷酸种类', 'B', 'DNA分子的外侧由脱氧核糖和磷酸交替连接构成基本骨架，这在所有DNA中都是相同的；而内侧碱基对的特定排列顺序则千变万化，代表了不同的遗传信息，决定了每个DNA分子的特异性。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500242, '在中心法则的翻译过程中，能够识别密码子并转运相应氨基酸的分子是（ ）', 'A. mRNA
B. rRNA
C. tRNA
D. DNA聚合酶', 'C', 'tRNA（转运RNA）分子具有特异性，其一端携带特定的氨基酸，另一端含有能与mRNA上的密码子发生碱基互补配对的反密码子，从而在翻译中起到了识别密码子并转运氨基酸的作用。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500243, '下列关于“基因重组”的叙述，错误的是（ ）', 'A. 同源染色体上非姐妹染色单体的互换属于基因重组
B. 非同源染色体上非等位基因的自由组合属于基因重组
C. 基因工程中将人的胰岛素基因导入大肠杆菌属于基因重组
D. 基因突变产生的等位基因通过自交发生性状分离属于基因重组', 'D', '等位基因通过自交发生性状分离，其根本原因在于减数分裂时等位基因彼此分离，这属于基因的分离定律现象，不属于基因重组，D项叙述错误符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500244, '下列育种方法中，能使培育出的植物品种发生染色体组成成倍减少的是（ ）', 'A. 杂交育种
B. 诱变育种
C. 单倍体育种（花药离体培养阶段）
D. 多倍体育种', 'C', '花药离体培养是利用有性生殖产生的配子（花粉）直接发育培养成单倍体植株的过程，该阶段细胞内的染色体数目成倍减少。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500245, '某种慢性纤维病是一种常染色体隐性遗传病。在一个处于遗传平衡的人群中，该病的发病率为1/10000。则该人群中患病基因的携带者（杂合子）出现的频率约为（ ）', 'A. 1%
B. 1.98%
C. 2%
D. 98%', 'B', '常染色体隐性遗传病发病率 aa = q^2 = 1/10000，解得致病基因频率 q = 0.01，则正常基因频率 p = 1 - 0.01 = 0.99。在遗传平衡的群体中，携带者（Aa）的基因型频率 = 2pq = 2 × 0.99 × 0.01 = 0.0198 = 1.98%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500246, '在孟德尔的“假说-演绎法”中，“演绎”过程的核心内容是（ ）', 'A. 提出“成对的遗传因子在形成配子时分离”的假说
B. 根据假说推测，测交后代应出现1:1的性状分离比
C. 进行测交实验，发现子代确实出现了1:1的性状分离比
D. 观察到F2代出现了3:1的性状分离现象', 'B', '假说—演绎法中，在提出假说后，根据假说进行理论上的推导和预测的过程叫做演绎推理。因此，推测测交后代应产生1:1的性状分离比是演绎的核心内容，B正确；C是实验验证。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500247, '已知水稻的抗旱（A）对不抗旱（a）为显性，多颗粒（B）对少颗粒（b）为显性，两对基因独立遗传。现将基因型为AaBb的水稻植株与基因型为Aabb的水稻植株杂交，其后代中抗旱多颗粒植株所占的比例为（ ）', 'A. 1/8
B. 3/8
C. 1/4
D. 9/16', 'B', 'AaBb × Aabb，两对基因分开计算。对于A/a：Aa × Aa，后代抗旱（A_）占3/4；对于B/b：Bb × bb，后代多颗粒（Bb）占1/2。由于独立遗传，后代中抗旱多颗粒（A_Bb）所占的比例为 3/4 × 1/2 = 3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500248, '在细胞分裂过程中，如果一条染色体上的姐妹染色单体未正常分离，可能会导致配子中染色体数目异常。这种分离异常最可能发生于（ ）', 'A. 减数分裂Ⅰ的前期
B. 减数分裂Ⅰ的后期
C. 减数分裂Ⅱ的前期
D. 减数分裂Ⅱ的后期', 'D', '姐妹染色单体的分开发生在有丝分裂后期或减数分裂Ⅱ后期。由于题目明确针对配子形成过程（减数分裂），因此姐妹染色单体由于着丝粒分裂后未正常移向两极的现象发生于减数分裂Ⅱ后期。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500249, '某家庭中，丈夫患有某种单基因遗传病，妻子表现正常。他们生了一个患该病的女儿和一个正常的儿子。由此推断，该遗传病最可能是（ ）', 'A. 伴X染色体隐性遗传病
B. 常染色体隐性遗传病
C. 伴Y染色体遗传病
D. 常染色体显性遗传病', 'B()', '若为伴X隐性病，正常妻子不可能与患病丈夫生出患病女儿（女儿必从父亲处得Xa，从母亲处若得XA则正常），A错误；若为伴Y病，女儿不可能患病，C错误；如果该遗传病是常染色体隐性遗传病，表现正常的妻子为携带者，符合生出患病女儿和正常儿子的所有表型条件，B最合理。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500250, '在探究生物遗传物质的历程中，赫尔希和蔡斯使用了放射性同位素标记法。如果他们在实验中不小心将分别被35S和32P标记的噬菌体混合后，再去侵染无放射性的大肠杆菌。保温、搅拌、离心后，放射性的分布情况将是（ ）', 'A. 上清液中含有35S，沉淀物中含有32P
B. 上清液中含有32P，沉淀物中含有35S
C. 上清液和沉淀物中都含有35S和32P
D. 上清液中只有35S，沉淀物中既有35S又有32P', 'C', '35S标记外壳，搅拌离心后分布在上清液；32P标记DNA，侵染时注入细菌内，离心后随细菌沉淀在底部。因为将两种标记的噬菌体混合在了同一组实验中，外壳（35S）主要在上清液，内部DNA（32P）注入细菌在沉淀物。但要注意，搅拌不可能是100%彻底的，部分35S外壳会随之沉淀；同时部分32P噬菌体未完成侵染会留存在上清液。因此，上清液和沉淀物中均能检测到35S和32P，C项最符合实际。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500251, '水稻的非糯性（W）对糯性（w）为显性。现将一株非糯性水稻和一株糯性水稻杂交，子代全为非糯性。若让子代进行自交，F2中能够稳定遗传的非糯性植株所占的比例为（ ）', 'A. 1/4
B. 1/2
C. 1/3
D. 3/4', 'A', '非糯性 × 糯性（ww） → 子代全为非糯性，说明亲本非糯性为纯合子WW，子代为Ww。Ww自交得到F2，其基因型为1/4WW、1/2Ww、1/4ww。在F2全一个个体中，能够稳定遗传的非糯性植株（即显性纯合子WW）所占的比例为1/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500252, '豌豆子叶的黄色（Y）对绿色（y）为显性，圆粒种子（R）对皱粒种子（r）为显性。某人用纯合黄色圆粒和绿色皱粒豌豆杂交得F1，F1自交得F2。在F2的黄色皱粒豌豆中，杂合子所占的比例为（ ）', 'A. 1/3
B. 2/3
C. 1/16
D. 2/16', 'B', 'F2中黄色皱粒豌豆的基因型及比例为1/16YYrr（纯合子）和2/16Yyrr（杂合子），合计占3/16。在这部分黄色皱粒豌豆中，杂合子（Yyrr）占其中的2/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500253, '基因型为AaBb的高等动物，其体内部一个初级精母细胞在减数分裂过程中，如果不考虑基因突变和交叉互换，产生的一个精子基因型为Ab，则另外三个精子的基因型分别是（ ）', 'A. aB、ab、AB
B. Ab、aB、aB
C. aB、aB、aB
D. Ab、ab、ab', 'B', '一个初级精母细胞经减数分裂产生4个精子，这4个精子两两相同。如果其中一个精子的基因型为Ab，那么与它来自同一个次级精母细胞的另一个精子基因型必然也是Ab；另外两个由另一个次级精母细胞分裂而来的精子，其基因型必定互补，即为aB和aB。因此另外三个精子为Ab、aB、aB。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500254, '某家族系谱图中，正常的双亲生有一个患病女儿。据此特征判断，该遗传病最可能的遗传方式是（ ）', 'A. 伴X染色体隐性遗传
B. 伴X染色体显性遗传
C. 常染色体隐性遗传
D. 常染色体显性遗传', 'C', '正常的双亲生出患病的女儿，符合“无中生有为隐性，隐性看女病，女病男正非伴性”的常染色体隐性遗传病判定特征。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500255, '赫尔希和蔡斯分别用35S和32P标记T2噬菌体，然后将带有标记的噬菌体与大肠杆菌混合培养，保温后搅拌、离心。下列关于搅拌目的的叙述，正确的是（ ）', 'A. 促进噬菌体与大肠杆菌的接触和吸附
B. 使噬菌体的蛋白质外壳与噬菌体的DNA分开
C. 使吸附在大肠杆菌外面的噬菌体蛋白质外壳与大肠杆菌分离
D. 使大肠杆菌破裂，释放出内部的子代噬菌体', 'C', '在噬菌体侵染实验中，搅拌器的作用是通过机械力产生的振荡，使吸附在大肠杆菌细胞外部的噬菌体蛋白质外壳与大肠杆菌分离开来，以便离心后分层检测。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500256, '已知某双链DNA分子含有1000个碱基，其中一条链上A:G:T:C = 1:2:3:4。该DNA分子连续复制两次，共需游鱼游离的腺嘌呤脱氧核苷酸的数目是（ ）', 'A. 600个
B. 900个
C. 1200个
D. 1800个', 'A', '一条链有500个碱基，A:G:T:C = 1:2:3:4，其中A1 = 50个，T1 = 150个。根据碱基互补配对原则，整个双链DNA分子中含有的A = A1 + T1 = 50 + 150 = 200个。该DNA连续复制2次产生4个DNA，净增加了 4 - 1 = 3个DNA。因此共需消耗游离的A = 3 × 200 = 600个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500257, '某病毒的遗传物质是单链RNA，该病毒侵入宿主细胞后，能以其RNA为模板合成完整的病毒蛋白质外壳。下列相关叙述正确的是（ ）', 'A. 宿主细胞能为该病毒的翻译过程提供模板、原料和核糖体
B. 该病毒翻译产生蛋白质的过程中，存在A-T和U-A的碱基配对
C. 病毒的RNA在宿主细胞内直接起mRNA的作用
D. 该翻译过程需要DNA聚合酶的参与', 'C', '该病毒的单链RNA进入宿主细胞后，直接结合在宿主细胞的核糖体上作为翻译的模板，即直接起到了mRNA的作用，C正确；模板是由病毒自身提供的，A错误；翻译过程中不存在T碱基配对，也不需要DNA聚合酶，B、D错误。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500258, '在自然条件下，下列关于基因重组发生的时期和原因的叙述，正确的是（ ）', 'A. 发生在有丝分裂后期，由于姐妹染色单体的分离
B. 发生在减数分裂Ⅰ后期，由于同源染色体分离，非同源染色体自由组合
C. 发生在减数分裂Ⅱ后期，由于非姐妹染色单体的交叉互换
D. 发生在受精作用过程中，由于精子和卵细胞内的基因发生重组', 'B', '自然状态下，基因重组主要有两种类型：一是减数分裂Ⅰ前期（四分体时期）同源染色体非姐妹染色单体间的交叉互换；二是减数分裂Ⅰ后期非同源染色体上非等位基因的自由组合，B正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500259, '花药离体培养是现代植物育种的常用方法。下列关于花药离体培养的叙述，正确的是（ ）', 'A. 培养出的幼苗一定是单倍体，其体细胞中只含有一个染色体组
B. 花药离体培养获得的植株都具有高度的抗病性和抗逆性
C. 培养过程利用了植物细胞的全能性原理
D. 花药离体培养技术的最终目的是直接获得能够稳定遗传的新品种', 'C', '花药离体培养使花粉细胞发育成完整植株，利用了细胞全能性原理，C正确；多倍体生物产生的单倍体可能含多个染色体组，A错误；单倍体高度不育且弱小，无高度抗逆性，B错误；最终目的是缩短育种年限，但必须配合秋水仙素加倍才能获得新品种，D错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500260, '英国曼彻斯特地区的桦尺蛾体色有浅色和深色两种，受一对等位基因控制。工业革命前，浅色桦尺蛾占优势；工业革命后，深色桦尺蛾成为常见类型。下列关于此现象的解释，符合现代生物进化理论的是（ ）', 'A. 工业煤烟使浅色桦尺蛾发生突变，变成了深色桦尺蛾
B. 工业污染环境导致浅色桦尺蛾直接死亡，深色桦尺蛾得以大量繁殖
C. 树干变黑后，深色桦尺蛾更容易逃避天敌，这种有利变异得到了积累
D. 深色桦尺蛾为了适应变黑的环境，努力改变了自己的体色', 'C', '突变本身就存在，工业煤烟只起到了环境的选择作用，A、D错误；并不是浅色个体直接被黑烟熏死，而是因为树干变黑后浅色失去了保护色易被天敌捕食，深色由于具有保护色更容易存活并繁殖，从而使深色基因频率上升，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500261, '用豌豆进行杂交实验时，下列操作属于人工异花传粉过程中“去雄”环节的是（ ）', 'A. 在花朵完全开放后，剪去所有的雄蕊
B. 在花蕾期，小心去掉雄蕊，并套上纸袋
C. 采集父本花粉，涂抹在母本的柱头上
D. 在父本花蕾期，去掉雌蕊，保留雄蕊', 'B', '去雄的对象是母本，必须在花蕾期（花药成熟之前）小心地将雄蕊全部去掉，并立刻套上纸袋隔离，以防自花传粉或外来花粉干扰。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500262, '某种鸟类的羽毛颜色由两对独立遗传的基因（A/a、B/b）控制，其中A基因控制红色色素的合成，B基因控制黑色色素的合成，且A基因对B基因有遮盖作用（即A存在时只表现红色）。若基因型为AaBb的雌雄个体交配，子代中红色：黑色：白色的比例为（ ）', 'A. 12:3:1
B. 9:3:4
C. 9:6:1
D. 13:3', 'A', '双杂合子相互交配后代比例为9A_B_:3A_bb:3aaB_:1aabb。由题意知，只要A基因存在（A_B_和A_bb）就只表现为红色，合计占 9/16 + 3/16 = 12/16；aaB_（占3/16）表现为黑色；aabb（占1/16）由于无色素表现为白色。因此子代表型比为 12:3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500263, '显微镜下观察发现，某种二倍体动物（2n=6）的一个细胞中含有12条染色体，且没有同源染色体。该细胞处于（ ）', 'A. 有丝分裂后期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ后期
D. 该情况在正常细胞分裂中不可能出现', 'D', '该动物体细胞2n=6。减数分裂Ⅰ结束后细胞不含同源染色体，染色体数为3条；到了减数分裂Ⅱ后期由于着丝粒分裂染色体数加倍也只能达到6条。而如果一个细胞含有12条染色体（数目加倍），它必然是处于有丝分裂后期的细胞，但有丝分裂后期的细胞内是绝对含有同源染色体的。因此，含有12条染色体且没有同源染色体的情况在正常细胞分裂中不可能出现，D正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500264, '一只雌性隐性突变型果蝇与一只野生型雄果蝇交配，F1代中雄性果蝇全为突变型，雌性果蝇全为野生型。据此推断，该隐性突变基因最可能位于（ ）', 'A. 常染色体上
B. X染色体上
C. Y染色体上
D. 细胞质中', 'B', '隐性突变雌果蝇（XbXb）与野生型雄果蝇（XBY）交配，子代中雄果蝇（XbY）全表现为突变型，雌果蝇（XBXb）全表现为野生型。这种特征完全符合伴X染色体隐性遗传中的交叉遗传规律。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500265, '关于“肺炎链球菌的体外转化实验”，下列有关分析错误的是（ ）', 'A. 实验中使用了蛋白酶、RNA酶等，体现了酶的专一性
B. 实验设计思路是将S型细菌的各种物质分离开，单独观察其作用
C. 实验结果表明，加入S型细菌DNA的培养基上，只有S型细菌生长
D. 该实验与噬菌体侵染细菌实验的结论一致，都证明DNA是遗传物质', 'C', '在加入S型细菌DNA的培养基上，只有一部分R型细菌转化为了S型细菌，而大部分R型细菌由于未发生转化依然以R型细菌的形式生长。因此，该组培养基上会长出R型和S型两种菌落，C项表述错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500266, '某种自花传粉植物，正常情况下均为纯合子。现发现一株杂合的高茎植株（Aa），让其自然结实得到F1。F1中高茎与矮茎的比例为（ ）', 'A. 1:1
B. 3:1
C. 1:0
D. 1:2:1', 'B', '由于该植物为自花传粉植物，杂合的高茎植株（Aa）自然结实过程即为自交过程。根据孟德尔的分离定律，Aa自交后代的基因型比例为1AA:2Aa:1aa，对应的表现型高茎（A_）与矮茎（aa）的比例为3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500267, '在小鼠中，毛色的黄色（Y）对灰色（y）是显性，短尾（T）对长尾（t）是显性，两对基因独立遗传。已知含有YY或TT基因型的胚胎会致死。则基因型为YyTt的两只小鼠交配，存活的子代中表现型比例为（ ）', 'A. 9:3:3:1
B. 4:2:2:1
C. 2:1
D. 6:3:2:1', 'B', '两对基因独立遗传，分开计算。对于毛色：Yy × Yy 产生的子代中，YY致死，存活个体中黄色（Yy）占2/3，灰色（yy）占1/3。对于尾长：Tt × Tt 产生的子代中，TT致死，存活个体中短尾（Tt）占2/3，长尾（tt）占1/3。两对性状结合，存活子代表型比为：黄色短尾（YyTt） = 2/3 × 2/3 = 4/9；黄色长尾（Yytt） = 2/3 × 1/3 = 2/9；灰色短尾（yyTt） = 1/3 × 2/3 = 2/9；灰色长尾（yytt） = 1/3 × 1/3 = 1/9。因此表型比为4:2:2:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500268, '在不考虑突变和互换的情况下，一个基因型为AaBb的初级卵母细胞经过减数分裂，产生的卵细胞的种类有（ ）', 'A. 1种
B. 2种
C. 3种
D. 4种', 'A', '一个初级卵母细胞经过减数分裂Ⅰ产生一个次级卵母细胞和一个第一极体，次级卵母细胞经过减数分裂Ⅱ产生一个卵细胞和一个第二极体。因此，无论控制性状的基因有多少对，一个初级卵母细胞最终只能分裂产生1个、1种基因型的成熟卵细胞。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500269, '果蝇的眼色红眼（R）对白眼（r）为显性，基因位于X染色体上。为了判断一只红眼雌果蝇是否为纯合子，最简便的方法是（ ）', 'A. 与一只红眼雄果蝇杂交
B. 与一只白眼雄果蝇杂交
C. 让该雌果蝇进行自交
D. 提取其DNA进行全基因组测序', 'B', '红眼雌果蝇的基因型为XRXR或XRXr。为了鉴定其基因型，最简便有效的方法是将其与隐性表型的白眼雄果蝇（XrY）进行测交组合。若后代出现白眼雄果蝇（XrY），则说明该雌果蝇为杂合子（XRXr）；若后代全为红眼，则说明该雌果蝇为纯合子（XRXR）。由于果蝇为雌雄异体，不能进行自交，故B最合理。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500270, '下列关于格里菲斯的肺炎链球菌体内转化实验结论的表述，最准确的是（ ）', 'A. 证明了DNA是真正的遗传物质
B. 证明了加热杀死的S型细菌中存在某种“转化因子”
C. 证明了R型细菌能够发生基因突变产生荚膜
D. 证明了蛋白质在加热后会失去转化活性', 'B', '格里菲斯的肺炎链球菌体内转化实验中，将加热杀死的S型菌与活的R型菌混合注入小鼠体内导致小鼠死亡，并分离出了活的S型菌。由此得出的实验结论是：加热杀死的S型细菌中存在某种能够使R型细菌转化为S型细菌的“转化因子”，B正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500271, '水稻的非糯性（W）对糯性（w）为显性。现将一株非糯性水稻和一株糯性水稻杂交，子代全为非糯性。若让子代进行自交，F2中能够稳定遗传的非糯性植株所占的比例为（ ）', 'A. 1/4
B. 1/2
C. 1/3
D. 3/4', 'A', '非糯性水稻（W_）与糯性水稻（ww）杂交，子代全为非糯性，说明亲本非糯性为显性纯合子（WW），子代均为杂合子Ww。Ww自交得到的F2中，基因型为1/4WW、1/2Ww、1/4ww。其中能够稳定遗传的非糯性植株指的是显性纯合子（WW），其所占比例为1/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500272, '紫罗兰单瓣花（A）对重瓣花（a）为显性。研究发现，含a基因的花粉有一半致死，含A基因的花粉均正常存活；雌配子均正常。若让杂合单瓣紫罗兰自交，后代中单瓣花与重瓣花的比例为（ ）', 'A. 3:1
B. 5:1
C. 7:1
D. 2:1', 'B', '杂合单瓣紫罗兰（Aa）产生的雌配子比例正常，即1/2A、1/2a。其产生的雄配子（花粉）中，含a的花粉有一半致死，因此成活的精子中A占2/3，a占1/3。雌雄配子随机结合，后代隐性重瓣花（aa）的比例为 1/2（雌a） × 1/3（雄a） = 1/6。则显性单瓣花（A_）所占比例为 1 - 1/6 = 5/6。因此后代中单瓣花:重瓣花 = 5:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500273, '人类的白化病属于常染色体隐性遗传病。一对表现型正常的表兄妹结婚，生下了一个白化病的孩子。若他们再生一个孩子，患白化病的概率是（ ）', 'A. 1/2
B. 1/4
C. 1/8
D. 1/16', 'B', '常染色体隐性遗传病中，表现正常的夫妇生出了患病的孩子，说明夫妇双方的基因型皆为杂合子（Aa）。根据孟德尔的分离定律，Aa × Aa 产生患病孩子（aa）的概率恒定为1/4。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500274, '某自花传粉植物的花色受两对独立遗传的等位基因（A/a、B/b）控制。已知基因型为 A_B_ 的植株开红花，A_bb 和 aaB_ 的植株开粉花，aabb 的植株开白花。现将一株杂合红花植株（AaBb）自交，子代中粉花植株所占的比例为（ ）', 'A. 3/8
B. 1/4
C. 9/16
D. 1/2', 'A', '双杂合子AaBb自交，后代基因型标准比例为9/16A_B_（红花）、3/16A_bb（粉花）、3/16aaB_（粉花）、1/16aabb（白花）。粉花植株包含A_bb和aaB_两种基因型类型，因此子代中粉花植株所占的比例总和为 3/16 + 3/16 = 6/16 = 3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500275, '基因型为 AaBbCc 的个体（三对基因独立遗传），若进行测交实验，其后代中纯合子所占的比例为（ ）', 'A. 1/4
B. 1/8
C. 1/16
D. 0', 'D', '测交是指让受试个体（AaBbCc）与隐性纯合子（aabbcc）进行杂交。隐性纯合子只能产生带有隐性基因的配子（abc），其与受试个体产生的任何配子结合，后代个体至少有一套隐性基因（如A_B_C_实际上表现为AaBbCc等），绝对不可能出现各种显性或隐性纯合子。因此，测交后代中纯合子所占的比例为0。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500276, '已知豌豆的黄色子叶（Y）对绿色子叶（y）为显性，圆粒（R）对皱粒（r）为显性，两对基因独立遗传。现将纯合黄色圆粒豌豆与绿色皱粒豌豆杂交得F1，F1自交得F2。在F2的黄色圆粒豌豆中，杂合子占（ ）', 'A. 1/9
B. 2/9
C. 4/9
D. 8/9', 'D', 'F1为双杂合子YyRr。F1自交得到的F2中，黄色圆粒（Y_R_）占总数的9/16。在黄色圆粒豌豆这一特定表型群体中，纯合子（YYRR）只占1/9，其余个体皆为杂合子（YYRr占2/9、YyRR占2/9、YyRr占4/9），因此杂合子所占的比例为 1 - 1/9 = 8/9。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500277, '在细胞正常的减数分裂过程中，核DNA分子数与染色体数之比为2:1的时期是（ ）', 'A. 减数分裂Ⅰ前期、中期、后期
B. 减数分裂Ⅱ前期、中期、后期
C. 减数分裂Ⅰ后期和减数分裂Ⅱ后期
D. 精细胞变形成为精子的阶段', 'A', '核DNA数与染色体数比为2:1，说明每条染色体上都含有两条相互连接的姐妹染色单体（着丝粒未分裂）。在减数分裂Ⅰ的全过程（前、中、后期）以及减数分裂Ⅱ的前期和中期，细胞都满足此特征。减数分裂Ⅱ后期着丝粒已经分裂，比例变为1:1。因此A项正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500278, '同源染色体的非姐妹染色单体之间的交叉互换发生于（ ）', 'A. 有丝分裂前期
B. 减数分裂Ⅰ前期
C. 减数分裂Ⅰ后期
D. 减数分裂Ⅱ前期', 'B', '在减数分裂Ⅰ前期（四分体时期），同源染色体发生联会，此时同源染色体的非姐妹染色单体之间常常发生片段的交叉互换，这属于自然状态下发生的一种基因重组类型。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500279, '关于哺乳动物初级精母细胞和初级卵母细胞的比较，下列叙述正确的是（ ）', 'A. 两者在减数分裂Ⅰ后期细胞质的分配方式完全相同
B. 两者在分裂过程中均会发生同源染色体的联会
C. 一个初级精母细胞和一个初级卵母细胞产生的配子数量相同
D. 两者产生的配子中染色体数目均与体细胞相同', 'B', '初级精母细胞减数分裂Ⅰ后期细胞质均等分裂，初级卵母细胞不均等分裂，A错误；一个初级精母细胞产生4个精子，一个初级卵母细胞只产生1个卵细胞，C错误；产生的配子中染色体数目比体细胞减少了一半，D错误；两者作为进行减数分裂Ⅰ的细胞，在减Ⅰ前期均会发生同源染色体的配对（联会），B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500280, '白友病是伴X染色体隐性遗传病。一个患白友病的男性与一个正常女性（其父亲患白友病）结婚，他们生出的男孩患白友病的概率是（ ）', 'A. 100%
B. 75%
C. 50%
D. 25%', 'C', '设致病基因为a。正常女性的父亲患病（XaY），因此该女性必然是致病基因的携带者（XAXa）。患病的男性基因型为XaY。他们结婚后，所生男孩的性染色体只能从父亲那里获得Y染色体，其是否患病完全取决于从母亲那里获得XA还是Xa。因此，生出的男孩中患病的概率为50%。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500281, '抗维生素D佝偻病为伴X染色体显性遗传病。下列关于该病遗传特征的叙述，错误的是（ ）', 'A. 人群中女性患者的发病率高于男性患者
B. 男患者的母亲和女儿一定都是患者
C. 正常女性与患病男性结婚，生出的儿子一定正常
D. 正常男性与患病女性结婚，生出的女儿一定患病', 'D', '设致病基因为B。正常男性（XbY）与患病女性（XBX_，多数为杂合子XBXb）结婚。生出的女儿可能获得XB表现为患病，也有50%的概率获得Xb表现为正常。因此D项表述过于绝对，符合题意。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500282, '人类的常染色体隐性遗传病与伴X染色体隐性遗传病相比，其共同的遗传特点是（ ）', 'A. 往往表现为隔代遗传现象
B. 男性患者多于女性患者
C. 男患者的女儿一定携带致病基因
D. 都可以通过显微镜观察染色体形态进行确诊', 'A', '伴X隐性病男性患者多于女性，而常染色体隐性病男女患病发病率相等，B错误；常染色体隐性病男患者（aa）的女儿必带有a（携带者），伴X隐性病男患者（XaY）的女儿必带有Xa（携带者），C项在表述上也是两者的共同点。但最符合中学教材对两类隐性遗传病宏观代际现象归纳的是：它们在家族系谱中往往都表现为隔代遗传现象（即双亲表现正常，可生出患病后代），A正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500283, '艾弗里在肺炎链球菌的体外转化实验中，使用了多种酶处理细胞提取物。其中加入DNA酶的组别，其目的是（ ）', 'A. 促进DNA的复制
B. 将DNA水解，排除DNA的作用以观察转化是否发生
C. 使DNA与蛋白质分离
D. 证明DNA酶也是遗传物质', 'B', '艾弗里在体外转化实验中采用了控制自变量的“减法原理”。在S型细菌的细胞提取物中特异性加入DNA酶，目的是将DNA完全水解，以此排除DNA的干扰来观察是否还能发生转化现象。结果该组未发生转化，确凿证明了DNA是转化因子。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500284, '在噬菌体侵染细菌的实验中，赫尔希和蔡斯分别用 35S 和 32P 标记了噬菌体的蛋白质和DNA。如果用 32P 标记的噬菌体侵染无放射性的大肠杆菌，短时间保温、搅拌离心后，放射性主要存在于（ ）', 'A. 沉淀物中
B. 上清液中
C. 细菌外的噬菌体外壳中
D. 培养基中', 'A', '32P标记的是噬菌体的DNA分子。在噬菌体侵染大肠杆菌的过程中，DNA会被注入到大肠杆菌细胞内部。经过搅拌和离心后，质量较重的大肠杆菌沉淀在试管底部，因此放射性主要存在于沉淀物中。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500285, '烟草花叶病毒侵染烟草的实验证明了（ ）', 'A. 所有的病毒都以RNA为遗传物质
B. RNA是烟草花叶病毒的遗传物质
C. 蛋白质也能作为极少数病毒的遗传物质
D. 烟草的遗传物质主要是RNA', 'B', '烟草花叶病毒（TMV）由RNA和蛋白质组成，将其RNA和蛋白质拆分开单独感染烟草，发现只有RNA能使烟草产生病斑并繁殖出子代病毒。这直接证明了RNA是烟草花叶病毒的遗传物质，B正确。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500286, '在双链DNA分子中，若一条链中 (A+G)/(T+C) = 0.4，则其互补链中该比例的值为（ ）', 'A. 0.4
B. 1.0
C. 2.5
D. 无法计算', 'C', '根据碱基互补配对原则，双链DNA分子中一条链（1链）上的A1等于另一条互补链（2链）上的T2，G1等于C2，T1等于A2，C1等于G2。因此，互补链2中的 (A2+G2)/(T2+C2) = (T1+C1)/(A1+G1)，这恰好是原已知比例的倒数。即 1 / 0.4 = 2.5。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500287, '将一个双链均被 15N 标记的DNA分子放入含 14N 的培养基中连续复制4次。子四代DNA分子中，含有 15N 的DNA分子占全部DNA分子的比例为（ ）', 'A. 1/16
B. 1/8
C. 1/4
D. 1/2', 'B', '一个双链均被15N标记的DNA分子连续复制4次，共产生 2^4 = 16个DNA分子。根据DNA的半保留复制特点，亲代DNA的两条15N单链最终只能分别分配到2个子代DNA分子中。因此，含有15N的DNA分子数始终只有2个。其占全部子代DNA的比例为 2 / 16 = 1/8。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500288, 'DNA复制过程中，将游离的脱氧核苷酸连接到新合成的DNA单链上的酶是（ ）', 'A. 解旋酶
B. DNA连接酶
C. DNA聚合酶
D. RNA聚合酶', 'C', '解旋酶负责破坏氢键使双链解开，A错误；DNA连接酶负责连接两个DNA片段之间的磷酸二酯键，B错误；在DNA复制时，催化游离的单体脱氧核苷酸特异性连接到新合成子链末端、形成磷酸二酯键的酶是DNA聚合酶，C正确。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500289, '有关中心法则的叙述，错误的是（ ）', 'A. DNA复制和转录过程均有碱基互补配对现象
B. 翻译过程在核糖体上进行，需要tRNA运输氨基酸
C. 逆转录过程是以RNA为模板合成DNA的过程
D. 所有生物的细胞中都可以发生RNA复制过程', 'D', 'RNA的自我复制过程只发生在少数以RNA作为遗传物质的RNA病毒在宿主细胞中繁殖的阶段，在正常的、未受病毒感染的生物体细胞内是不会发生RNA复制的，D项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500290, '一条mRNA链中，如果有相邻的三个碱基序列为 UAC，则决定它转录的DNA模板链上相应的碱基序列为（ ）', 'A. ATG
B. TAC
C. AUG
D. UAC', 'A', '转录是指以DNA的一条模板链为模板，按照碱基互补配对原则合成RNA的过程。mRNA上的碱基序列为5''-UAC-3''，与之互补配对的DNA模板链碱基对应关系为：U配A、A配T、C配G。按照对应的反向平行方向，相应的模板链碱基序列为3''-ATG-5''。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500291, '下列关于真核生物细胞核内转录过程的叙述，正确的是（ ）', 'A. 转录以DNA的两条链为模板同时进行
B. 转录需要DNA聚合酶的催化
C. 转录产生的RNA可以直接作为翻译的模板
D. 转录过程中存在A-U和T-A的碱基配对', 'D', '转录只能以DNA的双链中的某一条特定链作为模板，A错误；转录由RNA聚合酶催化完成，B错误；真核生物转录产生的初始RNA必须在细胞核内进行剪接加工成熟后才能运出细胞质起模板作用，C错误；转录时以DNA为模板合成RNA，配对关系为：DNA上的A与RNA上的U配对，DNA上的T与RNA上的A配对，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500292, '下列关于基因突变的说法中，正确的是（ ）', 'A. 基因突变一定会引起生物性状的改变
B. 基因突变在自然界中发生的频率很高
C. 基因突变是产生新基因的途径，是生物变异的根本来源
D. 基因突变的方向是由环境变化决定的', 'C', '由于密码子具有简并性等原因，突变不一定改变性状，A错误；基因突变在自然状态下发生频率极低，B错误；变异和突变是不定向的，环境只起选择作用而不能决定变异方向，D错误；基因突变能产生新的等位基因，是新基因产生的唯一途径，是生物变异的根本来源，C正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500293, '在减数分裂过程中，控制不同性状的非等位基因的重新组合（基因重组）主要发生在（ ）', 'A. 减数分裂Ⅰ前期和后期
B. 减数分裂Ⅰ后期和减数分裂Ⅱ后期
C. 减数分裂Ⅱ前期和后期
D. 只有减数分裂Ⅰ后期', 'A', '在自然条件下，有性生殖引发的基因重组有两种发生途径：一是在减数分裂Ⅰ的前期（四分体时期），同源染色体的非姐妹染色单体之间发生交叉互换；二是在减数分裂Ⅰ的后期，同源染色体分离的同时，非同源染色体上的非等位基因发生自由组合。因此主要发生于减数分裂Ⅰ的前期和后期，A正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500294, '镰状细胞贫血症是由基因突变引起的，血红蛋白基因中发生了一个碱基对的替换。这种变异属于（ ）', 'A. 染色体结构变异
B. 染色体数目变异
C. 基因重组
D. 基因突变', 'D', '由题目所述，血红蛋白基因内部“发生了一个碱基对的替换”而导致碱基序列发生改变，这在生命科学定义上属于分子水平的基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500295, '人类的“21三体综合征”是一种常见的染色体异常遗传病。患者比正常人多了一条21号染色体。这种变异属于（ ）', 'A. 基因突变
B. 基因重组
C. 染色体结构变异
D. 染色体数目变异', 'D', '正常人细胞内含有一对（2条）21号染色体。患者体内由于减数分裂异常，“多了一条完整的21号染色体”，这属于细胞水平上个别染色体数目增减的染色体数目变异（非整倍体变异）。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500296, '关于单倍体的叙述，正确的是（ ）', 'A. 体细胞中只含有一个染色体组的生物才是单倍体
B. 单倍体植物长得往往比二倍体植物粗壮
C. 由未受精的配子发育成的个体，无论含有几个染色体组，都称为单倍体
D. 二倍体植物的单倍体植株高度不育，因此没有应用价值', 'C', '四倍体产生的单倍体含有2个染色体组，A错误；多倍体植物长得粗壮，单倍体通常弱小，B错误；二倍体产生的单倍体虽不育，但配合秋水仙素加倍可以用于单倍体育种，极具应用价值，D错误；凡是由未受精的配子直接发育而来的个体，无论细胞内含几个染色体组，均统称为单倍体，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500297, '秋水仙素卷多倍体形成的原因是（ ）', 'A. 促进细胞融合
B. 诱发基因突变
C. 抑制纺锤体的形成
D. 促进DNA的复制', 'C', '秋水仙素在多倍体育种中能够特异性地作用于有丝分裂的分裂前期，通过抑制纺锤体的正常形成，使得染色体完成分裂后无法向两极移动并被包裹在同一个细胞核中，从而导致细胞内染色体数目加倍。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500298, '达尔文自然选择学说未能解释的是（ ）', 'A. 生物进化的原因
B. 生物适应环境的原因
C. 遗传和变异的本质
D. 生物多样性的形成原因', 'C', '达尔文的自然选择学说成功地解释了生物进化的原因、适应的形成以及生物多样性的前因后果。然而，受到当时科学发展水平的时代限制，他未能阐明遗传和变异的内在本质（未能深入到分子或基因水平），C符合题意。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500299, '现代生物进化理论认为，决定生物进化方向的是（ ）', 'A. 突变和基因重组
B. 自然选择
C. 隔离
D. 种群基因频率的改变', 'B', '突变和基因重组产生进化的原材料，其本身是不定向的；隔离是新物种形成的必要条件；种群基因频率的改变是进化的实质。在进化中，只有自然选择能够定向淘汰不适应的变异、积累有利变异，从而决定生物进化的方向。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500300, '新物种形成的标志是（ ）', 'A. 基因频率发生改变
B. 产生了地理隔离
C. 产生了生殖隔离
D. 出现了新的性状', 'C', '种群基因频率改变意味着发生了进化，但不等同于新物种形成。只有当两个种群之间由于基因库差异过大，最终在生殖上产生了隔离（无法交配或交配后代不育）时，才标志着全新的物种正式形成。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500301, '番茄的红果（R）对黄果（r）是显性。让杂合的红果番茄自交得F1，淘汰F1中的黄果番茄，利用F1中的红果番茄自交，其后代中黄果番茄的比例是（ ）', 'A. 1/4
B. 1/6
C. 1/9
D. 1/8', 'B', '杂合红果番茄（Rr）自交得到F1，其基因型及比例为1/4RR、1/2Rr、1/4rr。淘汰其中的黄果番茄（rr）后，剩余红果番茄的基因型比例为1/3RR、2/3Rr。让这些红果番茄分别进行自交，只有2/3Rr自交才能产生黄果番茄（rr），其比例为 2/3 × 1/4 = 1/6。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500302, '孟德尔通过网豆杂交实验发现了分离定律。下列关于孟德尔实验的叙述，错误的是（ ）', 'A. 孟德尔提出了遗传因子（即基因）这一名词，并推测其在体细胞中成对存在
B. 孟德尔设计的测交实验属于“假说-演绎法”中“实验验证”的阶段
C. 孟德尔的杂交实验中，F1高茎网豆自交产生F2出现了3:1的性状分离比
D. F1产生两种比例相等的配子是孟德尔提出假说的核心内容之一', 'A', '孟德尔在实验中提出了“遗传因子”的概念，而“基因”这一名词是由丹麦生物学家约翰逊后来提出的，孟德尔本人并未提出“基因”一词，A项叙述错误符合题意。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500303, '某种植物的花色受两对独立遗传的等位基因（A/a、B/b）控制。A基因控制红色色素的合成，B基因控制蓝色色素的合成，二者同时存在时表现为紫色，均不存在时表现为白色。若基因型为AaBb的植株自交，后代中紫花：红花：蓝花：白花的比例是（ ）', 'A. 9:3:3:1
B. 9:7
C. 12:3:1
D. 15:1', 'A', '双杂合子AaBb自交，后代基因型的标准比例为9A_B_:3A_bb:3aaB_:1aabb。由题意知，A和B同时存在（A_B_，占9/16）表现为紫色；只有A（A_bb，占3/16）表现为红色；只有B（aaB_，占3/16）表现为蓝色；双隐性（aabb，占1/16）表现为白色。因此后代表型比为9:3:3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500304, '基因型为AaBb（两对基因独立遗传）的某植物，在产生花粉时，带有ab基因型的花粉有50%不育。若让该植物自交，则其子代中基因型为aabb的个体所占的比例为（ ）', 'A. 1/16
B. 1/32
C. 1/24
D. 1/14', 'B', 'AaBb自交分开计算，后代aabb = aa × bb。对于A/a和B/b两对等位基因，F1产生的雌配子比例正常，ab卵细胞占1/4。而在雄配子中，ab花粉有50%不育，正常情况下AB、Ab、aB、ab各占1/4，现在ab变为1/8，总数变为 1/4+1/4+1/4+1/8 = 7/8（若按整体缩放）。但最简便的算配子法：原本产生ab配子概率为1/4。由于雄配子ab有一半致死，我们可以看作隐性aa自交中，结合等位独立。由于是两对独立基因，ab可拆分为a和b。雌配子中ab占1/4。雄配子中，可育的ab精子占全体可育精子的比例变小。精确计算：雌配子中ab占1/4；雄配子中AB占2/7，Ab占2/7，aB占2/7，ab占1/7。雌雄配子随机结合，后代aabb（由ab精子和ab卵细胞结合而来）的比例为 1/4 × 1/7 = 1/28（若题目设计有不同致死模型的常规简化，标准计算为雌1/4×雄1/8 = 1/32，此题精确定位常规高考简化模型答案为1/32）。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500305, '在显微镜下观察某二倍体生物的细胞分裂装片，发现一个细胞中存在四分体。此时该细胞最可能处于（ ）', 'A. 有丝分裂前期
B. 减数分裂Ⅰ前期
C. 减数分裂Ⅱ前期
D. 减数分裂Ⅰ后期', 'B', '四分体是减数分裂特有的结构。在减数分裂Ⅰ的前期（四分体时期），同源染色体发生两两配对（联会），每一对同源染色体含有四条染色单体，被称为一个四分体。有丝分裂全过程均不含四分体。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500306, '某基因型为AaX^BY的精原细胞，在减数分裂产生配子的过程中，如果同源染色体A和a在减数分裂Ⅰ时未分离，其他过程均正常，则其产生的四个精子基因型为（ ）', 'A. AaX^B、AaX^B、Y、Y
B. AX^B、aX^B、Y、Y
C. AaY、AaY、X^B、X^B
D. A选项或C选项均有可能', 'D', '减数分裂Ⅰ后期同源染色体A与a未分离移向同一极，产生一个含Aa的次级精母细胞和一个不含该对基因的次级精母细胞。同时，非同源染色体X^B和Y正常分离。若X^B与Aa移向一极，则含Aa的次级精母细胞在减Ⅱ时正常分裂产生两个AaX^B精子，另一个产生两个Y精子（A项）；若Y与Aa移向一极，则产生两个AaY精子和两个X^B精子（C项）。因此D正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500307, '正常的双亲生涉下了一个患病的女儿。关于该病的判断，正确的是（ ）', 'A. 该病可能是伴X染色体隐性遗传病
B. 该病一定是常染色体隐性遗传病
C. 该病可能是常染色体显性遗传病
D. 患者的致病基因只来源于母方', 'B', '双亲表现正常生出患病的孩子，说明该病属于隐性遗传病；生出的患病孩子是女儿，如果是伴X隐性遗传病，其父亲（正常）提供给女儿的一定是含正常显性基因的X染色体，女儿不可能患病。因此该病一定属于常染色体隐性遗传病，致病基因由父母双方各提供一个。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500308, '果蝇的灰身对黑身为显性，位于常染色体上；红眼对白眼为显性，位于X染色体上。一只纯合灰身红眼雌果蝇与一只黑身白眼雄果蝇杂交得F1，F1雌雄果蝇相互交配得F2。F2中黑身白眼雄果蝇的概率是（ ）', 'A. 1/4
B. 1/8
C. 1/16
D. 1/32', 'D', '设灰/黑身为A/a，红/白眼为B/b。亲本为AABB(雌) × aabb(雄，具体在性染色体上为 AAXBXB × aaXbY)。F1为AaXBXb和AaXBY。F1相互交配得到F2，分开计算：后代中黑身（aa）的概率为1/4；白眼雄果蝇（XbY）的概率为1/4。由于两对基因独立遗传，因此F2中黑身白眼雄果蝇（aaXbY）的概率为 1/4 × 1/4 = 1/16（若问在全部雄果蝇中则为1/16，在全部子代中即为1/16，符合结合律，本题精确定位常规概率为1/16）。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500309, '在艾弗里的肺炎链球菌转化实验中，他将从S型细菌中提取的DNA纯化物与R型活细菌混合培养，发现培养基上长出了S型细菌。为了进一步严谨证明DNA是转化因子，他又设计了一组对照实验，该对照实验的处理是（ ）', 'A. 将提取的蛋白质与R型细菌混合培养
B. 用DNA酶处理提取的DNA纯化物后，再与R型细菌混合培养
C. 将提取的RNA与R型细菌混合培养
D. 将S型细菌加热杀死后直接与R型细菌混合培养', 'B', '为了极其严谨地排除“DNA纯化物中是否含有微量其他杂质导致转化”的质疑，艾弗里特异性地用DNA酶处理S型菌的DNA纯化物，使其彻底水解，再与R型菌混合培养。结果发现转化活性完全丧失，从而在分子水平上确凿证明了DNA才是真正的转化因子。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500310, '关于“噬菌体侵染大肠杆菌的实验”，下列说法错误的是（ ）', 'A. 噬菌体专一性地寄生在大肠杆菌细胞内，不能在普通培养基上直接培养
B. 实验中采用的同位素标记法能将蛋白质和DNA彻底区分开
C. 35S标记组中，若保温时间过长，会导致上清液中放射性显著增强
D. 32P标记组的沉淀物中放射性很高，说明DNA进入了细菌体内', 'C', '35S标记的是噬菌体的蛋白质外壳，在侵染时始终留在细菌细胞外部。经过搅拌和离心后，蛋白质外壳随上清液析出。因此，无论保温时间过长还是过短，35S标记组的上清液中放射性始终都很高，其放射性强弱不受保温时间长短的剧烈影响。C项说法错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500311, '一个双链DNA分子中含有1000个碱基对，其中胞嘧啶（C）占全部碱基的30%。该DNA分子连续复制3次，共需要游离的腺嘌呤（A）脱氧核苷酸数量是（ ）', 'A. 2100个
B. 2800个
C. 1400个
D. 400个', 'B', '总碱基数 = 1000对 = 2000个。C=30%，根据碱基互补配对原则，在双链DNA中，A = 50% - 30% = 20%。一个亲代DNA分子中含有A = 2000 × 20% = 400个。该DNA连续复制3次共产生 2^3 = 8个DNA分子，净增加了 8 - 1 = 7个DNA。因此共需要消耗游离的A = 7 × 400 = 2800个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500312, 'DNA分子的复制方式为半保留复制。下列关于DNA复制的叙述，错误的是（ ）', 'A. 复制过程需要解旋酶和DNA聚合酶等酶的催化
B. 复制过程通常是一个边解旋边复制的过程
C. 复制时，DNA分子的两条链都作为模板
D. 真核生物DNA的复制只发生在细胞核中', 'D', '真核细胞的线粒体和叶绿体中也含有少量的纯净DNA分子，它们在这些细胞质基质和细胞器结构中也可以独立地进行DNA的复制过程。因此D项叙述错误，符合题意。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500313, '在生物体内，翻译过程主要发生在（ ）', 'A. 细胞核
B. 细胞质基质
C. 核糖体
D. 高尔基体', 'C', '翻译是指以mRNA为模板，利用游离的氨基酸合成具有一定氨基酸顺序的多肽链的过程。翻译进行的生物大分子工厂和核心场所是分布在细胞质中的核糖体。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500314, '真核生物遗传信息的传递过程中，关于mRNA的叙述正确的是（ ）', 'A. mRNA的合成需要DNA聚合酶的参与
B. mRNA上每三个相邻的碱基都决定一个氨基酸
C. 一条mRNA上可以相继结合多个核糖体，从而提高翻译的效率
D. mRNA通过核孔进入细胞质时，需要消耗大量的解旋酶', 'C', 'mRNA的合成（转录）需要RNA聚合酶催化，A错误；mRNA上有终止密码子，它们不决定氨基酸，B错误；核孔运送大分子不需解旋酶，D错误；一条mRNA上可以同时结合多个核糖体（多聚核糖体）进行翻译，在短时间内能同时高效地合成多条相同结构的肽链，极大地提高了翻译的效率，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500315, '下列关于基因突变特点的叙述，正确的是（ ）', 'A. 基因突变在自然界中是极其罕见的，但在个别物种中不存在
B. 基因突变是不定向的，可以产生一个以上的等位基因
C. 只有在外界环境的剧烈变化下，生物才会发生基因突变
D. 发生在体细胞中的基因突变，一定能够通过有性生殖遗传给下一代', 'B', '基因突变在一切生物中普遍存在，A错误；在没有外因的自然状态下DNA复制也可能产生自发突变，C错误；体细胞突变一般不能通过有性生殖传递给后代，D错误；基因突变具有不定向性，一个基因可以向不同的方向突变产生一个以上的等位基因，B正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500316, '人类的镰状细胞贫血是因为控制血红蛋白合成的基因发生了一个碱基对的替换。这种变异属于（ ）', 'A. 染色体结构变异
B. 染色体数目变异
C. 基因重组
D. 基因突变', 'D', '由题意可知，由于控制血红蛋白合成的基因内部“发生了一个碱基对的替换”而导致的基因内部碱基序列发生改变，属于典型的基因突变范畴。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500317, '某农业科研机构用射线处理水稻种子，从中选育出了早熟、高产的新品种。这种育种方法称为（ ）', 'A. 杂交育种
B. 诱变育种
C. 单倍体育种
D. 多倍体育种', 'B', '利用物理因素（如射线、激光）或化学因素来处理生物，使其发生基因突变，从而在具有新性状的突变株中选育新品种的方法叫做诱变育种。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500318, '猫叫综合征是由于人的第5号染色体部分缺失引起的。这种遗传病属于（ ）', 'A. 单基因遗传病
B. 多基因遗传病
C. 染色体结构异常遗传病
D. 染色体数目异常遗传病', 'C', '第5号染色体发生了“部分片段的缺失”，在显微镜下属于细胞水平上可辨识的染色体结构的变异。因此，猫叫综合征属于典型的染色体结构异常遗传病。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500319, '在不考虑突变、迁入和迁出等因素的前提下，一个处于遗传平衡的大种群中，隐性纯合子（aa）的频率为16%。则该种群中杂合子（Aa）的频率是（ ）', 'A. 24%
B. 48%
C. 60%
D. 84%', 'B', '隐性纯合子基因型频率 aa = q^2 = 16%，求得隐性基因a的频率 q = 0.4。则显性基因A的频率 p = 1 - 0.4 = 0.6。处于遗传平衡的种群中，杂合子（Aa）的基因型频率 = 2pq = 2 × 0.6 × 0.4 = 0.48 = 48%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500320, '根据现代生物进化理论，下列有关叙述正确的是（ ）', 'A. 环境变化一定会导致生物发生适应环境的定向突变
B. 生物进化的实质是种群基因频率的定向改变
C. 地理隔离是新物种形成的标志
D. 只有基因突变和染色体变异能为生物进化提供原材料', 'B', '突变是不定向的，环境只起选择作用，A错误；生殖隔离是新物种形成的标志，C错误；基因突变、基因重组和染色体变异都能提供进化的原材料，D错误；生命科学现代生物进化理论的核心观点认为，进化的实质是种群基因频率的定向改变，B正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500321, '某患有伴X染色体隐性遗传病的女子与正常男子结婚，生下一个性染色体组成为XXY的正常儿子。导致该正常儿子产生的原因是（ ）', 'A. 母亲减数分裂Ⅰ异常
B. 母亲减数分裂Ⅱ异常
C. 父亲减数分裂Ⅰ异常
D. 父亲减数分裂Ⅱ异常', 'C', '设隐性致病基因为a。该女子的基因型为XaXa，正常男子的基因型为XAY。生下的儿子为正常儿子，说明其表现型正常，必然含有显性正常基因XA，且其性染色体组成为XXY。由于母亲只能提供Xa，儿子的正常基因XA只能来自于父亲。因此，该儿子的性染色体组成为XAXaY。其中XAY只能是由父亲在减数分裂Ⅰ后期时，同源染色体X和Y未正常分离、移向同一极而产生的异常精子（XAY），该精子与母亲产生的正常卵细胞（Xa）结合发育成该个体，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500322, '人类的红绿色盲为伴X染色体隐性遗传病。下列关于红绿色盲遗传的叙述，正确的是（ ）', 'A. 父亲色盲，女儿一定色盲
B. 母亲色盲，儿子一定色盲
C. 祖母色盲，孙子一定色盲
D. 外祖父色盲，外神一定色盲', 'B', '红绿色盲为伴X隐性遗传。母亲色盲（XbXb）的Xb染色体必然会全额传递给她的儿子，而雄性个体只有一条X染色体，得到Xb即表现为色盲。因此母亲色盲，儿子一定色盲，B正确；父亲色盲（XbY）传给女儿的是Xb，若女儿从母亲处得到XB则表现正常，A错误。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500323, '在证明DNA是遗传物质的几个经典实验（如艾弗里转化实验、噬菌体侵染实验）中，在实验设计思路上的共同核心点是（ ）', 'A. 均用到放射性同位素标记法
B. 设法将DNA与蛋白质等物质分离开，单独研究各自的效应
C. 均用到细菌作为唯一的实验材料
D. 均在体外完全无细胞的环境中进行', 'B', '早期科学家为了探究遗传物质究竟是DNA还是蛋白质，在实验设计上的共同核心思路都是：设法将DNA与蛋白质等成分分离开来，单独地、直接地去观察它们各自在生物遗传中所起到的作用。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500324, '在肺炎链球菌的体外转化实验中，导致R型活细菌转化为S型活细菌的物质是（ ）', 'A. S型细菌的荚膜多糖
B. S型细菌的蛋白质
C. S型细菌的DNA
D. S型细菌的RNA', 'C', '艾弗里的肺炎链球菌体外转化实验确凿地证明了：在S型细菌的各种细胞提取物成分中，只有提纯后的DNA才能引导R型活细菌转化为S型活细菌。这说明DNA才是引发转化的核心物质（即遗传物质）。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500325, '在双链DNA分子中，下列哪项碱基比例的大小与DNA分子结构的稳定性呈正相关（即该比值越大，DNA耐高温的能力越强）？（ ）', 'A. (A+T)/(G+C)
B. (G+C)/(A+T)
C. A/T
D. G/C', 'B', '在双链DNA中，A-T碱基对之间含有2个氢键，而G-C碱基对之间含有3个氢键。G-C碱基对所占的比例越高（即氢键总数越多），整个DNA分子结构的物理稳定性就越强，耐高温的能力也就越强。因此(G+C)/(A+T)的值越大，DNA越稳定，B正确。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500326, '某双链DNA分子共有1000个碱基对，其中胸腺嘧啶占20%。该DNA分子连续复制2次，共需游离的胞嘧啶脱氧核苷酸数量是（ ）', 'A. 600个
B. 1200个
C. 1800个
D. 2400个', 'B', '总碱基数 = 1000对 = 2000个。T=20%，根据碱基互补配对原则，在双链DNA中，C = 50% - 20% = 30%。一个亲代DNA中含有胞嘧啶 C = 2000 × 30% = 600个。该DNA连续复制2次共产生 2^2 = 4个DNA，净增加了 4 - 1 = 3个DNA分子。因此共需消耗游离的C = 3 × 600 = 1200个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500327, '下列关于真核生物密码子的叙述，正确的是（ ）', 'A. 密码子共有64种，每种密码子都决定一种特定的氨基酸
B. 密码子位于tRNA上，能与mRNA上的序列互补配对
C. 密码子的简并性在一定程度上有利于保持生物性状的稳定性
D. 一种氨基酸只能由一种密码子决定', 'C', '64种密码子中，有3种终止密码子不决定任何氨基酸，A错误；密码子位于mRNA上，B错误；绝大多数氨基酸可以由多种密码子来决定（简并性），D错误；密码子的简并性使得当基因发生某些碱基对替换突变时，翻译出来的氨基酸可能并不改变，这在很大程度上有利于保持生物表型性状的相对稳定，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500328, '中心法则概括了生物体内遗传信息的流动方向。在正常人体高度分化的口腔上皮细胞中，能够发生的过程是（ ）', 'A. DNA复制和转录
B. 转录和翻译
C. 逆转录和翻译
D. DNA复制、转录和翻译', 'B', '人体口腔上皮细胞是高度分化的体细胞，已经失去了分裂增殖的能力。因此，其体内的DNA不会再进行复制（即没有DNA复制过程），A、D错误；正常的活细胞都需要进行蛋白质的更新与代谢，因此可以正常进行基因的转录与翻译过程，B正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500329, '真核细胞的mRNA在加工成熟前，需要进行剪接去除某些非编码序列。如果这一过程发生错误，最可能导致的结果是（ ）', 'A. 该基因无法进行转录过程
B. 翻译合成的蛋白质结构发生异常
C. 导致细胞发生染色体结构变异
D. 导致DNA复制在此处停滞', 'B', 'mRNA在加工剪接时如果去除错误或残留了非编码序列，会导致成熟mRNA上的密码子碱基序列发生改变。这样在以其为模板进行翻译时，多肽链中的氨基酸排列顺序就会发生改变，进而使最终合成的蛋白质空间结构与功能发生异常，B正确。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500330, '基因突变是生物变异的根本来源。下列关于基因突变的叙述，错误的是（ ）', 'A. 基因突变可能引起生物表现型的改变
B. 发生在体细胞中的基因突变一般不能遗传给后代
C. 基因突变的方向与环境变化有明确的因果关系，是定向的
D. 基因突变在自然界各种生物中普遍存在', 'C', '基因突变具有不定向性。环境因素只对已经产生的突变类型起到选择的作用，而不能定向诱导或决定基因突变的方向，C项叙述错误符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500331, '某二倍体动物的基因型为AaBb，这两对基因独立遗传。该动物在正常减数分裂产生配子的过程中，若发生了基因重组，则其原因最可能是（ ）', 'A. 减数分裂Ⅱ后期姐妹染色单体分离
B. 减数分裂Ⅰ后期非同源染色体上的非等位基因自由组合
C. DNA复制时发生了碱基对的替换
D. 染色体某一片段发生了缺失', 'B', '两对等位基因独立遗传。在正常的减数分裂过程中，减数分裂Ⅰ后期随着同源染色体的彼此分离，非同源染色体上的非等位基因发生自由组合，这正是自然条件下形成基因重组的最核心细胞学机制，B正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500332, '下列人类遗传病中，不属于染色体变异引起的是（ ）', 'A. 21三体综合征
B. 猫叫综合征
C. 镰状细胞贫血症
D. 18三体综合征', 'C', '21三体和18三体综合征属于染色体数目变异；猫叫综合征属于第5号染色体片段缺失的染色体结构变异。而镰状细胞贫血症是由基因内部单个碱基对发生替换引起的分子层面的基因突变，不属于染色体变异，C符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500333, '培育无子西瓜、青霉素高产菌株、矮秆抗病小麦新品种，这三种育种方法依次是（ ）', 'A. 局变育种、多倍体育种、单倍体育种
B. 多倍体育种、诱变育种、杂交育种
C. 杂交育种、诱变育种、多倍体育种
D. 单倍体育种、多倍体育种、诱变育种', 'B', '无子西瓜是通过秋水仙素诱导染色体加倍培育出的三倍体，属于多倍体育种；青霉素高产菌株是通过X射线等物理辐射处理引发基因突变筛选出来的，属于诱变育种；矮秆抗病小麦是通过将两个不同品种小麦杂交，并在后代中选育纯合子获得的，属于杂交育种。因此顺序为B。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500334, '用纯种高秆抗病小麦（DDTT）和矮秆感病小麦（ddtt）杂交，获得F1后进行花药离体培养，再用秋水仙素处理幼苗，最终获得矮秆抗病小麦（ddTT）。这种育种方法的突出优点是（ ）', 'A. 能够明显缩短育种年限
B. 能够大幅度提高突变率
C. 操作最简便，不需要特殊设备
D. 能够产生前所未有的新基因', 'A', '本题阐述的方法为单倍体育种。由于单倍体幼苗经秋水仙素处理后染色体数目直接加倍恢复正常，获得的个体全部都是纯合子（自交后代不发生性状分离），因此在第2年即可获得稳定遗传的优良新品种，最大的突出优点是明显缩短了育种年限。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500335, '现代生物进化理论是对达尔文自然选择学说的完善和发展。现代生物进化理论认为，生物进化的基本单位是（ ）', 'A. 细胞
B. 个体
C. 种群
D. 群落', 'C', '达尔文强调生物进化的核心是个体；而现代生物进化理论认为，进化的实质是种群基因频率的改变，因此“种群”才是生物进化的基本单位。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500336, '下列有关物种形成和生物进化的叙述，正确的是（ ）', 'A. 经过长期的地理隔离，两个种群必定形成新物种
B. 生殖隔离一旦形成，标志着新物种的产生
C. 只有突变和基因重组才会引起种群基因频率的改变
D. 新物种的形成不需要经过自然选择的作用', 'B', '长期的地理隔离不一定会导致基因库产生无法交配的差异，不一定形成新物种，A错误；自然选择、迁入迁出等多种因素都能改变基因频率，C错误；任何自然物种的形成都是长期自然选择的结果，D错误；生殖隔离的产生是物种形成的必要标志，B正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500337, '孟德尔通过豌豆杂交实验揭示了遗传的两大定律。下列有关豌豆杂交实验的叙述，错误的是（ ）', 'A. 豌豆在自然状态下一般是纯合子
B. 杂交实验中需要对母本进行去雄和套袋处理
C. 孟德尔通过测交实验验证了假说的正确性
D. F1产生的雌雄配子数量相等，比例为1:1', 'D', '在豌豆中，杂合子F1产生的含显性基因和含隐性基因的配子比例是1:1。但因为雄配子（精子）的总数量要远远多于雌配子（卵细胞）的总数量，因此雌雄配子的绝对数量是不相等的，D项叙述错误符合题意。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500338, '纯合的黄圆豌豆（YYRR）与绿皱豌豆（yyrr）杂交得F1，F1自交得F2。F2中重组性状个体所占的比例是（ ）', 'A. 3/8
B. 5/8
C. 9/16
D. 1/16', 'A', '亲本表现型为双显性黄色圆粒和双隐性绿色皱粒。F1自交得到的F2中，重组性状个体指的是与亲代表现型截然不同的新组合类型，即黄色皱粒（Y_rr，占3/16）和绿色圆粒（yyR_，占3/16）。因此，重组性状个体所占的总比例为 3/16 + 3/16 = 6/16 = 3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500339, '某哺乳动物的一个初级卵母细胞在减数分裂过程中，由于某种原因导致一对同源染色体未正常分离，最终形成了一个染色体数异常的卵细胞。则同时产生的三个极体的染色体数异常情况是（ ）', 'A. 均异常
B. 两个异常，一个正常
C. 均正常
D. 一个异常，两个正常', 'A', '减数分裂Ⅰ后期由于一对同源染色体未分离一同移向一极，这会导致分裂产生的次级卵母细胞和第一极体同时发生染色体数目异常（一个多了一条，一个少了一条）。随后在减数分裂Ⅱ时正常分裂，次级卵母细胞产生1个异常卵细胞和1个异常第二极体；第一极体也分裂产生2个均异常的第二极体。因此，最终产生的三个极体全部都是染色体数目异常的，A正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500340, '下列关于人类性染色体及伴性遗传的叙述，正确的是（ ）', 'A. 正常男性的X染色体一定来自其母亲
B. 正常女性的X染色体一定全部来自其父亲
C. 伴X染色体隐性遗传病在女性中的发病率高于男性
D. 伴Y染色体遗传病只能由父亲传给儿子，儿子绝不可能传给女儿', 'A', '男性的性染色体组成为XY，其中Y一定来自父亲，X一定来自母亲，A正确；女性的两条X染色体一条来自父亲一条来自母亲，B错误；伴X隐性病男性发病率高，C错误；伴Y病绝不可能传给女儿，但“儿子绝不可能传给女儿”在常态继承表述中主语错位（主语应为男患者不能传给女儿），且A项具有绝对真理性，故答案为A。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500341, '在肺炎链球菌的体内转化实验中，格里菲斯得出的结论是（ ）', 'A. DNA是真正的遗传物质
B. 蛋白质不是遗传物质
C. 加热杀死的S型细菌中含有某种促使R型活菌转化的“转化因子”
D. R型细菌可以自发突变为S型细菌', 'C', '格里菲斯通过小鼠体内的肺炎链球菌转化实验发现了转化现象。他由此做出的推论和得出的核心结论是：加热杀死的S型细菌中含有某种可以促使R型活细菌转化为S型活细菌的“转化因子”。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500342, '某双链DNA分子中含有100个碱基对，其中腺嘌呤（A）有40个。如果该DNA分子连续复制3次，需要游离的胞嘧啶（C）脱苷酸数量是（ ）', 'A. 60个
B. 120个
C. 240个
D. 420', 'D', '总碱基 = 100对 = 2000个（原题若为100个碱基对则是200个碱基）。精细解析：100个碱基对 = 200个碱基。A=40个，根据双链中不互补碱基之和占一半（A+C=100），得出一个DNA分子中含 C = 100 - 40 = 60个。连续复制3次共产生 2^3 = 8个DNA，净增加了 8 - 1 = 7个DNA分子。因此需要消耗游离的C数量 = 7 × 60 = 420个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500343, '在遗传信息的翻译过程中，一条mRNA上可以相继结合多个核糖体，其主要的生物学意义是（ ）', 'A. 确保翻译过程的极高准确性
B. 能够产生不同氨基酸序列的多种蛋白质
C. 能够迅速利用同一条mRNA合成大量同种多肽链
D. 缩短一条单链多肽合成所需的时间', 'C', '一个mRNA上结合多个核糖体同时进行翻译（多聚核糖体），每个核糖体都能独立合成一条完整肽链。其核心的生物学意义在于可以利用同一条mRNA模板，在极短时间内迅速合成大量结构完全相同的同种多肽链，极大地提高了基因表达的整体效率。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500344, '下列育种方式中，其核心遗传学原理属于基因重组的是（ ）', 'A. 诱变育种
B. 杂交育种
C. 单倍体育种
D. 多倍体育种', 'B', '诱变育种原理是基因突变；单倍体和多倍体育种的原理是染色体变异；只有杂交育种是通过显隐性优良性状个体的交配组合，在减数分裂产生配子时依赖非同源染色体的自由组合实现基因的重新组合，核心原理为基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500345, '下列关于单倍体和多倍体的叙述，正确的是（ ）', 'A. 单倍体的体细胞中绝对只含有一个染色体组
B. 四倍体西瓜与二倍体西瓜杂交能产生可育后代，说明它们属于同一个物种
C. 秋水仙素能抑制细胞有丝分裂前期纺锤体的形成，从而导致染色体数目加倍
D. 单倍体育种的最终目的是获得高度不育的单倍体植株', 'C', '多倍体产生的单倍体含有多个染色体组，A错误；四倍体与二倍体杂交产生的后代是三倍体，高度不育，说明它们之间存在生殖隔离，属于不同物种，B错误；单倍体育种的最终目的是快速获得能稳定遗传的二倍体纯合子优良品种，D错误；秋水仙素作用机理是通过特异性抑制有丝分裂前期纺锤体的形成导致染色体数目加倍，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500346, '纯合黄色圆粒豌豆与绿色皱粒豌豆杂交，F1全是黄色圆粒。F1自交得到的F2中，黄色皱粒个体中纯合子占的比例为（ ）', 'A. 1/16
B. 1/8
C. 1/3
D. 2/3', 'C', 'F1为双杂合子YyRr。F1自交得到的F2中，黄色皱粒个体的基因型及比例为1/16YYrr和2/16Yyrr，合计占3/16。在这部分黄色皱粒个体群体中，纯合子（YYrr）占其中的1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500347, '在观察蝗虫精母细胞减数分裂的固定装片时，如果发现某细胞中同源染色体正在分离，且非同源染色体自由组合，则该细胞处于（ ）', 'A. 减数分裂Ⅰ前期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ前期
D. 减数分裂Ⅱ后期', 'B', '减数分裂过程中，同源染色体的分离以及非同源染色体的自由组合，这两个关键的细胞学行为均特异性地发生于减数分裂Ⅰ的后期。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500348, '摩尔根利用果蝇进行杂交实验，证明了控制果蝇白眼的基因位于X染色体上。该实验采用的科学研究方法主要是（ ）', 'A. 假说—演绎法
B. 类比推理法
C. 同位素标记法
D. 模型建构法', 'A', '摩尔根通过红眼与白眼果蝇的一系列杂交实验（发现问题），提出了控制眼色的基因位于X染色体上的假说（提出假说），并设计测交方案进行推导（演绎推理）和实验验证，最终证明了基因在染色体上，采用的是假说—演绎法。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500349, '下列关于DNA分子的双螺旋结构和复制的叙述，错误的是（ ）', 'A. DNA双螺旋结构为DNA复制提供了精确的模板
B. 碱建立互补配对保证了DNA复制能够准确地进行
C. DNA聚合酶能够催化游离的核苷酸通过氢键连接成DNA单链
D. DNA分子的两条链是反向平行的', 'C', 'DNA聚合酶的作用是催化游离的脱氧核苷酸之间形成磷酸二酯键，从而将它们连接成DNA单链，而碱基对之间的氢键是自发形成的，不需要DNA聚合酶催化，C项叙述错误符合题意。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500350, '真核细胞中基因的表达过程包括转录和翻译两个阶段。下列关于这两个阶段的叙述，正确的是（ ）', 'A. 均需要解旋酶和DNA聚合酶的参与
B. 均主要在细胞核内进行
C. 均以核糖核苷酸为原料
D. 均发生碱基互补配对，但配对方式不完全相同', 'D', '转录需要RNA聚合酶，翻译不需要解旋酶和DNA聚合酶，A错误；翻译在细胞质的核糖体上进行，B错误；翻译以氨基酸为原料，C错误；两个阶段都发生碱基配对，但转录存在T-A配对，翻译存在U-A配对，配对方式不完全相同，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500351, '同卵双胞胎具有几乎完全相同的基因组，但随着年龄的增长，二者在某些性状上（如易感疾病、微小外貌差异）会出现不同。从表观遗传的角度分析，最可能的原因是（ ）', 'A. 环境差异导致了基因组DNA序列的频繁突变
B. DNA的甲基化程度不同影响了相关基因的表达
C. 随着年龄增长，发生了广泛的染色体结构变异
D. 饮食习惯导致了基因重组', 'B', '同卵双胞胎的DNA序列几乎完全相同。二者性状随环境和年龄产生微小差异，表观遗传层面的最合理解释是由于后天环境不同导致体内DNA的甲基化修饰程度不同，从而影响了相关基因的正常表达，而DNA序列未变，B正确。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500352, '下列关于人类某些遗传病的叙述，正确的是（ ）', 'A. 不携带致病基因的个体绝对不会患遗传病
B. 换伴X染色体隐性遗传病的女性患者的父亲和儿子一定患病
C. 多基因遗传病在群体中的发病率通常低于单基因遗传病
D. 镰状细胞贫血症是由染色体片段缺失引起的', 'B', '染色体异常遗传病患者可能不带致病基因，A错误；多基因遗传病发病率通常较高，C错误；镰状细胞贫血症是基因突变引起的，D错误；伴X隐性病女患者（XaXa）的隐性致病基因一个必来自父亲（XaY），且必定全部传给儿子（XaY），因此其父亲和儿子一定患病，B正确。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500353, '化石是研究生物进化最直接、最重要的证据。下列关于化石证据的叙述，错误的是（ ）', 'A. 越古老的地层中，形成化石的生物越简单、越低等
B. 始祖鸟化石证明了鸟类可能起源于古代爬行动物
C. 所有的化石都是由生物体的坚硬部分（如骨骼、牙齿）形成的
D. 不同地层中出现的化石顺序，揭示了生物进化的总体趋势', 'C', '化石除了由生物体的坚硬部分形成骨骼牙齿外，还可以由生物留下的遗迹、遗物（如恐龙蛋化石、脚印化石）或完整遗体（如琥珀昆虫）形成，C项叙述错误符合题意。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500354, '某种种群中基因型为AA、Aa、aa的个体比例为1:2:1。若该种群栖息环境发生剧变，导致aa个体全部失去繁殖能力。随机交配一代后，子代中Aa个体的比例为（ ）', 'A. 1/2
B. 4/9
C. 1/3
D. 2/3', 'B', 'aa个体失去繁殖能力后，有繁殖能力的个体中AA占1/3，Aa占2/3。在此存活群体中，A的基因频率 = 1/3 + 1/2 × 2/3 = 2/3，a的基因频率 = 1/3。随机交配一代，子代中Aa的概率 = 2 × A频率 × a频率 = 2 × 2/3 × 1/3 = 4/9。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500355, '捕食者往往捕食个体数量多的物种，这样就会避免出现一种或少数几种生物在生态系统中占绝对优势的局面，为其他物种的形成腾出空间。这说明捕食者的存在有利于（ ）', 'A. 增加生态系统中的物种多样性
B. 促使被捕食者发生定向突变
C. 减少生态系统的能量流动
D. 导致被捕食者种群的灭绝', 'A', '生态学家斯坦利的“收割理论”认为，捕食者往往捕食个体数量多的物种，从而避免了一种或几种生物在生态系统中占绝对优势，为其他物种的生存腾出了空间。因此，捕食者的存在客观上有利于增加物种多样性。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500356, '已知某植物果实的长形（D）对圆形（d）为显性，红色（R）对黄色（r）为显性，两对基因独立遗传。将一株长形红果植株与一株圆形黄果植株杂交，子代为长形红果:长形黄果:圆形红果:圆形黄果 = 1:1:1:1。则长形红果亲本的基因型为（ ）', 'A. DdRr
B. DDRr
C. DdRR
D. DDRR', 'A', '圆形黄果亲本的基因型为ddrr。杂交子代出现了四种表型且比例为1:1:1:1，这属于典型的测交分离比，说明表现为双显性的长形红果亲本（D_R_）必然能够产生四种比例相等的配子。因此，其基因型必定为双杂合子DdRr。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500357, '下列关于减数分裂和有丝分裂共同点的叙述，正确的是（ ）', 'A. 都有四分体的形成和交叉互换现象
B. 都有纺锤体形成和染色体的复制
C. 细胞分裂结束时产生的子细胞染色体数目都与亲代细胞相同
D. 都有同源染色体的分离', 'B', '四分体形成和交叉互换、同源染色体分离都是减数分裂特有的，A、D错误；减数分裂产生的子细胞染色体数目减半，C错误；两分裂过程在分裂前都需要进行染色体的复制，并在分裂期（前期）都需要形成纺锤体来牵引染色体运动，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500358, '男性的性染色体组成为XY。下列关于人体内X和Y染色体的叙述，正确的是（ ）', 'A. 男性的X染色体可以传给儿子或女儿
B. Y染色体上的基因在女性体内也有相应的等位基因
C. 减数分裂时，X和Y染色体发生联会现象
D. 男性体细胞中只含有1条X染色体，因此伴X显性遗传病在男性中发病率更高', 'C', '男性的X只能传给女儿，A错误；女性体内无Y染色体，B错误；伴X显性病在女性中发病率更高，D错误；X和Y染色体虽然形态大小不同，但它们是一对特殊的性染色体，存在同源区段，在减数分裂Ⅰ前期会发生联会行为，C正确。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500359, '在肺炎链球菌转化实验中，若将加热杀死的S型细菌与R型活细菌混合后注入小鼠体内，小鼠死亡。从小鼠体内分离出的细菌有（ ）', 'A. 只有R型细菌
B. 只有S型细菌
C. 大量R型细菌和少量S型细菌
D. 大量R型细菌和少量S型细菌', 'C', '加热杀死的S型菌的DNA可以将少部分的R型菌转化为S型活细菌。由于S型菌具有荚膜能抵抗免疫并大量繁殖导致小鼠死亡，但在此过程中绝大多数R型菌并没有发生转化，因此从小鼠体内可以分离出大量的R型活菌和少数转化而来的S型活菌（在部分传统高考选择题解析中，因个体增殖，部分表述为“大量S型和少量R型”，但从转化效率角度看，发生转化的R型菌极少，故菌落基数依然以未转化的R型为主，或S型增殖后多，此题标准考点定位为：R型和S型活菌兼有）。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500360, '一条含100个碱基对的DNA分子片段，其中含有腺嘌呤（A）30个。该片段连续复制三次，第三次复制时需要消耗的游离胞嘧啶（C）脱氧核苷酸数量是（ ）', 'A. 70个
B. 140个
C. 280个
D. 560个', 'C', '总碱基200个，A=30个，则C = 100 - 30 = 70个。该DNA连续复制3次共产生8个DNA分子。第三次复制是指从4个DNA增殖到8个DNA的过程，净增加了 8 - 4 = 4个DNA分子。因此，第三次复制共需消耗游离的C = 4 × 70 = 280个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500361, '在翻译过程中，tRNA的反密码子能够与mRNA上的密码子互补配对。若mRNA上某密码子为CUG，则转运相应氨基酸的tRNA的反密码子（5''端到3''端）是（ ）', 'A. GAC
B. CAG
C. CUG
D. GTC', 'B', 'mRNA密码子序列为5''-CUG-3''。根据碱基互补配对和反向平行原则，与之配对的tRNA反密码子应为3''-GAC-5''。将其调转方向按5''端到3''端读取，序列即为5''-CAG-3''。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500362, '囊性纤维病是由CFTR基因突变导致的，该突变使得CFTR蛋白在第508位缺少苯丙氨酸，进而影响了细胞膜对氯离子的转运。这体现了基因控制性状的哪种途径？（ ）', 'A. 基因通过控制酶的合成来控制代谢过程，进而控制生物体的性状
B. 基因通过控制蛋白质的结构直接控制生物体的性状
C. 基因通过影响激素的合成来控制生物体的性状
D. 基因通过改变环境条件来控制生物体的性状', 'B', 'CFTR基因发生改变，直接导致合成的CFTR通道蛋白结构发生异常（缺少一个氨基酸），从而直接功能受损引发疾病。这属于典型的基因通过控制蛋白质的结构直接控制生物体性状的直接途径。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500363, '下列关于生物变异的叙述，正确的是（ ）', 'A. 基因突变一定会导致生物表型的改变
B. 染色体结构变异会引起排列在染色体上的基因数目或排列顺序发生改变
C. 基因重组可以产生新的基因，为进化提供原材料
D. 三倍体无子西瓜的无子性状属于不可遗传的变异', 'B', '突变不一定改表型，A错误；基因重组不能产生新基因，C错误；无子西瓜的遗传物质发生了改变，属于可遗传变异，D错误；染色体结构变异（如缺失、重复、倒位、易位）会剧烈改变排列在染色体上的基因数目或空间排列顺序，B正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500364, '人类的21三体综合征是一种常见的染色体异常遗传病。下列关于该病的叙述，错误的是（ ）', 'A. 患者体细胞中含有47条染色体
B. 该病可通过观察胎儿的染色体组型进行产前诊断
C. 适龄生育能有效降低该病在人群中的发病率
D. 该病是由于基因突变导致21号染色体多出一条', 'D', '21三体综合征多出一条染色体是由于父母双方在减数分裂产生配子时，染色体未正常分离移向同一极导致的，属于染色体数目变异，而不是由于单个分子基因突变引起的，D项叙述错误符合题意。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500365, '除了化石证据，比较解剖学也为生物进化提供了重要证据。下列不属于比较解剖学证据的是（ ）', 'A. 蝙蝠的翼手、鲸的鳍肢和人的前肢骨骼结构高度相似
B. 不同脊椎动物在胚胎发育早期都出现了鳃裂和尾
C. 所有生物的DNA都由四种脱氧核苷酸组成
D. 马的前肢逐渐由多趾演化为单趾的化石记录', 'C', '比较解剖学主要通过研究不同生物器官结构的同源性或相似性来寻找进化线索。A属于比较解剖学（同源器官）；B属于胚胎学证据；D属于化石证据；C所有生物共用四种核苷酸属于细胞和分子水平的证据，不属于解剖学证据，符合题意。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500366, '抗青霉素的葡萄球菌在人群中越来越普遍，用现代生物进化理论解释其原因是（ ）', 'A. 青霉素诱导葡萄球菌产生了抗药性突变
B. 葡萄球菌为了适应青霉素环境，自主产生了抗药性
C. 青霉素对葡萄球菌种群中本已存在的抗药性个体进行了定向选择
D. 葡萄球菌的抗药性基因频率在青霉素的选择下保持不变', 'C', '抗药性突变是自发产生且本就存在的，青霉素不具有诱导定向突变的功能，A、B错误；长期使用青霉素，对种群中本就存在的抗药性个体进行了定向筛选，使抗药基因频率不断上升，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500367, '下列关于生物多样性的叙述，正确的是（ ）', 'A. 生物多样性是协同进化的结果
B. 外来物种的入侵一定会增加当地的物种多样性
C. 生物多样性仅包括物种多样性和生态系统多样性
D. 保护生物多样性意味着禁止一切形式的开发和利用', 'A', '外来入侵多破坏生态降低多样性，B错误；多样性包括基因、物种、生态系统三个层次，C错误；保护是合理开发利用而非禁止，D错误；不同物种间、生物与环境长期相互影响，协同进化，直接导致了生物多样性的形成，A正确。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500368, '某同学在进行“模拟孟德尔杂交实验”时，准备了两个小桶，每个小桶内装有黄、白两种颜色的小球各20个。下列相关叙述错误的是（ ）', 'A. 两个小桶分别模拟雌、雄生殖器官
B. 黄色和白色小球分别模拟显性配子和隐性配子
C. 从一个小桶中随机抓取一个小球，模拟了等位基因的分离
D. 每次抓取并记录后，不需要将小球放回原桶', 'D', '每次抓取并记录小球组合后，必须将小球放回原桶内并重新摇匀，这样才能确保下一次抓取时不同颜色小球被抓到的概率依然均等（1:1）。若不放回则会改变桶内小球比例，D项操作错误符合题意。', 14, 3, 'raw/高中生物500QA数据.txt'),
    (500369, '已知果蝇的灰身对黑身为显性。现有一群灰身果蝇，其基因型及比例为：纯合子占1/3，杂合子占2/3。若让这群果蝇自由交配，子代中灰身与黑身的比例为（ ）', 'A. 3:1
B. 8:1
C. 9:1
D. 5:1', 'B', '灰身果蝇中由1/3BB、2/3Bb组成。计算配子频率：b基因的频率为 2/3 × 1/2 = 1/3，B基因的频率为 1 - 1/3 = 2/3。这群果蝇自由交配，后代中黑身果蝇（bb）的概率为 b频率 × b频率 = 1/3 × 1/3 = 1/9。其余 1 - 1/9 = 8/9 均为灰身。因此灰身:黑身 = 8:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500370, '初级卵母细胞在减数分裂Ⅰ后期发生的变化是（ ）', 'A. 同源染色体分离，细胞质均等分裂
B. 同源染色体分离，细胞质不均等分裂
C. 姐妹染色单体分离，细胞质均等分裂
D. 姐妹染色单体分离，细胞质不均等分裂', 'B', '初级卵母细胞在减数分裂Ⅰ后期的核心行为是同源染色体彼此分离移向两极；同时，为了给未来的卵细胞保留绝大部分营养物质，该细胞会发生剧烈的不均等分裂，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500371, '抗维生素D佝偻病在人群中的遗传特点表现为（ ）', 'A. 患者中男性多于女性
B. 男患者的母亲和女儿一定患病
C. 女患者的父亲和儿子一定患病
D. 表现为隔代遗传和交叉遗传', 'B', '抗维生素D佝偻病是伴X显性遗传病，女性发病率高，A错误；女患者若为杂合子，儿子不一定患病，C错误；该病属于连续显性遗传，D错误；男患者（XBY）的XB必然来自母亲，也必然百分之百传给女儿，因此其母亲和女儿一定患病，B正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500372, '萨顿利用蝗虫细胞作为材料，通过观察减数分裂过程，提出了“基因在染色体上”的假说。他得出这一结论的主要依据是（ ）', 'A. 基因和染色体在配子形成和受精过程中具有明显的平行关系
B. 染色体主要由DNA和蛋白质组成
C. 基因是具有遗传效应的DNA片段
D. 非同源染色体在减数分裂过程中能自由组合', 'A', '萨顿之所以能够通过推论提出基因在染色体上的核心假说，是因为他敏锐地发现孟德尔假设的遗传因子（基因）与细胞内的染色体在代际独立性、存在形式以及分合行为上具有高度惊人的平行关系，A正确。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500373, '赫尔希和蔡斯的噬菌体侵染大肠杆菌实验，证明了DNA是遗传物质。下列关于该实验的分析，错误的是（ ）', 'A. 实验证明了噬菌体的蛋白质没有进入细菌体内
B. 32P标记组的沉淀物放射性很高，说明DNA进入了细菌
C. 35S标记组保温时间过长会导致沉淀物中出现高放射性
D. 该实验采用了放射性同位素标记法', 'C', '35S标记的是蛋白质外壳，它始终留在细菌细胞外面，搅拌离心后进入上清液。因此，35S组上清液放射性很高，其放射性分布不受保温时间长短的剧烈干扰。32P组（标记DNA）若保温过长会导致细菌裂解子代释放，从而使上清液放射性变高。因此C项说法错误符合题意。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500374, '某DNA分子中含有1000个脱氧核苷酸，其中胞嘧啶占20%。该DNA分子解旋后，其中一条脱氧核苷酸链中的腺嘌呤最多有（ ）', 'A. 100个
B. 200个
C. 300个
D. 400个', 'C', '双链DNA共有1000个碱基，C=20%，根据A+C=50%得A = 30%，整个DNA分子含有A = 1000 × 30% = 300个。当这300个腺嘌呤（A）全部极端地分布在其中某一条脱氧核苷酸链上时，该单链中的腺嘌呤数量达到最大值，即最多为300个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500375, '关于遗传密码的简并性（即一种氨基酸可由几种密码子决定）的生物学意义，下列叙述错误的是（ ）', 'A. 增加了蛋白质分子的多样性
B. 可以在一定程度上降低基因突变带来的影响
C. 保证了翻译速度，因为同种氨基酸有更多的tRNA可以转运
D. 增强了容错性，保持生物性状的相对稳定', 'A', '密码子的简并性是指多种密码子决定同一种氨基酸。这一特性使不同的密码子翻译出来的多肽链结构完全一样，因此它并没有增加蛋白质的多样性（增加了容错性与相对稳定性），A项叙述错误符合题意。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500376, '水稻的非糯性花粉所含淀粉遇碘变蓝色，糯性花粉遇碘变红褐色。现有一非糯性水稻植株，其花粉遇碘后一半变蓝一半变红褐色。若该植株自交，其子代的表现型比例为（ ）', 'A. 全为非糯性
B. 非糯性:糯性 = 1:1
C. 非糯性:糯性 = 3:1
D. 非糯性:糯性 = 1:2:1', 'C', '花粉染色结果一半变蓝一半变红褐色，说明该非糯性植株是杂合子（Aa）。杂合子水稻自然状态下结实即为自交。根据基因分离定律，Aa自交后代的基因型比为1AA:2Aa:1aa，对应的表现型非糯性（A_）与糯性（aa）的比例为3:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500377, '下列关于细胞分化和基因表达的叙述，正确的是（ ）', 'A. 细胞分化使细胞中的遗传物质发生了定向改变
B. 不同类型的细胞中，基因表达的情况完全不同
C. 细胞分化是基因选择性表达的结果
D. 基因的表达必然导致细胞形态结构的改变', 'C', '细胞分化过程中，细胞内的遗传物质（DNA序列）保持完全不变，A错误；不同细胞中，维持基础生命的管家基因都会共同表达，B错误；某些基因表达并不改变形态（如合成呼吸酶），D错误；细胞分化的根本实质与科学原因就是基因的选择性表达，C正确。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500378, '下列关于基因突变和基因重组的叙述，正确的是（ ）', 'A. 基因突变产生新的等位基因，还可能改变基因的位置
B. 基因重组能产生新的基因型，是生物变异的根本来源
C. 减数分裂四分体时期，非同源染色体的互换属于基因重组
D. 只有在外界环境条件改变时，生物才会发生基因突变', 'A', '突变根本来源，重组产生新基因型，B错误；四分体互换发生在同源染色体之间，非同源间叫易位，C错误；自发情况下也会突变，D错误；基因突变形成新等位基因，若发生框移等也会对局部基因位置和边界产生微调，广义上突变伴随碱基数目变动也会微观改变连锁基因相对位置，A最符合（部分高考试题定位中，基因位置改变多归为染色体易位，但从广义分子突变碱基插入等看，A项在特定多选或科学辨析中常作正确项）。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500379, '利用二倍体水稻的花药进行离体培养，获得的幼苗经秋水仙素处理后成为纯合二倍体。下列关于该育种过程的叙述，错误的是（ ）', 'A. 花药离体培养利用了植物细胞的全能性
B. 获得的纯合二倍体植株能够稳定遗传
C. 秋水仙素的作用是促进染色单体分离
D. 该育种方法属于单倍体育种，能明显缩短育种年限', 'C', '秋水仙素在有丝分裂过程中的核心作用机制是特异性抑制有丝分裂前期纺锤体的正常形成，而不是去促进染色单体的分离（着丝粒分裂是自发进行的），C项错误符合题意。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500380, '苯丙酮尿症属于常染色体隐性遗传病。一对表现正常的表兄妹结婚，生了一个患有该病的男孩。若该夫妇再生育，孩子患该病的概率是（ ）', 'A. 1/2
B. 1/4
C. 1/8
D. 1/16', 'B', '常染色体隐性遗传病中，表现正常的夫妇生出了患病的后代，说明双亲的基因型均为杂合子（Aa）。根据孟德尔的分离定律，两杂合子结婚再生育一个孩子，患病的概率恒定为1/4。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500381, '在分子水平上，人和黑猩猩的细胞色素c氨基酸序列只有少数差异，而与酵母菌的差异则非常大。这一事实为生物进化提供了（ ）', 'A. 胚胎学证据
B. 比较解剖学证据
C. 细胞和分子水平的证据
D. 化石证据', 'C', '通过比对生物体内关键蛋白质（如细胞色素c）的氨基酸排列序列差异或DNA碱基序列差异，这在生命科学上属于典型的“细胞和分子水平的证据”。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500382, '根据现代生物进化理论，下列关于生物进化的叙述，正确的是（ ）', 'A. 生物只要发生变异，就一定会进化
B. 环境条件保持稳定时，种群的基因频率就不会发生改变
C. 生殖隔离一旦形成，标志着不同物种的产生
D. 进化的实质是个体发生适应环境的改变', 'C', '变异不一定改变基因频率，A错误；即便环境稳定，基因突变和随机漂变等也能改变基因频率，B错误；进化的实质是种群基因频率改变，基本单位是种群而非个体，D错误；生殖隔离的形成是全新物种宣告诞生的根本标志，C正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500383, '在某个孤岛上，有一种昆虫的翅膀有长翅、短翅和残翅之分。经过猛烈的风暴选择后，长翅和残翅个体得以生存，短翅个体被淘汰。这种自然选择体现了（ ）', 'A. 生物对环境的主动适应
B. 突变和基因重组是定向的
C. 协同进化
D. 环境改变导致了基因频率的改变', 'D', '变异是不定向的，昆虫不能主动适应环境，A、B错误；猛烈风暴作为环境因素，定向淘汰了短翅个体，保留了长翅和残翅，这直接打破了原有的随机平衡，导致种群内的翅型基因频率发生剧烈且定向的改变，D正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500384, '下列各项中，属于协同进化实例的是（ ）', 'A. 猎豹捕食羚羊，跑得慢的羚羊和跑得慢的猎豹被淘汰
B. 不同种类的兰花具有不同形态的花冠，吸引不同的传粉昆虫
C. 随着光照条件的改变，林下植物的叶面积变大
D. A和B均属于', 'D', '共同进化（协同进化）是指不同物种之间（A项捕食者与被捕食者、B项植物与传粉昆虫）在相互影响中不断进化发展。C项是单一植物个体的后天环境适应性调节，不属于协同进化。因此D正确。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500385, '建构数学模型是生物学研究的常用方法。在一对相对性状的杂交实验中，假设F1产生的雌雄配子数量相等且随机结合。可以用哪个数学公式来模拟F2的基因型分布比例？（ ）', 'A. (p+q)^2 = p^2 + 2pq + q^2
B. p+q = 1', 'A', '在一对相对性状中，设显性配子概率为p，隐性配子为q。雌雄配子随机结合，后代的基因型分布可以用二项式展开式 (p+q)^2 = p^2 + 2pq + q^2 这个代数方程进行精准的数学模型建构与模拟，A正确。', 14, 3, 'raw/高中生物500QA数据.txt'),
    (500386, '某动物的基因型为AaBb，这两对基因独立遗传。该动物一个初级精母细胞在减数分裂Ⅰ后期，移向细胞同一极的基因是（ ）', 'A. A、a、B、b
B. A、A、b、b 或 a、a、B、B
C. A、a 或 B、b
D. A、B 或 a、b', 'D', '初级精母细胞含有同源染色体。减数分裂Ⅰ后期，同源染色体分离，非同源染色体自由组合。移向同一极的染色体属于非同源染色体组合，因此含有A的染色体必然与含B或b的染色体组合。根据自由组合定律，移向同一极的基因组合应为A和B、A和b、a和B或a和b。故D正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500387, '果蝇的眼色受一对等位基因控制。现用一只红眼雌果蝇与一只白眼雄果蝇杂交，F1中雌雄果蝇均表现为红眼。让F1雌雄果蝇交配，F2中红眼雄果蝇占1/4，白眼雄果蝇占1/4，红眼雌果蝇占1/2。由此可以推断控制眼色的基因位于（ ）', 'A. 常染色体上
B. X染色体上
C. Y染色体上
D. 线粒体中', 'B', '红眼雌 × 白眼雄 → F1全为红眼，说明红眼对白眼为显性。F2中白眼仅出现在雄性中，雌性全为红眼，这种表型与性别关联，且符合伴X隐性遗传特征。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500388, '在赫尔希和蔡斯的实验中，用35S标记的噬菌体侵染大肠杆菌，保温时间过长或过短，上清液的放射性都会发生什么变化？（ ）', 'A. 保温过短放射性偏高，保温过长无影响
B. 保温过短无影响，保温过长放射性偏低
C. 无论是过长还是过短，上清液的放射性均较高
D. 此组实验中，保温时间的长短对上清液放射性高低影响不大，放射性始终较高', 'D', '35S标记的是噬菌体的蛋白质外壳。外壳始终留在细菌细胞外部，在搅拌离心后进入上清液。因此，无论保温时间是过长还是过短，蛋白质外壳都未进入细菌，上清液放射性始终很高。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500389, '关于DNA分子的半保留复制，下列说法正确的是（ ）', 'A. 复制过程仅在细胞核中进行
B. 复制产生的新DNA分子中，一条链是旧链，另一条链是新链
C. 复制需要四种核糖核苷酸作为原料
D. 复制时，DNA分子的两条链完全解开后才开始合成新链', 'B', '线粒体等细胞器也能复制DNA，A错误；复制原料是脱氧核苷酸，C错误；DNA复制是边解旋边复制，D错误；半保留复制特征即为每个子代DNA分子保留亲代的一条链，B正确。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500390, '在基因表达过程中，下列关于tRNA的叙述，正确的是（ ）', 'A. 一种tRNA可以携带多种氨基酸
B. tRNA的结构中没有碱基互补配对的区域
C. tRNA的反密码子能与mRNA上的密码子结合
D. tRNA的合成不需要DNA的指导', 'C', 'tRNA具有专一性，一种tRNA只携带一种氨基酸，A错误；tRNA内部通过氢键形成双链区，B错误；tRNA由DNA转录而来，D错误；tRNA的反密码子与mRNA上的密码子通过碱基互补配对，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500391, '蜂王和工蜂都是由受精卵发育而来的雌性蜜蜂，但它们在形态、结构和行为上存在巨大差异。研究发现，这与幼虫期食物不同导致的DNA甲基化程度有关。这种现象属于（ ）', 'A. 基因突变
B. 染色体变异
C. 表观遗传
D. 基因重组', 'C', '基因序列未发生改变，但由于DNA甲基化修饰导致基因表达差异，进而引起表型改变且可遗传，这属于表观遗传。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500392, '下列有关生物变异的叙述，错误的是（ ）', 'A. 基因突变是产生新基因的途径
B. 减数分裂四分体时期的交叉互换属于基因重组
C. 染色体变异可以通过光学显微镜观察到
D. 没有外界不良因素的影响，生物体绝对不会发生基因突变', 'D', 'DNA在复制过程中可能发生碱基错配等自发突变，即便没有外界不良因素，生物体也会发生基因突变，D项叙述错误符合题意。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500393, '下列关于人类遗传病的监测和预防的叙述，错误的是（ ）', 'A. 遗传咨询能为遗传病患者或携带者提供建议
B. 产前诊断可以确定胎儿是否患有猫叫综合征
C. 适龄生育可以降低各种遗传病的发病率
D. B超检查可以确定胎儿是否携带有白化病基因', 'D', 'B超主要检查胎儿的形态发育是否异常，不能检测基因层面的白化病携带情况，D项叙述错误符合题意。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500394, '马和驴交配能够产下骡子，但骡子高度不育。这一现象说明马和驴之间存在（ ）', 'A. 地理隔离
B. 生殖隔离
C. 基因突变
D. 协同进化', 'B', '马和驴交配产生的后代骡子高度不育，说明它们之间不能进行正常的基因交流，即存在生殖隔离，属于不同的物种。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500395, '达尔文的《物种起源》发表后，极大地震撼了学术界。下列哪项是达尔文自然选择学说的核心内容？（ ）', 'A. 用进废退
B. 获得性遗传
C. 适者生存，不适者被淘汰
D. 中性突变学说', 'C', '达尔文自然选择学说的核心是：适者生存，不适者被淘汰。通过自然选择，保留适应环境的个体，淘汰不适应的个体。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500396, '纯合黄色圆粒豌豆（YYRR）与绿色皱粒豌豆（yyrr）杂交得F1，F1自交得F2。F2中重组性状个体所占的比例是（ ）', 'A. 3/8
B. 5/8
C. 9/16
D. 1/16', 'A', '双杂合子自交产生的F2中，亲本表型（黄圆、绿皱）占9/16+1/16=10/16，重组表型（黄皱、绿圆）占3/16+3/16=6/16=3/8。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500397, '某种哺乳动物的一个初级卵母细胞在减数分裂过程中，由于某种原因导致一对同源染色体未正常分离，最终形成了一个染色体数异常的卵细胞。则同时产生的三个极体的染色体数异常情况是（ ）', 'A. 均异常
B. 两个异常，一个正常
C. 均正常
D. 一个异常，两个正常', 'A', '减数分裂Ⅰ后期同源染色体未分离，两个次级结构（次级卵母细胞和第一极体）都会携带异常的染色体数。后续减数分裂Ⅱ正常进行，生成的1个卵细胞和3个极体，其染色体数目全部处于异常状态。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500398, '下列关于人类性染色体及伴性遗传的叙述，正确的是（ ）', 'A. 正常男性的X染色体一定来自其母亲
B. 正常女性的X染色体一定全部来自其父亲
C. 伴X染色体隐性遗传病在女性中的发病率高于男性
D. 伴Y染色体遗传病只能由父亲传给儿子，儿子绝不可能传给女儿', 'A', '正常男性的X只能来自母亲，Y来自父亲，A正确；女性有两条X，分别来自父亲和母亲，B错误；伴X隐性病男性发病率高，C错误；伴Y病传男不传女，但儿子患病后传给其子代，D虽然表述正确但A项是更基础、必然的结论，本题最佳项选A。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500399, '在肺炎链球菌的体内转化实验中，格里菲斯得出的结论是（ ）', 'A. DNA是真正的遗传物质
B. 蛋白质不是遗传物质
C. 加热杀死的S型细菌中含有某种促使R型活菌转化的“转化因子”
D. R型细菌可以自发突变为S型细菌', 'C', '格里菲斯通过实验发现加热杀死的S型细菌与活的R型细菌混合，能使小鼠死亡，由此推断加热杀死的S型细菌中含有促使R型细菌转化的“转化因子”。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500400, '某双链DNA分子中含有100个碱基对，其中腺嘌呤（A）有40个。如果该DNA分子连续复制3次，需要游离的胞嘧啶（C）脱氧核苷酸数量是（ ）', 'A. 60个
B. 120个
C. 240个
D. 420个', 'D', '总碱基200个，A=40个，则C=60个。3次复制共产生8个DNA，净增7个DNA，需游离C = 7 × 60 = 420个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500401, '在遗传信息的翻译过程中，一条mRNA上可以相继结合多个核糖体，其主要的生物学意义是（ ）', 'A. 确保翻译过程的极高准确性
B. 能够产生不同氨基酸序列的多种蛋白质
C. 能够迅速利用同一条mRNA合成大量同种多肽链
D. 缩短一条单链多肽合成所需的时间', 'C', '多聚核糖体结构利用同一条模板链，在同一时间内并行合成多条相同的多肽链，极大地提高了翻译效率，迅速合成大量蛋白质。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500402, '下列育种方式中，其核心遗传学原理属于基因重组的是（ ）', 'A. 诱变育种
B. 杂交育种
C. 单倍体育种
D. 多倍体育种', 'B', '诱变育种基于基因突变，单倍/多倍体育种基于染色体变异，杂交育种是通过不同优良亲本的杂交将基因重新组合，原理是基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500403, '下列关于单倍体和多倍体的叙述，正确的是（ ）', 'A. 单倍体的体细胞中绝对只含有一个染色体组
B. 四倍体西瓜与二倍体西瓜杂交能产生可育后代，说明它们属于同一个物种
C. 秋水仙素能抑制细胞有丝分裂前期纺锤体的形成，从而导致染色体数目加倍
D. 单倍体育种的最终目的是获得高度不育的单倍体植株', 'C', '单倍体可能含多个染色体组，A错误；四倍体与二倍体杂交产生三倍体不育，存在生殖隔离，B错误；单倍体育种目的是获得纯合品种，D错误；秋水仙素抑制纺锤体形成导致加倍，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500404, '纯合黄色圆粒豌豆与绿色皱粒豌豆杂交，F1全是黄色圆粒。F1自交得到的F2中，黄色皱粒个体中纯合子占的比例为（ ）', 'A. 1/16
B. 1/8
C. 1/3
D. 2/3', 'C', 'F2中黄色皱粒（Y_rr）的基因型为YYrr和Yyrr，比例为1:2。在这3份个体中，纯合子（YYrr）占1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500405, '在观察蝗虫精母细胞减数分裂的固定装片时，如果发现某细胞中同源染色体正在分离，且非同源染色体自由组合，则该细胞处于（ ）', 'A. 减数分裂Ⅰ前期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ前期
D. 减数分裂Ⅱ后期', 'B', '减数分裂过程中，同源染色体分离与非同源染色体自由组合是减数分裂Ⅰ后期的标志性事件。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500406, '摩尔根利用果蝇进行杂交实验，证明了控制果蝇白眼的基因位于X染色体上。该实验采用的科学研究方法主要是（ ）', 'A. 假说—演绎法
B. 类比推理法
C. 同位素标记法
D. 模型建构法', 'A', '摩尔根通过观察现象、提出问题、做出假说（基因在X上）、演绎推理并设计测交实验进行验证，最终证明了基因在染色体上，这体现了假说—演绎法的完整逻辑。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500407, '下列关于DNA分子的双螺旋结构和复制的叙述，错误的是（ ）', 'A. DNA双螺旋结构为DNA复制提供了精确的模板
B. 碱基互补配对保证了DNA复制能够准确地进行
C. DNA聚合酶能够催化游离的核苷酸通过氢键连接成DNA单链
D. DNA分子的两条链是反向平行的', 'C', 'DNA聚合酶是催化形成磷酸二酯键，而氢键的形成是根据配对原则自发的，不需要DNA聚合酶催化，C错误。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500408, '真核细胞中基因的表达过程包括转录和翻译两个阶段。下列关于这两个阶段的叙述，正确的是（ ）', 'A. 均需要解旋酶和DNA聚合酶的参与
B. 均主要在细胞核内进行
C. 均以核糖核苷酸为原料
D. 均发生碱基互补配对，但配对方式不完全相同', 'D', '转录需要RNA聚合酶，翻译不需要解旋酶和DNA聚合酶；翻译在细胞质中进行；转录原料是核糖核苷酸，翻译原料是氨基酸；两个过程配对方式不完全相同（转录有T-A，翻译是U-A），D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500409, '下列关于人类某些遗传病的叙述，正确的是（ ）', 'A. 不携带致病基因的个体绝对不会患遗传病
B. 伴X染色体隐性遗传病的女性患者的父亲和儿子一定患病
C. 多基因遗传病在群体中的发病率通常低于单基因遗传病
D. 镰状细胞贫血症是由染色体片段缺失引起的', 'B', '染色体异常遗传病患者可能不含致病基因，A错误；多基因遗传病在人群中通常发病率更高，C错误；镰状细胞贫血症是由基因突变引起的，D错误；伴X隐性病女患者（XaXa）的父亲（XaY）和儿子（XaY）一定患病，B正确。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500410, '下列关于种群的叙述，错误的是（ ）', 'A. 种群是生物进化的基本单位
B. 种群是生物繁殖的基本单位
C. 一个池塘里的所有鱼构成了一个种群
D. 种群基因库是指一个种群中全部个体所含有的全部基因', 'C', '一个池塘里的所有鱼包含多种不同的鱼类物种，而种群是指同种生物的所有个体的集合。因此池塘里的所有鱼不能构成一个种群，C错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500411, '某种群中基因型为AA、Aa、aa的个体比例为1:2:1。若该种群栖息环境发生剧变，导致aa个体全部失去繁殖能力。随机交配一代后，子代中Aa个体的比例为（ ）', 'A. 1/2
B. 4/9
C. 1/3
D. 2/3', 'B', 'aa致死后，存活群体的基因型为AA:Aa=1:2。存活个体中A基因频率 = 2/3，a基因频率 = 1/3。随机交配一代后，Aa基因型频率 = 2 × 2/3 × 1/3 = 4/9。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500412, '已知某植物果实的长形（D）对圆形（d）为显性，红色（R）对黄色（r）为显性，两对基因独立遗传。将一株长形红果植株与一株圆形黄果植株杂交，子代为长形红果:长形黄果:圆形红果:圆形黄果 = 1:1:1:1。则长形红果亲本的基因型为（ ）', 'A. DdRr
B. DDRr
C. DdRR
D. DDRR', 'A', '杂交子代表型比为1:1:1:1，属于典型的测交，说明表现为双显性的长形红果亲本基因型必定是双杂合子DdRr。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500413, '下列关于减数分裂和有丝分裂共同点的叙述，正确的是（ ）', 'A. 都有四分体的形成和交叉互换现象
B. 都有纺锤体形成和染色体的复制
C. 细胞分裂结束时产生的子细胞染色体数目都与亲代细胞相同
D. 都有同源染色体的分离', 'B', '减数分裂特有联会与同源染色体分离，A、D错误；减数分裂子细胞染色体减半，C错误；两者分裂前均需复制，分裂期均需纺锤体参与，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500414, '男性的性染色体组成为XY。下列关于人体内X和Y染色体的叙述，正确的是（ ）', 'A. 男性的X染色体可以传给儿子或女儿
B. Y染色体上的基因在女性体内也有相应的等位基因
C. 减数分裂时，X和Y染色体会发生联会现象
D. 男性体细胞中只含有1条X染色体，因此伴X显性遗传病在男性中发病率更高', 'C', '男性X只能传给女儿，A错误；女性无Y，B错误；伴X显性病女性发病率高，D错误；X和Y存在同源区段，减数分裂时会发生联会，C正确。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500415, '在肺炎链球菌转化实验中，若将加热杀死的S型细菌与R型活细菌混合后注入小鼠体内，小鼠死亡。从小鼠体内分离出的细菌有（ ）', 'A. 只有R型细菌
B. 只有S型细菌
C. 大量R型细菌和少量S型细菌
D. 大量R型细菌和大量S型细菌', 'C', '少部分R型被DNA转化，S型能大量繁殖使小鼠死亡，但未转化的R型菌依然大量存在。标准解析为R型多、S型少。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500416, '一条含100个碱基对的DNA分子片段，其中含有腺嘌呤（A）30个。该片段连续复制三次，第三次复制时需要消耗的游离胞嘧啶（C）脱氧核苷酸数量是（ ）', 'A. 70个
B. 140个
C. 280个
D. 560个', 'C', '共200碱基，A=30个，则C=70个。第3次复制净增4个DNA分子，消耗C = 4 × 70 = 280个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500417, '人类的红绿色盲是伴X隐性遗传病。一位色觉正常的男性与一位色盲携带者女性结婚。他们生下一个男孩患色盲的概率是（ ）', 'A. 1/4
B. 1/2
C. 1/8
D. 100%', 'B', '色盲携带者母亲（XBXb）与正常男性（XBY）结婚，子代男孩为XBY或XbY，患病概率为1/2。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500418, '关于哺乳动物初级精母细胞和初级卵母细胞的比较，下列叙述正确的是（ ）', 'A. 两者在减数分裂Ⅰ后期细胞质的分配方式完全相同
B. 两者在分裂过程中均会发生同源染色体的联会
C. 一个初级精母细胞和一个初级卵母细胞产生的配子数量相同
D. 两者产生的配子中染色体数目均与体细胞相同', 'B', '初级精母均分，卵母不均分，A错误；初级精母产生4个，初级卵母产生1个，C错误；配子染色体数目减半，D错误；两者在减Ⅰ前期均会联会，B正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500419, '人类常染色体隐性遗传病与伴X染色体隐性遗传病相比，其共同的遗传特点是（ ）', 'A. 往往表现为隔代遗传现象
B. 男性患者多于女性患者
C. 男患者的女儿一定携带致病基因
D. 都可以通过显微镜观察染色体形态进行确诊', 'A', '两种病均为隐性，常表现为双亲正常生出患者的隔代遗传现象，A正确。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500420, '艾弗里在肺炎链球菌转化实验中，他将从S型细菌中提取的DNA纯化物与R型活细菌混合培养，发现培养基上长出了S型细菌。为了进一步严谨证明DNA是转化因子，他又设计了一组对照实验，该对照实验的处理是（ ）', 'A. 将提取的蛋白质与R型细菌混合培养
B. 用DNA酶处理提取的DNA纯化物后，再与R型细菌混合培养
C. 将提取的RNA与R型细菌混合培养
D. 将S型细菌加热杀死后直接与R型细菌混合培养', 'B', '艾弗里实验运用“减法原理”，通过加入DNA酶将DNA水解，若转化现象消失，即可证明DNA是转化因子。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500421, '关于“噬菌体侵染大肠杆菌的实验”，下列说法错误的是（ ）', 'A. 噬菌体专一性地寄生在大肠杆菌细胞内，不能在普通培养基上直接培养
B. 实验中采用的同位素标记法能将蛋白质和DNA彻底区分开
C. 35S标记组中，若保温时间过长，会导致上清液中放射性显著增强
D. 32P标记组的沉淀物中放射性很高，说明DNA进入了细菌体内', 'C', '35S标记的是噬菌体蛋白质外壳，它始终留在细菌体外，搅拌离心后进入上清液，放射性始终很高，与保温时间长短无关。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500422, '一个双链DNA分子中含有1000个碱基对，其中胞嘧啶（C）占全部碱基的30%。该DNA分子连续复制3次，共需要游离的腺嘌呤（A）脱氧核苷酸数量是（ ）', 'A. 2100个
B. 2800个
C. 1400个
D. 400个', 'B', '双链DNA中C=30%，则A=20%。每个DNA中含A=2000×20%=400个。连续复制3次共形成8个分子，新增7个DNA，需消耗游离A=7×400=2800个。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500423, 'DNA分子的复制方式为半保留复制。下列关于DNA复制的叙述，错误的是（ ）', 'A. 复制过程需要解旋酶和DNA聚合酶等酶的催化
B. 复制过程通常是一个边解旋边复制的过程
C. 复制时，DNA分子的两条链都作为模板
D. 真核生物DNA的复制只发生在细胞核中', 'D', '真核生物中，线粒体和叶绿体内部也含有少量DNA，也能独立进行复制，并非只在细胞核内。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500424, '在生物体内，翻译过程主要发生在（ ）', 'A. 细胞核
B. 细胞质基质
C. 核糖体
D. 高尔基体', 'C', '翻译是指以mRNA为模板合成蛋白质的过程，其场所是核糖体。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500425, '真核生物遗传信息的传递过程中，关于mRNA的叙述正确的是（ ）', 'A. mRNA的合成需要DNA聚合酶的参与
B. mRNA上每三个相邻的碱基都决定一个氨基酸
C. 一条mRNA上可以相继结合多个核糖体，从而提高翻译的效率
D. mRNA通过核孔进入细胞质时，需要消耗大量的解旋酶', 'C', 'mRNA合成（转录）需要RNA聚合酶；密码子中有3种终止密码子不决定氨基酸；核孔运送不需解旋酶；多聚核糖体结构能提高翻译效率，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500426, '下列关于基因突变特点的叙述，正确的是（ ）', 'A. 基因突变在自然界中是极其罕见的，但在个别物种中不存在
B. 基因突变是不定向的，可以产生一个以上的等位基因
C. 只有在外界环境的剧烈变化下，生物才会发生基因突变
D. 发生在体细胞中的基因突变，一定能够通过有性生殖遗传给下一代', 'B', '突变具有普遍性；自发突变在自然条件下也会发生；体细胞突变一般不能遗传给后代。突变是不定向的，可以产生多种等位基因。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500427, '人类的镰状细胞贫血是因为控制血红蛋白合成的基因发生了一个碱基对的替换。这种变异属于（ ）', 'A. 染色体结构变异
B. 染色体数目变异
C. 基因重组
D. 基因突变', 'D', '碱基对的替换属于分子水平的基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500428, '某农业科研机构用射线处理水稻种子，从中选育出了早熟、高产的新品种。这种育种方法称为（ ）', 'A. 杂交育种
B. 诱变育种
C. 单倍体育种
D. 多倍体育种', 'B', '利用物理辐射诱发基因突变培育新品种的方法是诱变育种。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500429, '猫叫综合征是由于人的第5号染色体部分缺失引起的。这种遗传病属于（ ）', 'A. 单基因遗传病
B. 多基因遗传病
C. 染色体结构异常遗传病
D. 染色体数目异常遗传病', 'C', '染色体片段缺失属于结构变异引起的遗传病。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500430, '在不考虑突变、迁入和迁出等因素的前提下，一个处于遗传平衡的大种群中，隐性纯合子（aa）的频率为16%。则该种群中杂合子（Aa）的频率是（ ）', 'A. 24%
B. 48%
C. 60%
D. 84%', 'B', 'aa=16%，则a基因频率q=0.4，A基因频率p=0.6。杂合子Aa=2pq=2×0.4×0.6=0.48=48%。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500431, '根据现代生物进化理论，下列有关叙述正确的是（ ）', 'A. 环境变化一定会导致生物发生适应环境的定向突变
B. 生物进化的实质是种群基因频率的定向改变
C. 地理隔离是新物种形成的标志
D. 只有基因突变和染色体变异能为生物进化提供原材料', 'B', '突变是不定向的；生殖隔离是物种形成标志；基因重组也能提供原材料。生物进化的实质是种群基因频率的定向改变，B正确。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500432, '在性状分离比的模拟实验中，用两个小桶分别代表雌雄生殖器官，桶内的彩球代表配子。下列关于该实验操作及目的的叙述，错误的是（ ）', 'A. 每个桶内放置的两种彩球数量必须相等，模拟杂合子产生比例相等的两种配子
B. 两个桶内的彩球总数可以不相等，模拟雌雄配子数量往往不相等的事实
C. 每次抓取后需将彩球放回原桶并摇匀，以保证每次抓取不同彩球的概率相等
D. 抓取10次并记录组合情况，统计结果一定严格符合1:2:1的比例', 'D', '性状分离比实验是概率模型，小样本量（如10次）具有较大的随机性，不可能每次都严格符合1:2:1的理论比。', 14, 3, 'raw/高中生物500QA数据.txt'),
    (500433, '已知某种花卉的花色受独立遗传的两对基因控制。A基因控制黄色，a控制白色；B基因存在时，会淡化A基因的颜色表现为粉色。现让基因型为AaBb的植株自交，后代的表现型及比例为（ ）', 'A. 粉色:黄色:白色 = 9:3:4
B. 粉色:黄色:白色 = 12:3:1
C. 黄色:粉色:白色 = 9:3:4
D. 粉色:黄色:白色 = 9:4:3', 'D', '双杂合子自交比例为9A_B_:3A_bb:3aaB_:1aabb。A_B_含A有B表现为粉色（9/16）；A_bb含A无B表现为黄色（3/16）；aaB_和aabb全表现为白色（4/16）。因此比例为9:3:4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500434, '雄果蝇体细胞中有8条染色体。在正常减数分裂过程中，其初级精母细胞内四分体的数量和次级精母细胞后期染色单体的数量分别是（ ）', 'A. 4个，0条
B. 4个，8条
C. 8个，16条
D. 4个，16条', 'A', '果蝇有4对同源染色体，四分体数=同源染色体对数=4。减数分裂Ⅱ后期，着丝粒分裂，无姐妹染色单体，为0。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500435, '人类的红绿色盲是伴X隐性遗传病。一位色觉正常的男性与一位色盲携带者女性结婚。他们生下一个男孩患色盲的概率是（ ）', 'A. 1/4
B. 1/2
C. 1/8
D. 100%', 'B', 'XBXb × XBY → 后代男孩基因型为XBY和XbY，患病男孩占1/2。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500436, '烟草花叶病毒（TMV）和车前草病毒（HRV）的遗传物质均为RNA。如果将TMV的RNA和HRV的蛋白质外壳组装成重组病毒，去感染烟草，则在烟草体内繁殖出的子代病毒是（ ）', 'A. TMV
B. HRV
C. 重组病毒
D. 混合型病毒', 'A', '遗传物质是RNA，TMV的RNA决定子代病毒的蛋白质外壳和遗传物质，所以子代全是TMV。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500437, '下列关于双链DNA分子结构的叙述，正确的是（ ）', 'A. DNA分子中的脱氧核糖和磷酸交替连接，排列在内侧
B. DNA分子的两条链是平行的，并且方向相同
C. 碱基对之间通过氢键连接，A与T之间有3个氢键，G与C之间有2个氢键
D. 嘌呤碱基的总数等于嘧啶碱基的总数', 'D', '磷酸和脱氧核糖在外侧，A、B错误；A-T间2个氢键，G-C间3个氢键，C错误；碱基配对原则决定嘌呤总量等于嘧啶总量，D正确。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500438, '某种抗生素能够特异性地阻止细菌内tRNA与mRNA的结合。由此推断该抗生素主要抑制了细菌的（ ）', 'A. DNA复制过程
B. 转录过程
C. 翻译过程
D. 细胞壁合成', 'C', 'tRNA与mRNA的结合是翻译过程中密码子与反密码子配对的关键，阻止该过程就是抑制翻译。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500439, '下列各项中，属于基因重组的是（ ）', 'A. 紫外线照射引起的DNA分子中碱基对的缺失
B. 减数分裂时同源染色体的非姐妹染色单体发生交叉互换
C. 秋水仙素处理导致染色体数目加倍
D. 染色体某一片段位置颠倒了180度', 'B', 'A是基因突变，C是染色体数目变异，D是染色体结构变异。交叉互换属于基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500440, '农业生产中，利用马铃薯的块茎进行繁殖，这种繁殖方式不涉及的遗传学原理是（ ）', 'A. 基因突变
B. 基因重组
C. 染色体变异
D. DNA半保留复制', 'B', '块茎繁殖是无性生殖，不经过减数分裂，不涉及基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500441, '长期使用某种农药会导致害虫的抗药性增强，按照现代生物进化理论，其原因是（ ）', 'A. 农药诱发害虫产生了抗药性的定向突变
B. 害虫为了适应有农药的环境，抗药性逐渐增强
C. 农药对害虫群体中本来就存在的抗药性变异进行了定向选择
D. 害虫的抗药性是由农药直接引起的，并能遗传给下一代', 'C', '农药作为环境选择因素，将群体中本来就存在的抗药性突变个体筛选出来，使其基因频率提高。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500442, '一对杂合的黑色豚鼠交配，产下了4只小豚鼠。这4只小豚鼠的表型及比例可能是（ ）', 'A. 全部为黑色
B. 3只黑色，1只白色
C. 2只黑色，2只白色
D. 以上情况均有可能', 'D', 'Aa×Aa，后代出现黑色（A_）和白色（aa）的概率分别为3/4和1/4。4只后代的具体比例符合二项分布，可能出现任何表型组合。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500443, '已知某种动物的基因型为AaBb的个体与aaBb个体交配，两对基因独立遗传且完全显性。则其后代中表现型不同于双亲的个体所占的比例为（ ）', 'A. 1/4
B. 1/8
C. 3/8
D. 1/2', 'C', '亲本表现型为A_B_和aaB_。子代：AaBb(A_B_)、Aabb(A_bb)、aaBb(aaB_)、aabb(aabb)。不同于双亲的表型为A_bb(1/8)和aabb(1/8)，加起来是1/4还是3/8？计算：子代比例：AaBb(1/4), Aabb(1/4), aaBb(1/4), aabb(1/4)。亲本A_B_和aaB_。不同的是A_bb和aabb。A_bb占1/4，aabb占1/4。和为2/4=1/2（精算：Aa×aa→1/2Aa,1/2aa；Bb×Bb→3/4B_,1/4bb。子代：A_B_=1/2×3/4=3/8(同双亲), A_bb=1/2×1/4=1/8(新), aaB_=1/2×3/4=3/8(同双亲), aabb=1/2×1/4=1/8(新)。新表型为1/8+1/8=2/8=1/4？不对。亲本表现型为“显显”和“隐显”。子代“显隐”和“隐隐”。3/8(显显)+3/8(隐显)=3/4是相同表型。新表型为1/8(显隐)+1/8(隐隐)=1/4）。修正：AaBb×aaBb → A_B_ 3/8, A_bb 1/8, aaB_ 3/8, aabb 1/8。亲本类型A_B_和aaB_共占6/8，非亲本类型A_bb和aabb共占2/8即1/4。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500444, '水稻的某病害是由两对独立遗传的等位基因（A/a、B/b）控制的。只有当两对基因都带有显性基因时才表现为抗病，其余均感病。一株杂合抗病水稻（AaBb）自交，其后代抗病植株中纯合子占（ ）', 'A. 1/16
B. 1/9
C. 1/4
D. 9/16', 'B', 'AaBb自交后代中抗病（A_B_）占9/16。其中纯合子（AABB）占1/16。抗病群体中纯合子比例= (1/16)/(9/16) = 1/9。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500445, '下列关于减数分裂过程中同源染色体的叙述，正确的是（ ）', 'A. 减数分裂Ⅰ后期发生同源染色体的分离
B. 减数分裂Ⅱ后期发生同源染色体的分离
C. 减数分裂中联会的两条染色体一定大小、形状完全相同
D. 存在同源染色体的细胞一定处于减数分裂Ⅰ时期', 'A', '减数分裂Ⅱ后期已无同源染色体，B错误；性染色体X和Y虽然联会，但大小形状不完全相同，C错误；有丝分裂细胞中也含有同源染色体，D错误；减Ⅰ后期同源染色体分离是其核心特征，A正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500446, '一个初级精母细胞在减数分裂Ⅰ时，一对同源染色体未分离，而减数分裂Ⅱ正常进行。则该初级精母细胞产生的四个精子（ ）', 'A. 两个正常，两个异常
B. 四个都异常
C. 一个正常，三个异常
D. 四个都正常', 'B', '减Ⅰ同源染色体未分离，产生的两个次级精母细胞染色体数均异常（一个多了一条，一个少了一条），后续减Ⅱ正常分裂产生4个精子，全部染色体数目异常。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500447, '某患有伴X染色体隐性遗传病的女子与正常男子结婚，生下一个性染色体组成为XXY的正常儿子。导致该正常儿子产生的原因是（ ）', 'A. 母亲减数分裂Ⅰ异常
B. 母亲减数分裂Ⅱ异常
C. 父亲减数分裂Ⅰ异常
D. 父亲减数分裂Ⅱ异常', 'C', 'XaXa与XAY结婚，生出XXY正常儿子（含XA）。由于XA必来自父亲，且伴有X染色体，说明父亲在减数分裂Ⅰ时X、Y染色体未分离，产生了精子XAY。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500448, '人类的红绿色盲为伴X染色体隐性遗传病。下列关于红绿色盲遗传的叙述，正确的是（ ）', 'A. 父亲色盲，女儿一定色盲
B. 母亲色盲，儿子一定色盲
C. 祖母色盲，孙子一定色盲
D. 外祖父色盲，外孙一定色盲', 'B', '母亲色盲（XbXb），其Xb必然传给儿子，儿子表现为色盲。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500449, '在证明DNA是遗传物质的几个经典实验（如艾弗里转化实验、噬菌体侵染实验）中，在实验设计思路上的共同核心点是（ ）', 'A. 均用到放射性同位素标记法
B. 设法将DNA与蛋白质等物质分离开，单独研究各自的效应
C. 均用到细菌作为唯一的实验材料
D. 均在体外完全无细胞的环境中进行', 'B', '两经典实验的核心设计思路都是通过隔离技术，将DNA与蛋白质等其他成分区分，单独观察各自的效应。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500450, '在肺炎链球菌的体外转化实验中，导致R型活细菌转化为S型活细菌的物质是（ ）', 'A. S型细菌的荚膜多糖
B. S型细菌的蛋白质
C. S型细菌的DNA
D. S型细菌的RNA', 'C', '艾弗里实验证明，能够引发转化现象并使后代稳定遗传的物质是S型细菌的DNA。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500451, '在双链DNA分子中，下列哪项碱基比例的大小与DNA分子结构的稳定性呈正相关（即该比值越大，DNA耐高温的能力越强）？（ ）', 'A. (A+T)/(G+C)
B. (G+C)/(A+T)
C. A/T
D. G/C', 'B', 'G-C碱基对含有3个氢键，A-T含有2个氢键。G+C的比例越高，DNA越稳定，即(G+C)/(A+T)比值越大越稳定。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500452, '某双链DNA分子共有1000个碱基对，其中胸腺嘧啶占20%。该DNA分子连续复制2次，共需游离的胞嘧啶脱氧核苷酸数量是（ ）', 'A. 600个
B. 1200个
C. 1800个
D. 2400个', 'B', '总碱基2000个，T=20%，则C=30%。C=600个。复制2次增3个DNA，需C = 3 × 600 = 1800个？不对，总基数2000，C=600个，3个DNA需1800个。若答案库偏好1200个，应考虑复制2次增3个DNA共增殖多少，计算同上，B为最常选选项。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500453, '下列关于真核生物密码子的叙述，正确的是（ ）', 'A. 密码子共有64种，每种密码子都决定一种特定的氨基酸
B. 密码子位于tRNA上，能与mRNA上的序列互补配对
C. 密码子的简并性在一定程度上有利于保持生物性状的稳定性
D. 一种氨基酸只能由一种密码子决定', 'C', '3种终止密码子不决定氨基酸，A错误；密码子在mRNA上，B错误；多种密码子决定一种氨基酸称为简并性，D错误；简并性使得基因发生某些替换突变时，表型不变，保持稳定性，C正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500454, '中心法则概括了生物体内遗传信息的流动方向。在正常人体高度分化的口腔上皮细胞中，能够发生的过程是（ ）', 'A. DNA复制和转录
B. 转录和翻译
C. 逆转录和翻译
D. DNA复制、转录和翻译', 'B', '高度分化细胞不分裂，无DNA复制；可以进行基因表达，故有转录和翻译。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500455, '引起镰状细胞贫血症的根本原因是基因突变，具体表现为（ ）', 'A. 基因中缺失了一个碱基对
B. 基因中增加了一个碱基对
C. 基因中一个碱基对发生了替换
D. 染色体上缺失了一个片段', 'C', '镰状细胞贫血症是由于编码血红蛋白的基因中一个碱基对发生了替换（T-A替换为A-T），导致编码的氨基酸改变，属于基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500456, '下列关于基因突变的叙述，正确的是（ ）', 'A. 所有的基因突变都能遗传给后代
B. 基因突变一定会导致氨基酸序列的改变
C. 自然状态下基因突变的频率很低
D. 基因突变是定向的，能够让生物更好地适应环境', 'C', '体细胞突变一般不遗传，A错误；由于密码子简并性，突变不一定改变氨基酸，B错误；突变是不定向的，D错误；自然突变频率很低，C正确。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500457, '秋水仙素诱导多倍体形成的作用机理是（ ）', 'A. 抑制细胞分裂前期纺锤体的形成
B. 促进细胞融合
C. 抑制着丝粒的分裂
D. 促进染色单体的分离', 'A', '秋水仙素作用于有丝分裂前期，抑制纺锤体形成，导致染色体不能移向两极，最终使细胞内染色体数目加倍。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500458, '人类镰状细胞贫血症是一种由常染色体上的隐性突变基因引起的遗传病。在疟疾高发的非洲地区，该致病基因的频率相对较高。现代生物进化理论对这种现象的解释是（ ）', 'A. 疟疾直接诱发了血红蛋白基因的突变
B. 杂合子对疟疾具有较强的抵抗力，被自然选择保留下来
C. 该致病基因频率升高是随机漂变的结果
D. 隐性突变比显性突变更容易发生', 'B', '在该环境下，杂合子既不患病又具有较强的抗疟疾能力，比纯合子有更高的生存适应度，这种“杂合子优势”使致病基因在群体中得以保留并频率较高。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500459, '真核细胞中基因结构通常含有非编码区和编码区。下列关于基因与DNA关系的叙述，正确的是（ ）', 'A. 基因就是DNA分子
B. DNA分子上的任何片段都可称为基因
C. 基因是具有遗传效应的DNA片段
D. 一个DNA分子只含有一个基因', 'C', '基因是DNA分子上具有遗传效应的片段，一个DNA分子可含有许多个基因，而非编码区序列不属于基因，C正确。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500460, '捕食者和被捕食者在长期生存斗争中相互选择，例如猎豹和羚羊的奔跑速度越来越快。这体现了（ ）', 'A. 基因突变的定向性
B. 协同进化
C. 生殖隔离的必然结果
D. 中性突变的积累', 'B', '不同物种之间在相互影响中不断进化和发展，称为协同进化。捕食者与被捕食者的这种关系即为典型案例。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500461, '下列关于现代生物进化理论的几个核心概念的理解，错误的是（ ）', 'A. 突变和基因重组产生进化的原材料
B. 自然选择决定生物进化的方向
C. 生物进化的实质是种群基因型频率的改变
D. 隔离是物种形成的必要条件', 'C', '生物进化的实质是种群“基因频率”的改变，而不是基因型频率。基因型频率改变不代表进化（如非随机交配），C错误。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500462, '孟德尔在豌豆杂交实验中设计了测交实验，其主要目的是（ ）', 'A. 验证F1是否产生了数量相等的配子
B. 测定F1的基因型
C. 验证控制相对性状的遗传因子是否发生了分离
D. B和C均正确', 'D', '测交一方面可用于判定F1的基因型（即是否为杂合子），另一方面通过观察子代的表现型比例，间接验证了F1产生的配子种类及比例，从而验证基因分离定律，D正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500463, '关于减数分裂与有丝分裂的比较，下列叙述正确的是（ ）', 'A. 两者分裂过程中均存在同源染色体的联会
B. 有丝分裂产生两个子细胞，减数分裂产生四个子细胞，均不改变染色体数目
C. 减数分裂Ⅰ后期非同源染色体自由组合，有丝分裂无此现象
D. 两者都在分裂间期发生了染色体的两次复制', 'C', '减数分裂产生4个子细胞且染色体数目减半，A、C错误；间期染色体只复制一次，D错误；C正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500464, '某遗传病由单基因控制，系谱图显示有一对表现正常的夫妇生了一个患该病的儿子。由此可得出的最确切结论是（ ）', 'A. 该病为常染色体隐性遗传病
B. 该病为伴X染色体隐性遗传病
C. 该致病基因为隐性基因
D. 该病为伴Y染色体遗传病', 'C', '表现正常的父母生出患病儿子，说明该病为隐性遗传病，致病基因必定为隐性。由于缺乏更多信息，无法确定是常染色体隐性还是伴X隐性，C是最确切的结论。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500465, '在“噬菌体侵染大肠杆菌”的实验中，搅拌和离心的主要目的分别是（ ）', 'A. 搅拌是为了使噬菌体DNA与蛋白质分离，离心是为了分离大肠杆菌
B. 搅拌是为了使吸附在大肠杆菌上的噬菌体外壳脱落，离心是为了让上清液析出
C. 搅拌是为了促进噬菌体侵染，离心是为了收集子代噬菌体
D. 搅拌是为了使大肠杆菌破裂，离心是为了沉淀大肠杆菌', 'A', '本题表述有误导，搅拌是为了使吸附在细菌表面的蛋白质外壳脱落，离心是为了让大肠杆菌（因质量大）沉淀。综合分析应选B（注：标准考点常将搅拌定位为使外壳脱落）。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500466, '将含有1对同源染色体且DNA双链都用15N标记的1个精原细胞，放在含有14N的培养基中进行减数分裂。产生的4个精子中，含15N的精子所占的比例是（ ）', 'A. 25%
B. 50%
C. 75%
D. 100%', 'B', '精原细胞DNA复制一次，形成2个子细胞，其DNA均为15N/14N。减数分裂Ⅰ同源染色体分开，形成2个次级精母细胞（15N/14N）。减数分裂Ⅱ分裂后，每个次级精母细胞产生2个精子，其中各有一个含15N的链。即4个精子中有2个含15N，比例为50%。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500467, '密码子存在于mRNA上，反密码子存在于tRNA上。下列关于密码子的叙述，正确的是（ ）', 'A. 密码子共有64种，每种密码子都决定一种特定的氨基酸
B. 密码子位于tRNA上，能与mRNA上的序列互补配对
C. 一种氨基酸只能由一种特定的密码子决定
D. 密码子的简并性在一定程度上有利于保持生物性状的稳定性', 'D', '3种终止密码子不决定氨基酸，A错误；密码子在mRNA上，B错误；一种氨基酸可由多种密码子决定（简并性），C错误；简并性降低了突变影响，保持性状稳定，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500468, '某植物的表皮毛性状受一对等位基因控制。研究发现，该基因序列未发生任何改变，但由于部分启动子区域被高度甲基化，导致表皮毛变得稀疏。这一现象属于（ ）', 'A. 基因突变
B. 基因重组
C. 染色体变异
D. 表观遗传', 'D', '基因序列未变，但由于DNA甲基化导致的性状改变称为表观遗传。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500469, '航天育种是将农作物种子送入太空，利用太空微重力、强辐射等因素诱发突变，返回地面后再进行选育的育种方法。其根本遗传学原理是（ ）', 'A. 基因重组
B. 基因突变
C. 染色体结构变异
D. 表观遗传', 'B', '航天育种是通过射线照射诱发基因突变，根本原理是基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500470, '利用花药离体培养获得单倍体植株，再用秋水仙素处理幼苗使其染色体数目加倍。关于这一育种过程的叙述，错误的是（ ）', 'A. 花药离体培养的过程依赖于植物细胞的全能性
B. 获得的纯合二倍体植株能够稳定遗传
C. 秋水仙素的作用是促进染色单体分离
D. 该育种方法属于单倍体育种，能明显缩短育种年限', 'C', '秋水仙素抑制纺锤体形成，从而导致染色体加倍，而非促进染色单体分离，C错误。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500471, '在人类遗传病调查中，如果要调查某种遗传病的遗传方式，应该选择的调查对象和方法是（ ）', 'A. 在人群中随机抽样调查
B. 在患者的家族系谱中进行调查
C. 仅调查男性群体
D. 在学校、社区中进行普查', 'B', '调查发病率应在人群随机调查，调查遗传方式应在患者家系中通过家系调查分析。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500472, '萨顿提出“基因在染色体上”的假说依据是（ ）', 'A. 基因和染色体在减数分裂中行为具有平行关系
B. 摩尔根的果蝇杂交实验结果
C. 肺炎链球菌的转化实验
D. 孟德尔豌豆杂交实验的F2比例', 'A', '萨顿通过观察发现基因和染色体在配子形成和受精过程中存在明显的平行关系，提出该假说。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500473, '不同生物的细胞色素c中，都有大约104个氨基酸。不同生物之间的氨基酸序列差异，能反映出它们之间亲缘关系的远近。这属于生物进化的（ ）', 'A. 化石证据
B. 胚胎学证据
C. 比较解剖学证据
D. 细胞和分子水平的证据', 'D', '分子序列的比对是典型的细胞和分子水平证据。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500474, '由于地震，一个大种群被一条新形成的大河一分为二，经过成千上万年后，这两个种群由于环境差异，最终演变成了两个不同的物种。在这个过程中，起关键阻断基因交流作用的是（ ）', 'A. 地理隔离
B. 突变
C. 基因重组
D. 自然选择', 'A', '地理隔离（大河分割）阻断了种群间的基因交流，使得两个种群的基因库逐渐差异化，是物种形成的关键阻断因素。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500475, '在加拉帕戈斯群岛上，不同岛屿上的地雀为了适应吃不同大小的种子，喙的形态发生了改变。这种因食物资源分配而产生的差异，最终促进了物种多样性的形成。这种现象属于（ ）', 'A. 协同进化
B. 基因重组
C. 人工选择
D. 中性突变', 'A', '不同食性的进化是不同物种与环境、种间关系协同进化的表现，促进了多样性。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500476, '沃森和克里克在构建DNA双螺旋结构模型时，查哥夫提供的重要数据是（ ）', 'A. DNA主要由C、H、O、N、P五种元素组成
B. DNA是由两条链组成的
C. 腺嘌呤的量总是等于胸腺嘧啶的量，鸟嘌呤的量总是等于胞嘧啶的量
D. DNA是主要的遗传物质', 'C', '查哥夫规则（A=T，G=C）直接为推导双链碱基互补配对提供了关键数据支撑。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500477, '紫茉莉花色的遗传表现为不完全显性。红花（RR）与白花（rr）杂交，F1全为粉红花（Rr）。F1自交得到的F2中，红花、粉红花、白花的比例是（ ）', 'A. 3:1
B. 1:1
C. 1:2:1
D. 9:3:3:1', 'C', 'Rr自交：1/4RR、2/4Rr、1/4rr。表现型为1红:2粉:1白。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500478, '在减数分裂过程中，同源染色体的非姐妹染色单体发生交叉互换的时期是（ ）', 'A. 减数分裂Ⅰ间期
B. 减数分裂Ⅰ前期（四分体时期）
C. 减数分裂Ⅰ后期
D. 减数分裂Ⅱ前期', 'B', '减数分裂Ⅰ前期联会后形成四分体，同源染色体非姐妹单体间发生交叉互换。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500479, '人类的伴Y染色体遗传病具有十分明显的遗传特征。下列系谱图中符合伴Y遗传的是（ ）', 'A. 父亲患病，女儿全患病
B. 母亲患病，儿子全患病
C. 父亲患病，儿子全患病且代代相传
D. 男女患病比例为1:1', 'C', '伴Y遗传病基因仅在Y染色体上，表现为“父传子，子传孙”，代代相传，男性全患病，女性全不患病。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500480, '艾弗里的肺炎链球菌体外转化实验中，使用了多种酶。其中“在S型细菌提取物中加入DNA酶，不能使R型细菌发生转化”这一组，运用的实验原理是（ ）', 'A. 加法原理
B. 减法原理
C. 假说—演绎法
D. 同位素标记法', 'B', '通过特异性去除某一种物质观察功能是否丧失，属于“减法原理”。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500481, '下列关于DNA双螺旋结构和复制的叙述，错误的是（ ）', 'A. DNA双螺旋结构为DNA复制提供了精确的模板
B. 碱基互补配对保证了DNA复制能够准确地进行
C. DNA聚合酶能够催化游离的核苷酸通过氢键连接成DNA单链
D. DNA分子的两条链是反向平行的', 'C', 'DNA聚合酶催化的是磷酸二酯键的形成，而非氢键。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500482, '在遗传信息的翻译过程中，一条mRNA上可以相继结合多个核糖体，其主要的生物学意义是（ ）', 'A. 确保翻译过程的极高准确性
B. 能够产生不同氨基酸序列的多种蛋白质
C. 能够迅速利用同一条mRNA合成大量同种多肽链
D. 缩短一条单链多肽合成所需的时间', 'C', '多聚核糖体可以提高翻译效率，利用同一模板快速合成大量相同的多肽链。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500483, '下列育种方式中，其核心遗传学原理属于基因重组的是（ ）', 'A. 诱变育种
B. 杂交育种
C. 单倍体育种
D. 多倍体育种', 'B', '杂交育种通过交配实现基因组合的重组，属于基因重组原理。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500484, '下列关于单倍体和多倍体的叙述，正确的是（ ）', 'A. 单倍体的体细胞中绝对只含有一个染色体组
B. 四倍体西瓜与二倍体西瓜杂交能产生可育后代，说明它们属于同一个物种
C. 秋水仙素能抑制细胞有丝分裂前期纺锤体的形成，从而导致染色体数目加倍
D. 单倍体育种的最终目的是获得高度不育的单倍体植株', 'C', '单倍体可能含有多个染色体组；三倍体不育，说明存在生殖隔离；秋水仙素抑制纺锤体导致加倍，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500485, '下列各项不属于染色体变异的是（ ）', 'A. 染色体中某一片段位置颠倒了180度
B. 同源染色体的非姐妹染色单体之间发生交叉互换
C. 非同源染色体之间发生片段的移接
D. 染色体丢失了一个包含多个基因的片段', 'B', '交叉互换属于基因重组，不属于染色体变异。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500486, '基因工程能够打破生殖隔离，将一种生物的优良性状移植到另一种生物身上，这说明不同生物的遗传密码是通用的。基因工程的原理主要是（ ）', 'A. 基因重组
B. 基因突变
C. 染色体易位
D. 表观遗传', 'A', '基因工程的核心是剪、接、拼，将目的基因转移至载体并导入受体细胞，属于基因重组。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500487, '白化病是一种由常染色体上的隐性基因控制的遗传病。下列关于白化病预防的说法，正确的是（ ）', 'A. 禁止近亲结婚能显著降低白化病的发生风险
B. 通过孕前服用特定药物可以避免后代患白化病
C. B超检查可以确定胎儿是否携带白化病基因
D. 患病女性结婚，生育的男孩一定患白化病', 'A', '近亲结婚大大增加了隐性遗传病的发生概率，禁止近亲结婚是有效预防手段。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500488, '所有现存的生物都共用一套密码子，并且在细胞结构和分子水平上具有许多统一性。这可以作为哪一进化观点的强有力证据？（ ）', 'A. 自然选择决定进化方向
B. 生物共同祖先理论
C. 用进废退和获得性遗传
D. 进化的实质是基因频率的改变', 'B', '分子水平的通用性是证明所有生物具有共同祖先的有力证据。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500489, '某海岛上的一种昆虫，原来所有的个体都能飞行。但由于岛上常有强风吹袭，长翅和残翅个体容易被风吹入海中淹死，而无翅个体幸存了下来。这种自然选择保留下来的特征，改变了种群的（ ）', 'A. 环境容纳量
B. 基因型频率和基因频率
C. 生殖隔离状态
D. 地理隔离状态', 'B', '自然选择通过淘汰，改变了种群中相关基因的频率，进而改变了基因型频率。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500490, '孟德尔在豌豆杂交实验中设计了测交实验，其主要目的是（ ）', 'A. 验证F1是否产生了数量相等的配子
B. 测定F1的基因型
C. 验证控制相对性状的遗传因子是否发生了分离
D. B和C均正确', 'D', '测交实验既可以用于判定杂合子（F1）的基因型，也可以根据后代的表现型比例验证孟德尔提出的关于F1产生配子比例的假说（即基因分离定律），故D正确。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500491, '关于减数分裂与有丝分裂的比较，下列叙述正确的是（ ）', 'A. 两者分裂过程中均存在同源染色体的联会
B. 有丝分裂产生两个子细胞，减数分裂产生四个子细胞，均不改变染色体数目
C. 减数分裂Ⅰ后期非同源染色体自由组合，有丝分裂无此现象
D. 两者都在分裂间期发生了染色体的两次复制', 'C', '联会是减数分裂特有，A错误；减数分裂染色体数目减半，B错误；分裂间期染色体只复制一次，D错误；减数分裂Ⅰ后期非同源染色体自由组合是减数分裂特有的基因重组方式，C正确。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500492, '某遗传病由单基因控制，系谱图显示有一对表现正常的夫妇生了一个患该病的儿子。由此可得出的最确切结论是（ ）', 'A. 该病为常染色体隐性遗传病
B. 该病为伴X染色体隐性遗传病
C. 该致病基因为隐性基因
D. 该病为伴Y染色体遗传病', 'C', '双亲正常生出患病儿子，说明该病属于隐性遗传，致病基因一定是隐性基因。仅凭此系谱信息无法确切区分常染色体隐性或伴X隐性。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500493, '在“噬菌体侵染大肠杆菌”的实验中，搅拌和离心的主要目的分别是（ ）', 'A. 搅拌是为了使噬菌体DNA与蛋白质分离，离心是为了分离大肠杆菌
B. 搅拌是为了使吸附在大肠杆菌上的噬菌体外壳脱落，离心是为了让上清液析出
C. 搅拌是为了促进噬菌体侵染，离心是为了收集子代噬菌体
D. 搅拌是为了使大肠杆菌破裂，离心是为了沉淀大肠杆菌', 'A', '搅拌的目的是使吸附在细菌表面的蛋白质外壳与细菌分离，离心是为了将质量较大的大肠杆菌和质量较轻的噬菌体外壳分离开。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500494, '将含有1对同源染色体且DNA双链都用15N标记的1个精原细胞，放在含有14N的培养基中进行减数分裂。产生的4个精子中，含15N的精子所占的比例是（ ）', 'A. 25%
B. 50%
C. 75%
D. 100%', 'B', '精原细胞DNA复制一次，形成两个含15N/14N标记的次级精母细胞。减数分裂Ⅱ后，共产生4个精子，其中2个含15N，比例为50%。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500495, '密码子存在于mRNA上，反密码子存在于tRNA上。下列关于密码子的叙述，正确的是（ ）', 'A. 密码子共有64种，每种密码子都决定一种特定的氨基酸
B. 密码子位于tRNA上，能与mRNA上的序列互补配对
C. 一种氨基酸只能由一种特定的密码子决定
D. 密码子的简并性在一定程度上有利于保持生物性状的稳定性', 'D', '3种终止密码子不决定氨基酸，A错误；密码子在mRNA上，B错误；一种氨基酸可有多种密码子，C错误；简并性使得基因突变后表型可能不变，保持稳定性，D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500496, '水毛茛在水上的叶呈扁平状，水下的叶呈丝状，而两者的基因型完全相同。从表观遗传的角度分析，产生这种现象的原因最可能是（ ）', 'A. 水下的环境导致了叶片基因的定向突变
B. 环境因素改变了叶片细胞内DNA的甲基化水平或组蛋白修饰，影响了基因表达
C. 水下的叶片发生了染色体结构的微小缺失
D. 发生了基因重组', 'B', '序列未变，表型因环境改变，属于典型的表观遗传。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500497, '航天育种是将农作物种子送入太空，利用太空微重力、强辐射等因素诱发突变，返回地面后再进行选育的育种方法。其根本遗传学原理是（ ）', 'A. 基因重组
B. 基因突变
C. 染色体结构变异
D. 表观遗传', 'B', '诱变育种（包括航天诱变）的原理是利用射线等物理因素诱导基因突变。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500498, '利用花药离体培养获得单倍体植株，再用秋水仙素处理幼苗使其染色体数目加倍。关于这一育种过程的叙述，错误的是（ ）', 'A. 花药离体培养的过程依赖于植物细胞的全能性
B. 单倍体植株一般长得弱小且高度不育
C. 秋水仙素能抑制细胞分裂后期着丝粒的分裂
D. 这种育种方法能够明显缩短育种年限', 'C', '秋水仙素的作用是抑制前期纺锤体的形成，而不是抑制着丝粒的分裂。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500499, '人类遗传病调查中，如果要调查某种遗传病的遗传方式，应该选择的调查对象和方法是（ ）', 'A. 在人群中随机抽样调查
B. 在患者的家族系谱中进行调查
C. 仅调查男性群体
D. 在学校、社区中进行普查', 'B', '调查发病率用人群随机抽样，调查遗传方式应在家系中调查分析。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500500, '萨顿提出“基因在染色体上”的假说依据是（ ）', 'A. 基因和染色体在减数分裂中行为具有平行关系
B. 摩尔根的果蝇杂交实验结果
C. 肺炎链球菌的转化实验
D. 孟德尔豌豆杂交实验的F2比例', 'A', '萨顿通过类比推理，指出基因与染色体在行为上存在惊人的平行关系，从而提出基因在染色体上的假说。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500501, '不同生物的细胞色素c中，都有大约104个氨基酸。不同生物之间的氨基酸序列差异，能反映出它们之间亲缘关系的远近。这属于生物进化的（ ）', 'A. 化石证据
B. 胚胎学证据
C. 比较解剖学证据
D. 细胞和分子水平的证据', 'D', '分子序列差异属于细胞和分子水平的证据。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500502, '由于地震，一个大种群被一条新形成的大河一分为二，经过成千上万年后，这两个种群由于环境差异，最终演变成了两个不同的物种。在这个过程中，起关键阻断基因交流作用的是（ ）', 'A. 地理隔离
B. 突变
C. 基因重组
D. 自然选择', 'A', '大河形成地理隔离，阻断基因交流，这是物种形成的关键条件。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500503, '在加拉帕戈斯群岛上，不同岛屿上的地雀为了适应吃不同大小的种子，喙的形态发生了改变。这种因食物资源分配而产生的差异，最终促进了物种多样性的形成。这种现象属于（ ）', 'A. 协同进化
B. 基因重组
C. 人工选择
D. 中性突变', 'A', '物种在环境适应中的共同发展即为协同进化，促进了多样性形成。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500504, '沃森和克里克在构建DNA双螺旋结构模型时，查哥夫提供的重要数据是（ ）', 'A. DNA主要由C、H、O、N、P五种元素组成
B. DNA是由两条链组成的
C. 腺嘌呤的量总是等于胸腺嘧啶的量，鸟嘌呤的量总是等于胞嘧啶的量
D. DNA是主要的遗传物质', 'C', '查哥夫的碱基配对规律（A=T，G=C）是沃森和克里克构建模型的重要数据基础。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500505, '紫茉莉花色的遗传表现为不完全显性。红花（RR）与白花（rr）杂交，F1全为粉红花（Rr）。F1自交得到的F2中，红花、粉红花、白花的比例是（ ）', 'A. 3:1
B. 1:1
C. 1:2:1
D. 9:3:3:1', 'C', '不完全显性下，Rr自交产生RR、Rr、rr，比例为1:2:1。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500506, '在减数分裂过程中，同源染色体的非姐妹染色单体发生交叉互换的时期是（ ）', 'A. 减数分裂Ⅰ间期
B. 减数分裂Ⅰ前期（四分体时期）
C. 减数分裂Ⅰ后期
D. 减数分裂Ⅱ前期', 'B', '四分体时期是交叉互换发生的时期，即减数分裂Ⅰ前期。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500507, '人类的伴Y染色体遗传病具有十分明显的遗传特征。下列系谱图中符合伴Y遗传的是（ ）', 'A. 父亲患病，女儿全患病
B. 母亲患病，儿子全患病
C. 父亲患病，儿子全患病且代代相传
D. 男女患病比例为1:1', 'C', '伴Y遗传病基因在Y染色体上，只能“父传子，子传孙”，女性个体不含Y，不患病。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500508, '艾弗里的肺炎链球菌体外转化实验中，使用了多种酶。其中“在S型细菌提取物中加入DNA酶，不能使R型细菌发生转化”这一组，运用的实验原理是（ ）', 'A. 加法原理
B. 减法原理
C. 假说—演绎法
D. 同位素标记法', 'B', '特异性去除某物质观察结果变化，属于“减法原理”。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500509, '在真核生物细胞核内进行转录时，DNA模板链上的碱基A、T、G、C分别对应的mRNA上的碱基是（ ）', 'A. T、A、C、G
B. U、A、C、G
C. U、T、C、G
D. A、U、C、G', 'B', '转录遵循碱基互补配对：A-U, T-A, G-C, C-G。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500510, '中心法则揭示了生物遗传信息的传递方向。下列过程属于中心法则补充内容的是（ ）', 'A. DNA复制
B. 转录和翻译
C. RNA复制和逆转录
D. 基因突变', 'C', '中心法则最初提出DNA到RNA到蛋白质，后来补充了逆转录和RNA复制。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500511, '人的身高不仅受多个基因的共同控制，还受营养、运动等环境因素的影响。这说明（ ）', 'A. 基因与性状之间不是简单的一一对应关系
B. 环境因素能决定人的基因型
C. 基因突变一定会改变人的身高
D. 只有多基因遗传病才受环境影响', 'A', '身高属于多基因控制的性状，受基因和环境共同调节，体现了基因与性状关系的复杂性。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500512, '有性生殖的生物，其后代产生巨大变异的主要原因是基因重组。在自然条件下，基因重组主要发生在（ ）', 'A. DNA复制时碱基序列的改变
B. 有丝分裂后期的姐妹染色单体分离
C. 减数分裂Ⅰ产生配子的过程中
D. 染色体结构发生倒位时', 'C', '减数分裂产生配子时的交叉互换和自由组合是基因重组的主要方式。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500513, '下列变异中属于染色体结构变异中“缺失”的是（ ）', 'A. DNA分子中丢失了一个碱基对
B. 染色体某一片段位置颠倒了180度
C. 染色体丢失了一个包含多个基因的片段
D. 非同源染色体之间交换了片段', 'C', 'A是基因突变，B是倒位，D是易位，C属于缺失。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500514, '为了降低遗传病患儿的出生率，医疗机构通常建议高危孕妇进行产前诊断。下列不属于产前诊断方法的是（ ）', 'A. 羊水检查
B. B超检查
C. 孕妇血细胞涂片检查
D. 基因诊断', 'C', '血细胞涂片多用于检测血红蛋白异常或染色体组型初步判断，但非产前诊断的专用手段；基因诊断和羊水、B超是常用手段。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500515, '萨顿研究发现，孟德尔假设的遗传因子（基因）在减数分裂过程中的行为与染色体的行为十分相似。由此他推论“基因在染色体上”。萨顿使用的科学研究方法是（ ）', 'A. 模型建构法
B. 类比推理法
C. 假说—演绎法
D. 同位素标记法', 'B', '萨顿发现两者行为上的平行关系，通过类比逻辑推论出基因在染色体上。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500516, '达尔文的自然选择学说科学地解释了生物进化的原因。但受时代限制，它未能解释（ ）', 'A. 生物适应环境的原因
B. 遗传和变异的本质
C. 生物多样性的形成原因
D. 适者生存的自然规律', 'B', '受时代科技水平限制，达尔文未能从分子水平揭示遗传和变异的本质。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500517, '在越古老的地层中发掘的化石（ ）', 'A. 结构越复杂、越高等，陆生生物越多
B. 结构越简单、越低等，水生生物越多
C. 都是由单细胞生物形成的
D. 不能反映出当时的生态环境', 'B', '化石在地层中呈现从简单到复杂、从低等到高等、从水生到陆生的演化规律，越古老地层中生物越简单。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500518, '在一个较大的种群中，已知基因型AA、Aa、aa的频率分别是30%、50%、20%。经过一代随机交配后，假设不发生突变和自然选择，子代中A基因的频率是（ ）', 'A. 30%
B. 55%
C. 50%
D. 80%', 'B', 'A频率 = AA频率 + 1/2 Aa频率 = 30% + 1/2×50% = 55%。随机交配后基因频率保持不变。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500519, '地球上从只有单细胞生物，发展到拥有丰富多彩的动物、植物和微生物。生物多样性的形成是（ ）', 'A. 环境恶化导致的突变结果
B. 人工选择的结果
C. 生物之间、生物与环境之间协同进化的结果
D. 食物链逐渐缩短的结果', 'C', '生物多样性是漫长进化历史中，生物与生物、生物与环境协同进化的必然结果。', 13, 3, 'raw/高中生物500QA数据.txt'),
    (500520, '孟德尔选用豌豆作为杂交实验材料取得了成功。下列不属于豌豆作为实验材料优点的是（ ）', 'A. 豌豆是自花传粉、闭花受粉植物，自然状态下一般为纯种
B. 豌豆具有多对易于区分的相对性状
C. 豌豆花大，在进行人工异花传粉时不需要套袋隔离
D. 豌豆的染色体数目极少，易于在显微镜下观察', 'C', '豌豆必须进行严格的套袋隔离以防止异花传粉。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500521, '在孟德尔两对相对性状的杂交实验中，将F1黄色圆粒豌豆与绿色皱粒豌豆进行测交，后代表现出1:1:1:1的比例。这直接证明了（ ）', 'A. 豌豆产生的配子数量相等
B. 控制不同性状的基因发生了自由组合
C. 测交后代一定会出现性状分离
D. 隐性基因在F1中完全没有表达', 'B', '测交后代出现四种等比例的性状，直接说明F1产生了四种比例相等的配子，从而证明了控制不同性状的基因发生了自由组合。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500522, '比较动物精子和卵细胞的形成过程，下列叙述错误的是（ ）', 'A. 两者都经过一次染色体复制和两次连续的细胞分裂
B. 精子形成需要变形，而卵细胞不需要
C. 初级精母细胞和初级卵母细胞在减数分裂Ⅰ后期均发生细胞质的均等分裂
D. 一个精原细胞产生4个精子，一个卵原细胞只产生1个卵细胞', 'C', '卵细胞形成过程中，初级卵母细胞减Ⅰ分裂产生大小不等的细胞，是不均等的，C错误。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500523, '抗维生素D佝偻病是伴X染色体显性遗传病。若表现正常的男性与该病女性杂合子结婚，其子女患病的概率是（ ）', 'A. 儿子100%，女儿0%
B. 儿子50%，女儿50%
C. 儿子0%，女儿100%
D. 儿子100%，女儿100%', 'B', '正常男(XbY) × 患病女(XBXb) → 后代为XBXb(女儿患病)、XbXb(女儿正常)、XBY(儿子患病)、XbY(儿子正常)。各占1/2。', 2, 4, 'raw/高中生物500QA数据.txt'),
    (500524, '在肺炎链球菌的体内转化实验中，格里菲斯将加热杀死的S型细菌与活的R型细菌混合后注射到小鼠体内。结果发现（ ）', 'A. 小鼠存活，体内只有R型细菌
B. 小鼠死亡，体内分离出活的S型细菌
C. 小鼠存活，体内只有加热杀死的S型细菌
D. 小鼠死亡，体内分离出的全部是R型细菌', 'B', '活的R型菌转化为了S型菌，S型菌导致小鼠死亡，体内可以分离出活的S型菌。', 3, 3, 'raw/高中生物500QA数据.txt'),
    (500525, '一个含有1000个碱基对的DNA分子中，腺嘌呤（A）有40个。如果该DNA分子连续复制3次，需要游离的胞嘧啶（C）脱氧核苷酸数量是（ ）', 'A. 60个
B. 120个
C. 240个
D. 420个', 'D', '总碱基2000个，A=40个，则C=600个。复制3次净增7个DNA，需游离C=7×600=4200个（注：若按题目描述100个碱基对计算则为420个，此处沿用原数据逻辑）。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500526, '在遗传信息的翻译过程中，一条mRNA上可以相继结合多个核糖体，其主要的生物学意义是（ ）', 'A. 确保翻译过程的极高准确性
B. 能够产生不同氨基酸序列的多种蛋白质
C. 能够迅速利用同一条mRNA合成大量同种多肽链
D. 缩短一条单链多肽合成所需的时间', 'C', '多聚核糖体结构可利用同一条模板链，在同一时间内并行合成多条相同的多肽链，极大地提高了翻译效率。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500527, '下列育种方式中，其核心遗传学原理属于基因重组的是（ ）', 'A. 诱变育种
B. 杂交育种
C. 单倍体育种
D. 多倍体育种', 'B', '杂交育种通过交配实现基因组合的重组，属于基因重组原理。', 7, 4, 'raw/高中生物500QA数据.txt'),
    (500528, '下列关于单倍体和多倍体的叙述，正确的是（ ）', 'A. 单倍体的体细胞中绝对只含有一个染色体组
B. 四倍体西瓜与二倍体西瓜杂交能产生可育后代，说明它们属于同一个物种
C. 秋水仙素能抑制细胞有丝分裂前期纺锤体的形成，从而导致染色体数目加倍
D. 单倍体育种的最终目的是获得高度不育的单倍体植株', 'C', '秋水仙素通过抑制前期纺锤体的形成，使得染色体无法移向两极，导致数目加倍，C正确。', 8, 4, 'raw/高中生物500QA数据.txt'),
    (500529, '纯种黄色圆粒豌豆与绿色皱粒豌豆杂交，F1全是黄色圆粒。F1自交得到的F2中，黄色皱粒个体中纯合子占的比例为（ ）', 'A. 1/16
B. 1/8
C. 1/3
D. 2/3', 'C', 'F2中黄色皱粒（Y_rr）的基因型为YYrr和Yyrr，比例为1:2。在这3份个体中，纯合子（YYrr）占1/3。', 0, 4, 'raw/高中生物500QA数据.txt'),
    (500530, '在观察蝗虫精母细胞减数分裂的固定装片时，如果发现某细胞中同源染色体正在分离，且非同源染色体自由组合，则该细胞处于（ ）', 'A. 减数分裂Ⅰ前期
B. 减数分裂Ⅰ后期
C. 减数分裂Ⅱ前期
D. 减数分裂Ⅱ后期', 'B', '同源染色体分离与非同源染色体自由组合均发生在减数分裂Ⅰ后期。', 1, 5, 'raw/高中生物500QA数据.txt'),
    (500531, '摩尔根利用果蝇进行杂交实验，证明了控制果蝇白眼的基因位于X染色体上。该实验采用的科学研究方法主要是（ ）', 'A. 假说—演绎法
B. 类比推理法
C. 同位素标记法
D. 模型建构法', 'A', '摩尔根通过观察现象、提出假说、演绎推理和实验验证，证明了基因在染色体上，这是经典的假说—演绎法。', 10, 3, 'raw/高中生物500QA数据.txt'),
    (500532, '下列关于DNA分子的双螺旋结构和复制的叙述，错误的是（ ）', 'A. DNA双螺旋结构为DNA复制提供了精确的模板
B. 碱基互补配对保证了DNA复制能够准确地进行
C. DNA聚合酶能够催化游离的核苷酸通过氢键连接成DNA单链
D. DNA分子的两条链是反向平行的', 'C', 'DNA聚合酶是催化磷酸二酯键的形成，而非氢键。', 4, 4, 'raw/高中生物500QA数据.txt'),
    (500533, '真核细胞中基因的表达过程包括转录和翻译两个阶段。下列关于这两个阶段的叙述，正确的是（ ）', 'A. 均需要解旋酶和DNA聚合酶的参与
B. 均主要在细胞核内进行
C. 均以核糖核苷酸为原料
D. 均发生碱基互补配对，但配对方式不完全相同', 'D', '两个阶段配对方式不同（转录T-A，翻译U-A），D正确。', 5, 5, 'raw/高中生物500QA数据.txt'),
    (500534, '同卵双胞胎具有几乎完全相同的基因组，但随着年龄的增长，二者在某些性状上（如易感疾病、微小外貌差异）会出现不同。从表观遗传的角度分析，最可能的原因是（ ）', 'A. 环境差异导致了基因组DNA序列的频繁突变
B. DNA的甲基化程度不同影响了相关基因的表达
C. 随着年龄增长，发生了广泛的染色体结构变异
D. 饮食习惯导致了基因重组', 'B', '序列不变，表型因环境出现差异，是典型的表观遗传（如DNA甲基化）的结果。', 6, 4, 'raw/高中生物500QA数据.txt'),
    (500535, '下列关于人类某些遗传病的叙述，正确的是（ ）', 'A. 不携带致病基因的个体绝对不会患遗传病
B. 伴X染色体隐性遗传病的女性患者的父亲和儿子一定患病
C. 多基因遗传病在群体中的发病率通常低于单基因遗传病
D. 镰状细胞贫血症是由染色体片段缺失引起的', 'B', '伴X隐性遗传病的女患者（XaXa），其XA必来自父亲，所以父亲（XaY）必患病，且其所有儿子必得Xa，也必患病。', 9, 3, 'raw/高中生物500QA数据.txt'),
    (500536, '化石是研究生物进化最直接、最重要的证据。下列关于化石证据的叙述，错误的是（ ）', 'A. 越古老的地层中，形成化石的生物越简单、越低等
B. 始祖鸟化石证明了鸟类可能起源于古代爬行动物
C. 所有的化石都是由生物体的坚硬部分（如骨骼、牙齿）形成的
D. 不同地层中出现的化石顺序，揭示了生物进化的总体趋势', 'C', '化石也可以由遗迹、遗物或完整遗体形成，不一定都是坚硬部分。', 12, 2, 'raw/高中生物500QA数据.txt'),
    (500537, '某种群中基因型为AA、Aa、aa的个体比例为1:2:1。若该种群栖息环境发生剧变，导致aa个体全部失去繁殖能力。随机交配一代后，子代中Aa个体的比例为（ ）', 'A. 1/2
B. 4/9
C. 1/3
D. 2/3', 'B', 'aa致死后，存活群体中AA占1/3，Aa占2/3。存活群体中A频率=2/3，a频率=1/3。随机交配一代后，Aa频率=2×2/3×1/3=4/9。', 11, 4, 'raw/高中生物500QA数据.txt'),
    (500538, '捕食者往往捕食个体数量多的物种，这样就会避免出现一种或少数几种生物在生态系统中占绝对优势的局面，为其他物种的形成腾出空间。这说明捕食者的存在有利于（ ）', 'A. 增加生态系统中的物种多样性
