    (500539, '已知某植物果实的长形（D）对圆形（d）为显性，红色（R）对黄色（r）为显性，两对基因独立遗传。将一株长形红果植株与一株圆形黄果植株杂交，子代为长形红果:长形黄果:圆形红果:圆形黄果 = 1:1:1:1。则长形红果亲本的基因型为（ ）', 'A. DdRr
